window.MUC_QUESTION_BANK=[{"id": "q-5498caf45ab49a", "type": "mcq", "prompt": "Why is the security boundary of a smart camera larger than the physical camera itself?", "answerHTML": "<p>B. Because security also depends on networks, cloud services, applications, and users<\/p><p>أمن الكاميرا بيعتمد كمان على الشبكة والخدمات والتطبيق والمستخدمين.<\/p>", "group": "4", "lecture": "1", "href": "lesson.html#slide-4", "options": ["Because cameras always have unlimited processing power", "Because security also depends on networks, cloud services, applications, and users", "Because a camera does not contain software", "Because only physical access matters"], "correct": 1, "explanation": "أمن الكاميرا بيعتمد كمان على الشبكة والخدمات والتطبيق والمستخدمين.", "persist": "q0", "week": 1}, {"id": "q-d876300ecfc35a", "type": "blank", "prompt": "A smart camera's security must consider the complete device-service _______.", "answerHTML": "<p><span dir=\"ltr\" style=\"display:block;margin:8px 0\"><span><strong>Answer: Ecosystem<\/strong><\/span><\/span><span dir=\"rtl\" style=\"display:block;margin:8px 0\">يعني النظام الكامل بكل أجزائه المرتبطة ببعض.<\/span><\/p>", "group": "4", "lecture": "1", "href": "lesson.html#slide-4", "week": 1}, {"id": "q-7e936b97bef649", "type": "case", "prompt": "Smart Camera — Cloud Service Outage", "answerHTML": "<p><span dir=\"ltr\" style=\"display:block;margin:8px 0\"><span><strong>Correct Answer (English):<\/strong><\/span><\/span><span dir=\"ltr\" style=\"display:block;margin:8px 0\">The affected component is the Cloud Service. The camera depends on remote services for certain functions, so a cloud failure may interrupt access to recordings even when the camera hardware is functioning.<\/span><span dir=\"rtl\" style=\"display:block;margin:8px 0\"><span><strong>الشرح بالعربي:<\/strong><\/span><\/span><span dir=\"rtl\" style=\"display:block;margin:8px 0\">الكاميرا شغالة، لكن الخدمة اللي بتعتمد عليها للوصول للتسجيلات مش متاحة. إذن المشكلة في <span><strong>Dependency<\/strong><\/span> خارج الجهاز نفسه.<\/span><span dir=\"ltr\" style=\"display:block;margin:8px 0\"><span><strong>Exam Keywords:<\/strong><\/span> Cloud Service, Remote Access, Dependency, Service Unavailability.<\/span><\/p>", "group": "4", "lecture": "1", "href": "lesson.html#slide-4", "context": "A smart security camera is functioning correctly, but its owner cannot access recordings because the remote cloud service is unavailable.", "questionsHTML": "<p dir=\"ltr\">Question: Identify the affected ecosystem component and explain why the camera may be affected even though its hardware is functioning.<\/p>", "week": 1}, {"id": "q-cd05e03cb5c292", "type": "mcq", "prompt": "Which component may aggregate data from multiple local IoT devices?", "answerHTML": "<p>B. Gateway / Edge<\/p><p>Gateway / Edge ممكن يجمع بيانات عدة أجهزة محلية.<\/p>", "group": "1-5", "lecture": "1", "href": "lesson.html#practice", "options": ["User Application", "Gateway / Edge", "Physical Actuator", "Device Memory"], "correct": 1, "explanation": "Gateway / Edge ممكن يجمع بيانات عدة أجهزة محلية.", "persist": "q1", "week": 1}, {"id": "q-0b62aef8bde3c6", "type": "mcq", "prompt": "Which component is associated with boot and configuration?", "answerHTML": "<p>A. Device Software<\/p><p>Boot وConfiguration من وظائف Device Software.<\/p>", "group": "1-5", "lecture": "1", "href": "lesson.html#practice", "options": ["Device Software", "Cloud Storage", "Connectivity", "User Application"], "correct": 0, "explanation": "Boot وConfiguration من وظائف Device Software.", "persist": "q2", "week": 1}, {"id": "q-bb188dc159f0d6", "type": "mcq", "prompt": "Which statement is correct about IoT security?", "answerHTML": "<p>C. The complete device-service ecosystem must be considered<\/p><p>لازم نأخذ النظام الكامل Device-Service Ecosystem بالحسبان.<\/p>", "group": "1-5", "lecture": "1", "href": "lesson.html#practice", "options": ["Only the physical device matters", "Only the network matters", "The complete device-service ecosystem must be considered", "Cloud services cannot affect device security"], "correct": 2, "explanation": "لازم نأخذ النظام الكامل Device-Service Ecosystem بالحسبان.", "persist": "q3", "week": 1}, {"id": "q-c98f0768c855d0", "type": "short", "prompt": "Q1. Which component collects temperature readings?", "answerHTML": "<p><strong>Answer:<\/strong> Sensor.<\/p>", "group": "6", "lecture": "1", "href": "lesson.html#slide-6", "context": "A smart environmental sensor is installed in a public park. It collects temperature readings and stores configuration information locally.", "week": 1}, {"id": "q-f6424194de82f1", "type": "short", "prompt": "Q2. Which component may contain identifiers and configuration?", "answerHTML": "<p><strong>Answer:<\/strong> Local Memory / Storage.<\/p>", "group": "6", "lecture": "1", "href": "lesson.html#slide-6", "context": "A smart environmental sensor is installed in a public park. It collects temperature readings and stores configuration information locally.", "week": 1}, {"id": "q-86ff6e9a356db5", "type": "short", "prompt": "Q3. What security concern is introduced by its installation location?", "answerHTML": "<p><strong>Answer:<\/strong> Physical Exposure.<\/p><p><strong>الشرح:<\/strong> الجهاز موجود بمكان عام، فإمكانية الوصول الفيزيائي إله بتكون عامل لازم المهندس الأمني ياخذه بالحسبان.<\/p>", "group": "6", "lecture": "1", "href": "lesson.html#slide-6", "context": "A smart environmental sensor is installed in a public park. It collects temperature readings and stores configuration information locally.", "week": 1}, {"id": "q-0313f50007047f", "type": "short", "prompt": "Question: Which security consideration becomes important?", "answerHTML": "<p><strong>Correct Answer:<\/strong> Long-term software maintainability.<\/p><p><strong>الشرح:<\/strong> استمرار تشغيل الجهاز مش دليل كافي على إنه مناسب أمنيًا لكل الظروف الجديدة. لازم نفكر بقدرته على الصيانة والدعم.<\/p><p><strong>ملاحظة من المحاضرة:<\/strong> Firmware protection and detailed update mechanisms are reserved for later weeks. المطلوب هون تفهم أهمية برمجيات الجهاز، مش تفاصيل حمايتها.<\/p>", "group": "7", "lecture": "1", "href": "lesson.html#slide-7", "context": "An IoT device has been operating for eight years. Its embedded software still performs its basic functions, but the surrounding network and services have changed.", "week": 1}, {"id": "q-d9237c787b6121", "type": "short", "prompt": "Question: Why might its communication requirements differ from those of a video-streaming camera?", "answerHTML": "<p><strong>Correct Answer (English):<\/strong><\/p><p>IoT devices have different operational priorities. Some prioritize low power, range, or reliability rather than high bandwidth.<\/p><p><strong>الشرح:<\/strong> لأن طبيعة عمل الأجهزة مختلفة. الحساس الصغير ممكن تكون الطاقة عنده أهم من سرعة نقل البيانات، بينما جهاز آخر عنده احتياجات مختلفة.<\/p>", "group": "8", "lecture": "1", "href": "lesson.html#slide-8", "context": "A battery-powered IoT sensor prioritizes low energy consumption and reliable communication over high bandwidth.", "week": 1}, {"id": "q-88e33ce07800b0", "type": "short", "prompt": "Q1. Which component failed?", "answerHTML": "<p>Gateway / Edge.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": "", "week": 1}, {"id": "q-e04fa8f4d8550e", "type": "short", "prompt": "Q2. Which security challenge is illustrated?", "answerHTML": "<p>Dependencies.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": "", "week": 1}, {"id": "q-ec30a8ffbd19c8", "type": "short", "prompt": "Q3. Why is the gateway important?", "answerHTML": "<p>Because multiple devices depend on it for communication and management.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": "", "week": 1}, {"id": "q-a0960e993ab0f3", "type": "short", "prompt": "Q4. Does gateway failure necessarily mean that every sensor stops sensing?", "answerHTML": "<p>No. Local sensing may continue if supported by the devices, while gateway-dependent communication becomes unavailable.<\/p><p><strong>الشرح:<\/strong> لازم نميز بين الوظيفة المحلية للجهاز وبين الخدمات اللي بتحتاج Gateway. مش كل عطل بالبوابة يعني إن الجهاز نفسه توقف بالكامل.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": "", "week": 1}, {"id": "q-8d1994baf71238", "type": "short", "prompt": "Question: Why can a cloud-side failure affect a large population of devices?", "answerHTML": "<p><strong>Correct Answer:<\/strong><\/p><p>Because many IoT devices may depend on the same remote infrastructure for management and other services.<\/p><p><strong>الشرح:<\/strong> الأجهزة بتشترك بخدمة مركزية. لذلك تعطلها ممكن يكون تأثيره واسع، حتى لو الأجهزة الفيزيائية نفسها ما تعطلت.<\/p>", "group": "10", "lecture": "1", "href": "lesson.html#slide-10", "context": "A company manages 10,000 IoT devices using one cloud platform. A failure in the cloud service prevents administrators from remotely managing the devices.", "week": 1}, {"id": "q-a7d50f0e0bd959", "type": "short", "prompt": "Q1. Which ecosystem component enables users to control the lock?", "answerHTML": "<p>User Application.<\/p>", "group": "11", "lecture": "1", "href": "lesson.html#slide-11", "context": "A smart lock application allows users to share access with family members. An administrator can also manage the system.", "week": 1}, {"id": "q-acdfd120efa4dd", "type": "short", "prompt": "Q2. Which human workflow is relevant?", "answerHTML": "<p>Sharing and Permissions.<\/p>", "group": "11", "lecture": "1", "href": "lesson.html#slide-11", "context": "A smart lock application allows users to share access with family members. An administrator can also manage the system.", "week": 1}, {"id": "q-2886fe4da004a5", "type": "short", "prompt": "Q3. Why must human interaction be considered part of the system boundary?", "answerHTML": "<p>Because user and administrator actions can influence system access, configuration, and operation.<\/p><p><strong>الشرح:<\/strong> المشكلة الأمنية مش شرط تكون في جهاز القفل. ممكن تكون مرتبطة بطريقة استخدام التطبيق أو إدارة الوصول.<\/p>", "group": "11", "lecture": "1", "href": "lesson.html#slide-11", "context": "A smart lock application allows users to share access with family members. An administrator can also manage the system.", "week": 1}, {"id": "q-8881a96914ccc1", "type": "mcq", "prompt": "Which component executes device logic and handles communication with other components?", "answerHTML": "<p>B. Processor<\/p><p>Processor بينفذ منطق الجهاز وبتعامل مع الاتصال.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Sensor", "Processor", "Actuator", "Cloud Service"], "correct": 1, "explanation": "Processor بينفذ منطق الجهاز وبتعامل مع الاتصال.", "persist": "lecture1-6-11-q1", "week": 1}, {"id": "q-5e4429b7e12681", "type": "mcq", "prompt": "Which of the following may be stored in local device memory?", "answerHTML": "<p>C. Configuration, identifiers, and logs<\/p><p>الذاكرة المحلية ممكن تحتوي Configuration وIdentifiers وLogs.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Only temperature readings", "Only video recordings", "Configuration, identifiers, and logs", "Only cloud account information"], "correct": 2, "explanation": "الذاكرة المحلية ممكن تحتوي Configuration وIdentifiers وLogs.", "persist": "lecture1-6-11-q2", "week": 1}, {"id": "q-944964868dde05", "type": "mcq", "prompt": "Why is physical accessibility important in IoT security?", "answerHTML": "<p>B. Devices may be reachable outside protected environments<\/p><p>الجهاز ممكن يكون متاحًا خارج بيئة محمية.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["IoT devices never contain software", "Devices may be reachable outside protected environments", "Physical access always disables the device", "IoT devices cannot communicate remotely"], "correct": 1, "explanation": "الجهاز ممكن يكون متاحًا خارج بيئة محمية.", "persist": "lecture1-6-11-q3", "week": 1}, {"id": "q-e4b2894b9a5937", "type": "mcq", "prompt": "Which function is controlled by embedded device software?", "answerHTML": "<p>A. Boot and configuration<\/p><p>Embedded Software بيتحكم في Boot وConfiguration.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Boot and configuration", "Only physical sensing", "Only cloud storage", "Only the installation location"], "correct": 0, "explanation": "Embedded Software بيتحكم في Boot وConfiguration.", "persist": "lecture1-6-11-q4", "week": 1}, {"id": "q-44884b2f875b08", "type": "mcq", "prompt": "Why does long-term software maintainability matter?", "answerHTML": "<p>C. The surrounding environment may change while software remains deployed<\/p><p>البيئة المحيطة ممكن تتغير بينما البرنامج يظل مستخدمًا.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["All IoT devices are replaced every year", "IoT software never changes", "The surrounding environment may change while software remains deployed", "All devices use the same operating system"], "correct": 2, "explanation": "البيئة المحيطة ممكن تتغير بينما البرنامج يظل مستخدمًا.", "persist": "lecture1-6-11-q5", "week": 1}, {"id": "q-34ee6c27588a4c", "type": "mcq", "prompt": "Which statement about IoT connectivity is correct?", "answerHTML": "<p>D. Devices may communicate locally, through gateways, or through the Internet<\/p><p>الاتصال ممكن يكون محليًا أو عبر Gateway أو الإنترنت.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["All devices must connect directly to the Internet", "Wi-Fi is the only possible communication technology", "All IoT devices prioritize high bandwidth", "Devices may communicate locally, through gateways, or through the Internet"], "correct": 3, "explanation": "الاتصال ممكن يكون محليًا أو عبر Gateway أو الإنترنت.", "persist": "lecture1-6-11-q6", "week": 1}, {"id": "q-2a78842e734ca1", "type": "mcq", "prompt": "Which component may aggregate data and translate communication?", "answerHTML": "<p>A. Gateway / Edge<\/p><p>Gateway ممكن يجمع البيانات ويكيّف الاتصال.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Gateway / Edge", "Actuator", "User Application", "Sensor"], "correct": 0, "explanation": "Gateway ممكن يجمع البيانات ويكيّف الاتصال.", "persist": "lecture1-6-11-q7", "week": 1}, {"id": "q-629c982a246c1b", "type": "mcq", "prompt": "Why can a gateway become an important trust point?", "answerHTML": "<p>B. Many devices may depend on one gateway<\/p><p>عدة أجهزة ممكن تعتمد على بوابة واحدة.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["It never communicates with remote services", "Many devices may depend on one gateway", "It eliminates the need for device software", "It always replaces cloud services"], "correct": 1, "explanation": "عدة أجهزة ممكن تعتمد على بوابة واحدة.", "persist": "lecture1-6-11-q8", "week": 1}, {"id": "q-f8241521be3c2b", "type": "mcq", "prompt": "Which function is commonly associated with cloud services?", "answerHTML": "<p>C. Remote device registration and account management<\/p><p>Cloud Service بتدير تسجيل الأجهزة والحسابات عن بُعد.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Physical temperature measurement", "Direct mechanical movement", "Remote device registration and account management", "Local sensor actuation only"], "correct": 2, "explanation": "Cloud Service بتدير تسجيل الأجهزة والحسابات عن بُعد.", "persist": "lecture1-6-11-q9", "week": 1}, {"id": "q-420a9f733f2d23", "type": "mcq", "prompt": "Which statement about human interaction is correct?", "answerHTML": "<p>D. Human workflows such as sharing and recovery are part of the security boundary<\/p><p>Sharing وRecovery وغيرها من تفاعل البشر جزء من حدود النظام.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Only administrators affect IoT security", "User experience has no security implications", "Installers are outside the system boundary", "Human workflows such as sharing and recovery are part of the security boundary"], "correct": 3, "explanation": "Sharing وRecovery وغيرها من تفاعل البشر جزء من حدود النظام.", "persist": "lecture1-6-11-q10", "week": 1}, {"id": "q-2984e114091366", "type": "blank", "prompt": "Smart devices interact with the physical world through sensors and _______.", "answerHTML": "<p>actuators<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "actuators", "week": 1}, {"id": "q-99eb36601d8780", "type": "blank", "prompt": "The _______ executes device logic and handles communication.", "answerHTML": "<p>processor<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "processor", "week": 1}, {"id": "q-9278dd4dbb588e", "type": "blank", "prompt": "Local memory may contain configuration, identifiers, and _______.", "answerHTML": "<p>logs<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "logs", "week": 1}, {"id": "q-654062a85daabd", "type": "blank", "prompt": "Embedded software determines how the device starts, behaves, stores _______ and communicates.", "answerHTML": "<p>configuration<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "configuration", "week": 1}, {"id": "q-6d8352e4358aaf", "type": "blank", "prompt": "Some IoT devices prioritize low power, range, or _______ rather than high bandwidth.", "answerHTML": "<p>reliability<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "reliability", "week": 1}, {"id": "q-e682a42ee684dd", "type": "blank", "prompt": "A _______ can connect local devices to external networks and services.", "answerHTML": "<p>gateway<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "gateway", "week": 1}, {"id": "q-22ac6a9d12036f", "type": "blank", "prompt": "A gateway may aggregate data and translate _______.", "answerHTML": "<p>communication<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "communication", "week": 1}, {"id": "q-f918f3a9f6bec4", "type": "blank", "prompt": "Cloud services may store device data, manage accounts, and register _______.", "answerHTML": "<p>devices<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "devices", "week": 1}, {"id": "q-50670f19bce653", "type": "blank", "prompt": "A cloud-side failure may affect a large population of _______.", "answerHTML": "<p>devices<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "devices", "week": 1}, {"id": "q-3e67c6cbe8fd0d", "type": "blank", "prompt": "Human interaction is part of the system _______.", "answerHTML": "<p>boundary<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "boundary", "week": 1}, {"id": "q-9b8a58e36de1bf", "type": "short", "prompt": "Q1. Which devices are more typical of IoT?", "answerHTML": "<p><b>Answer:<\/b> The smart environmental sensors.<\/p>", "group": "12", "lecture": "1", "href": "lesson.html#slide-12", "context": "A company uses office laptops and 2,000 smart environmental sensors installed across several buildings. The sensors operate without continuous user interaction and have limited processing power.", "week": 1}, {"id": "q-42e3d345015fb1", "type": "short", "prompt": "Q2. Identify two differences between the sensors and traditional IT endpoints.", "answerHTML": "<p><b>Answer:<\/b> The sensors are often unattended and have resource and power constraints.<\/p>", "group": "12", "lecture": "1", "href": "lesson.html#slide-12", "context": "A company uses office laptops and 2,000 smart environmental sensors installed across several buildings. The sensors operate without continuous user interaction and have limited processing power.", "week": 1}, {"id": "q-358129c8ae7872", "type": "short", "prompt": "Q3. Which security challenge is introduced by deploying 2,000 sensors?", "answerHTML": "<p><b>Answer:<\/b> Scale.<\/p><p><b>التحليل<\/b><b> <\/b><b>بالعربي<\/b><b>:<\/b> انتبه لكلمات <i>2,000 sensors<\/i>، و<i>unattended<\/i>، و<i>limited processing power<\/i>. كل كلمة بتدل على مفهوم مختلف.<\/p>", "group": "12", "lecture": "1", "href": "lesson.html#slide-12", "context": "A company uses office laptops and 2,000 smart environmental sensors installed across several buildings. The sensors operate without continuous user interaction and have limited processing power.", "week": 1}, {"id": "q-36fc1938b51d8e", "type": "short", "prompt": "Question: Do all IoT devices require actuation capabilities?", "answerHTML": "<p><b>Answer:<\/b> No. Actuation is optional.<\/p><p>ليش؟ لأن التعريف استخدم كلمة <b>Sometimes<\/b>.<\/p>", "group": "13", "lecture": "1", "href": "lesson.html#slide-13", "context": "", "week": 1}, {"id": "q-f63fdf43e39beb", "type": "short", "prompt": "Question: Which characteristic makes this system a Cyber-Physical System?", "answerHTML": "<p><b>Correct Answer:<\/b> Tight integration of computation with physical processes and feedback.<\/p><p><b>الشرح<\/b><b> <\/b><b>بالعربي<\/b><b>:<\/b> الكلمات المهمة هي <i>automatically adjusts<\/i> و<i>sensor feedback<\/i>. النظام مش بس بجمع بيانات، بل بستخدمها للتحكم بعملية فيزيائية.<\/p>", "group": "15", "lecture": "1", "href": "lesson.html#slide-15", "context": "A connected industrial system continuously measures temperature and automatically adjusts a cooling process based on sensor feedback.", "week": 1}, {"id": "q-e8feb2ae529e86", "type": "mcq", "prompt": "Which characteristic is more typical of IoT than Traditional IT?", "answerHTML": "<p>C. Often unattended operation<\/p><p>IoT كثيرًا ما يعمل بدون تفاعل بشري مستمر.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Frequent user interaction", "General-purpose computing", "Often unattended operation", "Easy replacement"], "correct": 2, "explanation": "IoT كثيرًا ما يعمل بدون تفاعل بشري مستمر.", "persist": "lecture1-12-17-q1", "week": 1}, {"id": "q-cfb2ad9d64baac", "type": "mcq", "prompt": "Which capability is optional in the lecture's definition of IoT?", "answerHTML": "<p>D. Actuation<\/p><p>التعريف بيقول Sometimes Actuation.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Sensing", "Processing", "Communication", "Actuation"], "correct": 3, "explanation": "التعريف بيقول Sometimes Actuation.", "persist": "lecture1-12-17-q2", "week": 1}, {"id": "q-6ed6aaecbe649c", "type": "mcq", "prompt": "What does CPS stand for?", "answerHTML": "<p>A. Cyber-Physical System<\/p><p>CPS اختصار Cyber-Physical System.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Cyber-Physical System", "Cloud Processing Service", "Connected Physical Software", "Cyber Protection Standard"], "correct": 0, "explanation": "CPS اختصار Cyber-Physical System.", "persist": "lecture1-12-17-q3", "week": 1}, {"id": "q-71103ca7d31efe", "type": "mcq", "prompt": "Which feature most clearly distinguishes a CPS in this lecture?", "answerHTML": "<p>B. Physical-process feedback<\/p><p>التمييز الأساسي هو Physical-process Feedback.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Cloud storage", "Physical-process feedback", "Mobile application", "Large device count"], "correct": 1, "explanation": "التمييز الأساسي هو Physical-process Feedback.", "persist": "lecture1-12-17-q4", "week": 1}, {"id": "q-13178c27a47f89", "type": "mcq", "prompt": "Which abbreviation refers to remote delivery of software or configuration?", "answerHTML": "<p>C. OTA<\/p><p>OTA يعني Over-the-Air.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["API", "UX", "OTA", "CPS"], "correct": 2, "explanation": "OTA يعني Over-the-Air.", "persist": "lecture1-12-17-q5", "week": 1}, {"id": "q-86740ee4b08726", "type": "mcq", "prompt": "A battery-powered sensor has limited processing and memory. Which challenge is illustrated?", "answerHTML": "<p>B. Constraints<\/p><p>محدودية المعالجة والذاكرة والطاقة تعني Constraints.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Scale", "Constraints", "Heterogeneity", "Dependencies"], "correct": 1, "explanation": "محدودية المعالجة والذاكرة والطاقة تعني Constraints.", "persist": "lecture1-12-17-q6", "week": 1}, {"id": "q-7097cc89017e68", "type": "mcq", "prompt": "A sensor is installed in a publicly accessible location. Which challenge is most relevant?", "answerHTML": "<p>A. Physical Exposure<\/p><p>المكان المتاح للجمهور يعني Physical Exposure.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Physical Exposure", "Scale", "Long Lifetime", "Heterogeneity"], "correct": 0, "explanation": "المكان المتاح للجمهور يعني Physical Exposure.", "persist": "lecture1-12-17-q7", "week": 1}, {"id": "q-8dc91aef8cc721", "type": "mcq", "prompt": "One configuration error affects 20,000 deployed devices. This illustrates:", "answerHTML": "<p>C. Scale<\/p><p>الخطأ المتكرر على آلاف الأجهزة يعني Scale.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["UX", "CPS", "Scale", "OTA"], "correct": 2, "explanation": "الخطأ المتكرر على آلاف الأجهزة يعني Scale.", "persist": "lecture1-12-17-q8", "week": 1}, {"id": "q-bd0f3d8ad426b1", "type": "mcq", "prompt": "Different manufacturers and communication technologies create which challenge?", "answerHTML": "<p>B. Heterogeneity<\/p><p>اختلاف الشركات والتقنيات يعني Heterogeneity.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Physical Exposure", "Heterogeneity", "Constraints", "Actuation"], "correct": 1, "explanation": "اختلاف الشركات والتقنيات يعني Heterogeneity.", "persist": "lecture1-12-17-q9", "week": 1}, {"id": "q-e1cb22966984cd", "type": "mcq", "prompt": "A device continues operating after its software support has ended. Which challenge is illustrated?", "answerHTML": "<p>D. Long Lifetime<\/p><p>استمرار الجهاز بعد انتهاء الدعم يعني Long Lifetime.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Scale", "Physical Exposure", "Connectivity", "Long Lifetime"], "correct": 3, "explanation": "استمرار الجهاز بعد انتهاء الدعم يعني Long Lifetime.", "persist": "lecture1-12-17-q10", "week": 1}, {"id": "q-0979f7932f33e3", "type": "mcq", "prompt": "A cloud failure prevents remote management of several smart devices. Which challenge is illustrated?", "answerHTML": "<p>A. Dependencies<\/p><p>تعطل خدمة يحتاجها الجهاز يعني Dependencies.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Dependencies", "Heterogeneity", "Physical Exposure", "Constraints"], "correct": 0, "explanation": "تعطل خدمة يحتاجها الجهاز يعني Dependencies.", "persist": "lecture1-12-17-q11", "week": 1}, {"id": "q-118005ab8a2c65", "type": "mcq", "prompt": "Which statement best describes the security unit of an IoT product?", "answerHTML": "<p>C. The complete device-service ecosystem<\/p><p>وحدة التحليل تشمل Complete Device-Service Ecosystem.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Only the physical hardware", "Only the network connection", "The complete device-service ecosystem", "Only the cloud platform"], "correct": 2, "explanation": "وحدة التحليل تشمل Complete Device-Service Ecosystem.", "persist": "lecture1-12-17-q12", "week": 1}, {"id": "q-a7c3efbcf0a83e", "type": "blank", "prompt": "IoT devices are often _______ rather than general-purpose computers.", "answerHTML": "<p>special-purpose<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "special-purpose", "week": 1}, {"id": "q-bbe3dce970e2ab", "type": "blank", "prompt": "IoT devices are often _______ without frequent user interaction.", "answerHTML": "<p>unattended<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "unattended", "week": 1}, {"id": "q-74e21e5b8c5d81", "type": "blank", "prompt": "The Internet of Things includes sensing, processing, communication, and sometimes _______.", "answerHTML": "<p>actuation<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "actuation", "week": 1}, {"id": "q-19f2f00f036386", "type": "blank", "prompt": "CPS stands for _______.", "answerHTML": "<p>Cyber-Physical System<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "Cyber-Physical System", "week": 1}, {"id": "q-b38070c617225f", "type": "blank", "prompt": "API stands for _______.", "answerHTML": "<p>Application Programming Interface<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "Application Programming Interface", "week": 1}, {"id": "q-1c089587aa81c5", "type": "blank", "prompt": "OTA stands for _______.", "answerHTML": "<p>Over-the-Air<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "Over-the-Air", "week": 1}, {"id": "q-a26d28131d2051", "type": "blank", "prompt": "UX stands for _______.", "answerHTML": "<p>User Experience<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "User Experience", "week": 1}, {"id": "q-e9537d3b602c3d", "type": "blank", "prompt": "Limited memory, processing, and power are examples of resource _______.", "answerHTML": "<p>constraints<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "constraints", "week": 1}, {"id": "q-64c7ab1a68d9de", "type": "blank", "prompt": "A configuration mistake repeated across thousands of devices illustrates _______.", "answerHTML": "<p>scale<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "scale", "week": 1}, {"id": "q-09bbd1e0504e8d", "type": "blank", "prompt": "Different vendors and communication technologies create _______.", "answerHTML": "<p>heterogeneity<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "heterogeneity", "week": 1}, {"id": "q-0235563690b03a", "type": "blank", "prompt": "Devices may outlive their software _______.", "answerHTML": "<p>support<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "support", "week": 1}, {"id": "q-7c272a1735f63d", "type": "blank", "prompt": "IoT devices may depend on gateways, networks, cloud services, and _______.", "answerHTML": "<p>applications<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "applications", "week": 1}, {"id": "q-9547d33c78a717", "type": "short", "prompt": "Q1. What physical service does the device support?", "answerHTML": "<p>Answer: Patient monitoring.<\/p>", "group": "18", "lecture": "1", "href": "lesson.html#slide-18", "context": "A hospital uses a connected medical sensor to monitor patient measurements. The sensor sends data to a cloud service used by clinical staff.", "week": 1}, {"id": "q-510944cdaad963", "type": "short", "prompt": "Q2. What data does the system collect?", "answerHTML": "<p>Answer: Patient measurements.<\/p>", "group": "18", "lecture": "1", "href": "lesson.html#slide-18", "context": "A hospital uses a connected medical sensor to monitor patient measurements. The sensor sends data to a cloud service used by clinical staff.", "week": 1}, {"id": "q-8547374c9cb1e1", "type": "short", "prompt": "Q3. What happens if the measurements are incorrect?", "answerHTML": "<p>Answer: Clinical staff may receive incorrect information, which could affect decisions based on those measurements.<\/p><p>التحليل بالعربي: لاحظ إننا حللنا وظيفة الجهاز والبيانات والاعتماد ونتائج الخطأ، بدون ما نحتاج نذكر أي هجوم محدد.<\/p>", "group": "18", "lecture": "1", "href": "lesson.html#slide-18", "context": "A hospital uses a connected medical sensor to monitor patient measurements. The sensor sends data to a cloud service used by clinical staff.", "week": 1}, {"id": "q-11dffeedb8418d", "type": "short", "prompt": "Q1. Identify four ecosystem elements.", "answerHTML": "<p>Answer: Physical Smart Lock, Mobile Application, Network Connection, Remote Service.<\/p>", "group": "19", "lecture": "1", "href": "lesson.html#slide-19", "context": "A smart door lock is controlled through a mobile application connected to a remote service. The owner and an installer both interact with the system.", "week": 1}, {"id": "q-c2ff05dc224e0c", "type": "short", "prompt": "Q2. Identify two human roles.", "answerHTML": "<p>Answer: Owner and Installer.<\/p>", "group": "19", "lecture": "1", "href": "lesson.html#slide-19", "context": "A smart door lock is controlled through a mobile application connected to a remote service. The owner and an installer both interact with the system.", "week": 1}, {"id": "q-b5c5673424aa09", "type": "short", "prompt": "Q3. What should be marked on the diagram?", "answerHTML": "<p>Answer: Information and command paths between components.<\/p>", "group": "19", "lecture": "1", "href": "lesson.html#slide-19", "context": "A smart door lock is controlled through a mobile application connected to a remote service. The owner and an installer both interact with the system.", "week": 1}, {"id": "q-5d953e0147a8c6", "type": "short", "prompt": "Why is the security boundary of a smart camera larger than the camera itself?", "answerHTML": "<p>Model Answer: Because the camera depends on software, network connections, remote services, applications, and human interaction.<\/p><p>الشرح: لأن المشكلة ممكن تكون في أي جزء من النظام، مش بس في الكاميرا نفسها.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": "", "week": 1}, {"id": "q-d12c5ac1583712", "type": "short", "prompt": "Give two differences between traditional IT endpoints and IoT devices.", "answerHTML": "<p>Model Answer: Traditional IT endpoints are generally general-purpose and frequently used by people, while IoT devices are often special-purpose and unattended.<\/p><p>الشرح: الكمبيوتر متعدد الاستخدامات وغالبًا المستخدم بتفاعل معه، بينما كثير أجهزة IoT إلها وظيفة محددة وبتشتغل بدون متابعة مستمرة.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": "", "week": 1}, {"id": "q-66dd42612f5976", "type": "short", "prompt": "Why can physical access matter more in IoT deployments?", "answerHTML": "<p>Model Answer: Because IoT devices may be installed in physically accessible locations where assumptions used for protected servers do not hold.<\/p><p>الشرح: لأن الجهاز ممكن يكون بمكان عام أو غير محمي مثل غرفة السيرفرات.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": "", "week": 1}, {"id": "q-8ffea3b923e41c", "type": "short", "prompt": "What is the difference between IoT and a Cyber-Physical System at a high level?", "answerHTML": "<p>Model Answer: IoT focuses on connected physical objects and services, while CPS emphasizes tight interaction between computation and physical processes with feedback.<\/p><p>الشرح: IoT بيركز على الأجهزة المتصلة والخدمات، بينما CPS بيركز على العلاقة المباشرة بين الحوسبة والتحكم الفيزيائي والتغذية الراجعة.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": "", "week": 1}, {"id": "q-1b73d9cf463989", "type": "short", "prompt": "Why should security engineers consider the complete device lifecycle?", "answerHTML": "<p>Model Answer: Because devices may remain deployed for years while software, services, networks, dependencies, and ownership change.<\/p><p>الشرح: لأنه الظروف اللي كان الجهاز شغال فيها وقت تركيبه ممكن تتغير مع مرور السنوات.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": "", "week": 1}, {"id": "q-0db82496637d01", "type": "short", "prompt": "Q1. Which IoT category best describes this system?", "answerHTML": "<p>Answer: Industrial / Infrastructure IoT.<\/p>", "group": "22", "lecture": "1", "href": "lesson.html#slide-22", "context": "A factory uses connected sensors to monitor an industrial process. Incorrect sensor operation could affect production.", "week": 1}, {"id": "q-8656a86e90a699", "type": "short", "prompt": "Q2. Which phrase is the strongest clue?", "answerHTML": "<p>Answer: Operational consequences.<\/p><p>الشرح: مجرد وجود Sensors مش كافي لتحديد الفئة؛ لازم تشوف وين مستخدمة الأجهزة وشو نتائج فشلها.<\/p>", "group": "22", "lecture": "1", "href": "lesson.html#slide-22", "context": "A factory uses connected sensors to monitor an industrial process. Incorrect sensor operation could affect production.", "week": 1}, {"id": "q-0eda39711280e4", "type": "short", "prompt": "Q1. Who is responsible for embedded software decisions?", "answerHTML": "<p>Answer: Device Manufacturer.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily.", "week": 1}, {"id": "q-783a1785202d62", "type": "short", "prompt": "Q2. Who manages account-related backend functions?", "answerHTML": "<p>Answer: Service Provider.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily.", "week": 1}, {"id": "q-c9effcf359ac2e", "type": "short", "prompt": "Q3. Who is responsible for installation and network configuration?", "answerHTML": "<p>Answer: Installer / Organization.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily.", "week": 1}, {"id": "q-0690631267d948", "type": "short", "prompt": "Q4. Who handles daily use and reports abnormal behavior?", "answerHTML": "<p>Answer: User / Operator.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily.", "week": 1}, {"id": "q-67d04e444486b0", "type": "short", "prompt": "Q5. What security problem can arise if these responsibilities are unclear?", "answerHTML": "<p>Answer: Security gaps may appear between the responsible parties.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily.", "week": 1}, {"id": "q-17239400364319", "type": "mcq", "prompt": "What should a security engineer do before looking for specific IoT vulnerabilities?", "answerHTML": "<p>B. Understand the device, its purpose, data, users, dependencies, and failure consequences<\/p><p>أول خطوة نفهم النظام ووظيفته ومكوناته والبيانات والأشخاص والاعتماد ونتائج الفشل.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Immediately identify attacks", "Understand the device, its purpose, data, users, dependencies, and failure consequences", "Ignore the physical environment", "Analyze only the cloud service"], "correct": 1, "explanation": "أول خطوة نفهم النظام ووظيفته ومكوناته والبيانات والأشخاص والاعتماد ونتائج الفشل.", "persist": "lecture1-18-23-q1", "week": 1}, {"id": "q-b9ad87c9b14967", "type": "mcq", "prompt": "Which question helps identify the information handled by an IoT system?", "answerHTML": "<p>C. What data does the system collect, store, or transmit?<\/p><p>Collect, Store, Transmit هي الكلمات الأساسية لفهم البيانات اللي بتتعامل معها المنظومة.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Who manufactured the device?", "Where is the company located?", "What data does the system collect, store, or transmit?", "How many computers are in the office?"], "correct": 2, "explanation": "Collect, Store, Transmit هي الكلمات الأساسية لفهم البيانات اللي بتتعامل معها المنظومة.", "persist": "lecture1-18-23-q2", "week": 1}, {"id": "q-ddfd118e90521c", "type": "mcq", "prompt": "In a smart lock mapping activity, what should be identified first?", "answerHTML": "<p>A. The device, application, network connection, and remote service<\/p><p>النشاط بطلب تحديد مكونات النظام ومسارات المعلومات والأوامر قبل تحليل الهجمات.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["The device, application, network connection, and remote service", "Only the attacker's location", "Only known vulnerabilities", "Only encryption methods"], "correct": 0, "explanation": "النشاط بطلب تحديد مكونات النظام ومسارات المعلومات والأوامر قبل تحليل الهجمات.", "persist": "lecture1-18-23-q3", "week": 1}, {"id": "q-cb383b4f94c828", "type": "mcq", "prompt": "Why is treating IoT as a small traditional computer a mistake?", "answerHTML": "<p>D. IoT may have limited resources, unusual hardware, physical effects, and external dependencies<\/p><p>أجهزة IoT إلها خصائص بتخلي التحليل الأمني مختلف عن الافتراضات التقليدية.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["IoT devices never contain processors", "IoT devices cannot communicate", "Traditional computers have no software", "IoT may have limited resources, unusual hardware, physical effects, and external dependencies"], "correct": 3, "explanation": "أجهزة IoT إلها خصائص بتخلي التحليل الأمني مختلف عن الافتراضات التقليدية.", "persist": "lecture1-18-23-q4", "week": 1}, {"id": "q-cf48bbc4e65e8f", "type": "mcq", "prompt": "Which category includes smart cameras, speakers, and wearables used by individuals?", "answerHTML": "<p>B. Consumer IoT<\/p><p>Consumer IoT غالبًا بستخدمه أشخاص عاديون وغير متخصصين.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Industrial IoT", "Consumer IoT", "Enterprise IoT", "Infrastructure IoT"], "correct": 1, "explanation": "Consumer IoT غالبًا بستخدمه أشخاص عاديون وغير متخصصين.", "persist": "lecture1-18-23-q5", "week": 1}, {"id": "q-b71ad548fd85af", "type": "mcq", "prompt": "Which IoT category is commonly managed at a larger organizational scale?", "answerHTML": "<p>C. Enterprise / Building IoT<\/p><p>Enterprise / Building IoT يشمل أنظمة المباني والتحكم بالدخول والحساسات المُدارة على نطاق أكبر.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Consumer IoT", "Personal IoT", "Enterprise / Building IoT", "Offline computing"], "correct": 2, "explanation": "Enterprise / Building IoT يشمل أنظمة المباني والتحكم بالدخول والحساسات المُدارة على نطاق أكبر.", "persist": "lecture1-18-23-q6", "week": 1}, {"id": "q-a553082ef1ebae", "type": "mcq", "prompt": "Which category may involve significant operational consequences from incorrect operation?", "answerHTML": "<p>A. Industrial / Infrastructure IoT<\/p><p>الأنظمة الصناعية والبنية التحتية ممكن يكون لأخطاء تشغيلها نتائج عملية مهمة.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Industrial / Infrastructure IoT", "Consumer IoT only", "Personal entertainment devices only", "Traditional desktop systems only"], "correct": 0, "explanation": "الأنظمة الصناعية والبنية التحتية ممكن يكون لأخطاء تشغيلها نتائج عملية مهمة.", "persist": "lecture1-18-23-q7", "week": 1}, {"id": "q-62c062fe2790ee", "type": "mcq", "prompt": "Who is responsible for hardware and embedded software decisions?", "answerHTML": "<p>D. Device Manufacturer<\/p><p>الشركة المصنعة مسؤولة عن القرارات المتعلقة بمكونات الجهاز والبرمجيات المدمجة.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["User / Operator", "Installer", "Service Provider", "Device Manufacturer"], "correct": 3, "explanation": "الشركة المصنعة مسؤولة عن القرارات المتعلقة بمكونات الجهاز والبرمجيات المدمجة.", "persist": "lecture1-18-23-q8", "week": 1}, {"id": "q-1a7bce8d869ed4", "type": "mcq", "prompt": "Who is most directly responsible for network placement and initial configuration?", "answerHTML": "<p>B. Installer / Organization<\/p><p>التركيب ومكان الجهاز على الشبكة والإعدادات من مسؤولية Installer / Organization.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Device Manufacturer", "Installer / Organization", "End User only", "Cloud Storage Provider"], "correct": 1, "explanation": "التركيب ومكان الجهاز على الشبكة والإعدادات من مسؤولية Installer / Organization.", "persist": "lecture1-18-23-q9", "week": 1}, {"id": "q-ff3ef50a0541b0", "type": "mcq", "prompt": "Which party handles backend and remote account-related responsibilities?", "answerHTML": "<p>C. Service Provider<\/p><p>Service Provider مسؤول عن Backend والإدارة عن بُعد والحسابات.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Device Manufacturer", "Installer", "Service Provider", "Physical Sensor"], "correct": 2, "explanation": "Service Provider مسؤول عن Backend والإدارة عن بُعد والحسابات.", "persist": "lecture1-18-23-q10", "week": 1}, {"id": "q-0d6a729229e33b", "type": "mcq", "prompt": "Which activity is associated with the User / Operator?", "answerHTML": "<p>A. Reporting abnormal behavior<\/p><p>المستخدم مسؤول عن الاستخدام اليومي والتعامل مع الحساب والإبلاغ عن السلوك غير الطبيعي.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Reporting abnormal behavior", "Designing device hardware", "Manufacturing processors", "Developing all embedded software"], "correct": 0, "explanation": "المستخدم مسؤول عن الاستخدام اليومي والتعامل مع الحساب والإبلاغ عن السلوك غير الطبيعي.", "persist": "lecture1-18-23-q11", "week": 1}, {"id": "q-7bbb5a1ceee8ee", "type": "mcq", "prompt": "Security gaps may appear when:", "answerHTML": "<p>D. Responsibilities between different parties are unclear<\/p><p>عدم وضوح المسؤوليات بين الأطراف ممكن يخلق فجوات أمنية.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Every device has a sensor", "A system includes a mobile application", "Devices operate locally", "Responsibilities between different parties are unclear"], "correct": 3, "explanation": "عدم وضوح المسؤوليات بين الأطراف ممكن يخلق فجوات أمنية.", "persist": "lecture1-18-23-q12", "week": 1}, {"id": "q-db62827d2c268f", "type": "blank", "prompt": "Before looking for vulnerabilities, engineers should understand the device's physical process or _______.", "answerHTML": "<p>service<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "service", "week": 1}, {"id": "q-c5a1b5b2380cb3", "type": "blank", "prompt": "Security engineers should identify what data a system collects, stores, or _______.", "answerHTML": "<p>transmits<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "transmits", "week": 1}, {"id": "q-6d4855f0597048", "type": "blank", "prompt": "A device may depend on gateways, networks, cloud services, and other _______.", "answerHTML": "<p>systems<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "systems", "week": 1}, {"id": "q-1fdf6a7b3a25af", "type": "blank", "prompt": "A smart lock mapping activity should mark where information or _______ move between components.", "answerHTML": "<p>commands<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "commands", "week": 1}, {"id": "q-f2bbad448b090d", "type": "blank", "prompt": "IoT devices may have limited resources, unusual hardware, and long deployment _______.", "answerHTML": "<p>periods<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "periods", "week": 1}, {"id": "q-87453488156077", "type": "blank", "prompt": "Consumer IoT devices are often deployed by _______ users.", "answerHTML": "<p>non-specialist<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "non-specialist", "week": 1}, {"id": "q-b905fd272dd357", "type": "blank", "prompt": "Access control and smart building systems are examples of _______ IoT.", "answerHTML": "<p>Enterprise / Building<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "Enterprise / Building", "week": 1}, {"id": "q-1f3e253478ad5a", "type": "blank", "prompt": "Industrial devices may have important _______ consequences when operating incorrectly.", "answerHTML": "<p>operational<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "operational", "week": 1}, {"id": "q-21e4a4eb4b2df5", "type": "blank", "prompt": "The device _______ is responsible for hardware and embedded software decisions.", "answerHTML": "<p>manufacturer<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "manufacturer", "week": 1}, {"id": "q-bec93ea45eb9bb", "type": "blank", "prompt": "The service provider handles backend and remote _______.", "answerHTML": "<p>management<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "management", "week": 1}, {"id": "q-950bff5e640976", "type": "blank", "prompt": "The installer or organization is responsible for deployment, network placement, and _______.", "answerHTML": "<p>configuration<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "configuration", "week": 1}, {"id": "q-4e39dfbe35a867", "type": "blank", "prompt": "Security gaps often appear when responsibility between parties is _______.", "answerHTML": "<p>unclear<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "unclear", "week": 1}, {"id": "q-a45aef5ab12b68", "type": "short", "prompt": "Q1. Identify the telemetry path.", "answerHTML": "<p>Answer: Thermostat → Cloud Service → Dashboard.<\/p>", "group": "24", "lecture": "1", "href": "lesson.html#slide-24", "context": "A smart thermostat sends temperature readings to a cloud dashboard. A user can also send commands through a mobile application to adjust the heating system.", "week": 1}, {"id": "q-f4aa0e7631390f", "type": "short", "prompt": "Q2. Identify the control path.", "answerHTML": "<p>Answer: Mobile Application → Cloud Service → Thermostat / Heating Control.<\/p>", "group": "24", "lecture": "1", "href": "lesson.html#slide-24", "context": "A smart thermostat sends temperature readings to a cloud dashboard. A user can also send commands through a mobile application to adjust the heating system.", "week": 1}, {"id": "q-7f241076bd6ed3", "type": "short", "prompt": "Q3. Why is the control path security-relevant?", "answerHTML": "<p>Answer: Because control commands can influence physical device behavior.<\/p>", "group": "24", "lecture": "1", "href": "lesson.html#slide-24", "context": "A smart thermostat sends temperature readings to a cloud dashboard. A user can also send commands through a mobile application to adjust the heating system.", "week": 1}, {"id": "q-977c118e0e7987", "type": "short", "prompt": "Q1. Identify the physical layer.", "answerHTML": "<p>Answer: Door sensors, cameras, and access-control devices.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard.", "week": 1}, {"id": "q-afd68389077fc2", "type": "short", "prompt": "Q2. Identify the local layer.", "answerHTML": "<p>Answer: Gateways.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard.", "week": 1}, {"id": "q-dd2382021c4850", "type": "short", "prompt": "Q3. Identify the remote layer.", "answerHTML": "<p>Answer: Remote Management Dashboard / Service.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard.", "week": 1}, {"id": "q-0a4b52f48d21dd", "type": "short", "prompt": "Q4. Why is analyzing only the physical devices insufficient?", "answerHTML": "<p>Answer: Because the devices depend on local communication, gateways, remote services, and human interaction.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard.", "week": 1}, {"id": "q-82e4f4c71e9688", "type": "short", "prompt": "Q1. Which security challenge is illustrated?", "answerHTML": "<p>Answer: Scale.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor.", "week": 1}, {"id": "q-7e71279da7f96f", "type": "short", "prompt": "Q2. Why is the error more significant than a similar error on one laptop?", "answerHTML": "<p>Answer: Because the same mistake is reproduced across an entire fleet.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor.", "week": 1}, {"id": "q-015f83c5364e24", "type": "short", "prompt": "Q3. Name four important management processes.", "answerHTML": "<p>Answer: Onboarding, Inventory, Maintenance, and Retirement.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor.", "week": 1}, {"id": "q-36c954985308f1", "type": "short", "prompt": "Q4. Why is direct inspection difficult?", "answerHTML": "<p>Answer: Because devices may be distributed across many locations.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor.", "week": 1}, {"id": "q-63cc4964178c21", "type": "short", "prompt": "Q1. Which security challenge is illustrated?", "answerHTML": "<p>Answer: Long Lifetime.<\/p>", "group": "27", "lecture": "1", "href": "lesson.html#slide-27", "context": "A smart meter has been installed for 12 years. It still collects readings, but some of its software dependencies are no longer supported.", "week": 1}, {"id": "q-628d7a05e25927", "type": "short", "prompt": "Q2. What may become outdated?", "answerHTML": "<p>Answer: Security assumptions and software dependencies.<\/p>", "group": "27", "lecture": "1", "href": "lesson.html#slide-27", "context": "A smart meter has been installed for 12 years. It still collects readings, but some of its software dependencies are no longer supported.", "week": 1}, {"id": "q-0e3a346278954a", "type": "short", "prompt": "Q3. What should the organization know?", "answerHTML": "<p>Answer: Which devices exist and whether they remain supportable.<\/p><p>ملاحظة: السلايد بتذكر إن تفاصيل تحديث الأجهزة وحماية دورة حياتها رح تنشرح في Week 6، فهون ركز على المفهوم الأساسي.<\/p>", "group": "27", "lecture": "1", "href": "lesson.html#slide-27", "context": "A smart meter has been installed for 12 years. It still collects readings, but some of its software dependencies are no longer supported.", "week": 1}, {"id": "q-d16ab094d58335", "type": "short", "prompt": "Question 1 — List the ecosystem components without discussing specific attacks.", "answerHTML": "<p>Model Answer (English): The ecosystem includes the patient sensor, embedded device software, communication network, remote service, clinical application, and clinical staff. A gateway may also be present depending on the architecture.<\/p><p>الشرح بالعربي: بنبدأ بالحساس نفسه، بعدين برمجياته، والاتصال، والخدمة، والتطبيق، والأشخاص. لاحظ إن Gateway مش مذكور صراحة في السيناريو، لذلك ما بنقدر نفترض إنه موجود أكيد.<\/p>", "group": "28", "lecture": "1", "href": "lesson.html#slide-28", "context": "A patient sensor collects measurements and sends them to a service used by clinical staff.", "week": 1}, {"id": "q-5ba3498db3b10c", "type": "short", "prompt": "Question 2 — Which components are physically accessible? Which are remotely managed?", "answerHTML": "<p>Model Answer (English): The patient sensor is physically accessible in the clinical environment. The remote service and its management functions may be administered remotely.<\/p><p>الشرح بالعربي: الحساس نفسه موجود في البيئة الطبية وممكن الوصول إله فيزيائيًا. أما الخدمة البعيدة، فإدارتها ممكن تكون عن بُعد.<\/p>", "group": "28", "lecture": "1", "href": "lesson.html#slide-28", "context": "A patient sensor collects measurements and sends them to a service used by clinical staff.", "week": 1}, {"id": "q-d2598432a17807", "type": "short", "prompt": "Question 3 — What would matter more: Data Exposure, Incorrect Data, Service Interruption, or Incorrect Physical Behavior?", "answerHTML": "<p>هاي أهم نقطة في السيناريو، ولازم نفهم الخيارات الأربعة:<\/p>", "group": "28", "lecture": "1", "href": "lesson.html#slide-28", "context": "A patient sensor collects measurements and sends them to a service used by clinical staff.", "week": 1}, {"id": "q-846bf4cb818988", "type": "mcq", "prompt": "Which term describes measurements flowing from physical devices toward applications?", "answerHTML": "<p>B. Telemetry<\/p><p>Telemetry هي البيانات والقياسات اللي بتنتقل من الجهاز باتجاه التطبيقات والخدمات.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Actuation", "Telemetry", "Control Command", "Onboarding"], "correct": 1, "explanation": "Telemetry هي البيانات والقياسات اللي بتنتقل من الجهاز باتجاه التطبيقات والخدمات.", "persist": "lecture1-24-29-q1", "week": 1}, {"id": "q-c9864ad107161e", "type": "mcq", "prompt": "Which action best represents a control path?", "answerHTML": "<p>C. An application sends an unlock command<\/p><p>أمر الفتح بيؤثر على سلوك الجهاز الفيزيائي، لذلك هو Control Command.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["A sensor reports humidity", "A camera sends recorded video", "An application sends an unlock command", "A device reports battery level"], "correct": 2, "explanation": "أمر الفتح بيؤثر على سلوك الجهاز الفيزيائي، لذلك هو Control Command.", "persist": "lecture1-24-29-q2", "week": 1}, {"id": "q-a1ecf32b9b37c6", "type": "mcq", "prompt": "Can an IoT system expose sensitive information without performing a physical action?", "answerHTML": "<p>A. Yes<\/p><p>ممكن يحصل Data Exposure حتى لو النظام ما بقدر ينفذ أي فعل فيزيائي.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Yes", "No", "Only if it contains an actuator", "Only if it is industrial"], "correct": 0, "explanation": "ممكن يحصل Data Exposure حتى لو النظام ما بقدر ينفذ أي فعل فيزيائي.", "persist": "lecture1-24-29-q3", "week": 1}, {"id": "q-6c7c5e0348902e", "type": "mcq", "prompt": "Which smart-building layer includes gateways and controllers?", "answerHTML": "<p>D. Local Layer<\/p><p>Controllers وGateways موجودين في Local Layer.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Physical Layer", "Human Layer", "Remote Layer", "Local Layer"], "correct": 3, "explanation": "Controllers وGateways موجودين في Local Layer.", "persist": "lecture1-24-29-q4", "week": 1}, {"id": "q-71ac5d90d0f5f0", "type": "mcq", "prompt": "Which layer includes dashboards, storage, and remote administration?", "answerHTML": "<p>B. Remote Layer<\/p><p>Remote Layer بتوفر وظائف الإدارة والتخزين والمراقبة عن بُعد.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Physical Layer", "Remote Layer", "Human Layer", "Sensor Layer"], "correct": 1, "explanation": "Remote Layer بتوفر وظائف الإدارة والتخزين والمراقبة عن بُعد.", "persist": "lecture1-24-29-q5", "week": 1}, {"id": "q-14702cb65e4863", "type": "mcq", "prompt": "A configuration error affects 15,000 identical IoT devices. Which challenge is illustrated?", "answerHTML": "<p>C. Scale<\/p><p>تكرار نفس الخطأ على عدد كبير من الأجهزة بوضح مشكلة Scale.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Heterogeneity", "Physical Exposure", "Scale", "User Experience"], "correct": 2, "explanation": "تكرار نفس الخطأ على عدد كبير من الأجهزة بوضح مشكلة Scale.", "persist": "lecture1-24-29-q6", "week": 1}, {"id": "q-b7589952da6b5e", "type": "mcq", "prompt": "Which activity means introducing and registering a new device in a deployment?", "answerHTML": "<p>A. Onboarding<\/p><p>Onboarding هي عملية إدخال الجهاز الجديد وتجهيزه ضمن النظام.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Onboarding", "Retirement", "Telemetry", "Actuation"], "correct": 0, "explanation": "Onboarding هي عملية إدخال الجهاز الجديد وتجهيزه ضمن النظام.", "persist": "lecture1-24-29-q7", "week": 1}, {"id": "q-e7c44eaa2b2692", "type": "mcq", "prompt": "Which process removes a device from active service?", "answerHTML": "<p>D. Retirement<\/p><p>Retirement تعني إخراج الجهاز من الخدمة.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Inventory", "Communication", "Maintenance", "Retirement"], "correct": 3, "explanation": "Retirement تعني إخراج الجهاز من الخدمة.", "persist": "lecture1-24-29-q8", "week": 1}, {"id": "q-a25a6f7219731f", "type": "mcq", "prompt": "Why may security assumptions become outdated during a device's lifetime?", "answerHTML": "<p>B. Networks, services, software dependencies, and ownership may change<\/p><p>البيئة المحيطة بالجهاز ممكن تتغير خلال سنوات تشغيله.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Sensors always stop working", "Networks, services, software dependencies, and ownership may change", "IoT devices never receive maintenance", "All devices use identical software"], "correct": 1, "explanation": "البيئة المحيطة بالجهاز ممكن تتغير خلال سنوات تشغيله.", "persist": "lecture1-24-29-q9", "week": 1}, {"id": "q-dcd55b7a870db8", "type": "mcq", "prompt": "What should organizations know about long-deployed IoT devices?", "answerHTML": "<p>C. Which devices exist and whether they remain supportable<\/p><p>Visibility وSupportability نقطتان أساسيتان في السلايد.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Only their purchase price", "Only their physical color", "Which devices exist and whether they remain supportable", "Only the number of users"], "correct": 2, "explanation": "Visibility وSupportability نقطتان أساسيتان في السلايد.", "persist": "lecture1-24-29-q10", "week": 1}, {"id": "q-0eecb1789b6173", "type": "mcq", "prompt": "A patient sensor sends incorrect measurements to clinical staff. Which concern is most directly illustrated?", "answerHTML": "<p>A. Incorrect Data<\/p><p>المشكلة الأساسية هي Incorrect Data، لأنها مرتبطة بصحة القياسات.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Incorrect Data", "Scale", "Retirement", "Physical Actuation"], "correct": 0, "explanation": "المشكلة الأساسية هي Incorrect Data، لأنها مرتبطة بصحة القياسات.", "persist": "lecture1-24-29-q11", "week": 1}, {"id": "q-198fb70ef325ef", "type": "mcq", "prompt": "Which conclusion about the medical sensor scenario is most appropriate?", "answerHTML": "<p>D. The importance of each consequence depends on the system&#x27;s functions and context<\/p><p>لازم نحلل الوظائف الفعلية للجهاز، وما نفترض وجود Actuation أو Gateway بدون دليل.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Every sensor necessarily controls treatment", "Data exposure is the only relevant concern", "The system definitely includes a gateway", "The importance of each consequence depends on the system's functions and context"], "correct": 3, "explanation": "لازم نحلل الوظائف الفعلية للجهاز، وما نفترض وجود Actuation أو Gateway بدون دليل.", "persist": "lecture1-24-29-q12", "week": 1}, {"id": "q-3fb93ba27fe3c7", "type": "blank", "prompt": "_______ flows from the physical environment toward applications and services.", "answerHTML": "<p>Telemetry<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Telemetry", "week": 1}, {"id": "q-3d068d3f956567", "type": "blank", "prompt": "Control commands may influence device _______.", "answerHTML": "<p>behavior<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "behavior", "week": 1}, {"id": "q-6b4b55a26b43e2", "type": "blank", "prompt": "A system can expose sensitive _______ without performing physical actions.", "answerHTML": "<p>data<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "data", "week": 1}, {"id": "q-fd4d59688e3d71", "type": "blank", "prompt": "Door sensors and cameras belong to the _______ layer.", "answerHTML": "<p>Physical<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Physical", "week": 1}, {"id": "q-0e98dc8bc7007d", "type": "blank", "prompt": "Controllers and gateways belong to the _______ layer.", "answerHTML": "<p>Local<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Local", "week": 1}, {"id": "q-b571890f1e7c7e", "type": "blank", "prompt": "Dashboards and remote administration belong to the _______ layer.", "answerHTML": "<p>Remote<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Remote", "week": 1}, {"id": "q-8a6497a5bc8cf4", "type": "blank", "prompt": "Employees and administrators belong to the _______ layer.", "answerHTML": "<p>Human<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Human", "week": 1}, {"id": "q-11f5b16432b7aa", "type": "blank", "prompt": "A repeated configuration mistake across thousands of devices illustrates _______.", "answerHTML": "<p>Scale<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Scale", "week": 1}, {"id": "q-fd3599b1b2d8b9", "type": "blank", "prompt": "The process of introducing devices into a deployment is called _______.", "answerHTML": "<p>Onboarding<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Onboarding", "week": 1}, {"id": "q-a26eb896301d60", "type": "blank", "prompt": "Maintaining a record of deployed devices is called _______.", "answerHTML": "<p>Inventory<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Inventory", "week": 1}, {"id": "q-bfb801eb747bd2", "type": "blank", "prompt": "Removing a device from active service is called _______.", "answerHTML": "<p>Retirement<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Retirement", "week": 1}, {"id": "q-3e673dc065e1e6", "type": "blank", "prompt": "Organizations should know whether deployed devices remain _______.", "answerHTML": "<p>Supportable<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Supportable", "week": 1}, {"id": "q-f3d1184f3e870d", "type": "short", "prompt": "Q1. Identify four attack-surface elements.", "answerHTML": "<p>Answer: Maintenance port, wireless interface, cloud service interface, and mobile application interface.<\/p>", "group": "32", "lecture": "2", "href": "lesson.html#slide-32", "context": "A smart camera has a maintenance port, wireless communication, a cloud service, and a mobile application.", "week": 1}, {"id": "q-cbe5bbf8bed563", "type": "short", "prompt": "Q2. Does the existence of these interfaces prove that the camera is insecure?", "answerHTML": "<p>Answer: No. A larger attack surface does not automatically mean that a system is insecure.<\/p>", "group": "32", "lecture": "2", "href": "lesson.html#slide-32", "context": "A smart camera has a maintenance port, wireless communication, a cloud service, and a mobile application.", "week": 1}, {"id": "q-6c6d3bf24403d0", "type": "short", "prompt": "Q3. What is the purpose of attack-surface mapping?", "answerHTML": "<p>Answer: To identify and understand the system's exposure and interaction points.<\/p><p>التحليل بالعربي: السؤال مش بطلب منك تذكر هجوم. هو بطلب تحدد الأماكن اللي ممكن يصير فيها تفاعل مع النظام.<\/p>", "group": "32", "lecture": "2", "href": "lesson.html#slide-32", "context": "A smart camera has a maintenance port, wireless communication, a cloud service, and a mobile application.", "week": 1}, {"id": "q-cebba58237cc51", "type": "short", "prompt": "Q1. Identify five attack-surface areas.", "answerHTML": "<p>Answer: Hardware, Firmware, Radio / Network, Cloud / API, and Application / Human.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device.", "week": 1}, {"id": "q-658bc40d704500", "type": "short", "prompt": "Q2. Which area includes wireless communication?", "answerHTML": "<p>Answer: Radio / Network.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device.", "week": 1}, {"id": "q-d1b0ca22eb7133", "type": "short", "prompt": "Q3. Which area includes the mobile application and user workflows?", "answerHTML": "<p>Answer: Application / Human.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device.", "week": 1}, {"id": "q-fde12300546e14", "type": "short", "prompt": "Q4. Which area includes device boot code?", "answerHTML": "<p>Answer: Firmware.<\/p><p>ملاحظة: لا تضيف Gateway للإجابة إلا إذا السيناريو ذكره أو كان واضحًا من تصميم النظام.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device.", "week": 1}, {"id": "q-692e90bbec403f", "type": "short", "prompt": "Q1. Which attack-surface area is most relevant?", "answerHTML": "<p>Answer: Hardware Surface.<\/p>", "group": "35", "lecture": "2", "href": "lesson.html#slide-35", "context": "A smart environmental sensor is installed in a public area. The device contains a processor, memory, and a physical debugging interface.", "week": 1}, {"id": "q-d71f5b0ae4ec52", "type": "short", "prompt": "Q2. What should a security engineer identify?", "answerHTML": "<p>Answer: The existing hardware interfaces and who can physically access them.<\/p>", "group": "35", "lecture": "2", "href": "lesson.html#slide-35", "context": "A smart environmental sensor is installed in a public area. The device contains a processor, memory, and a physical debugging interface.", "week": 1}, {"id": "q-b43cf0611f62d2", "type": "short", "prompt": "Q3. Does the presence of a debugging interface automatically prove a vulnerability?", "answerHTML": "<p>Answer: No. It is an interface that should be identified and understood.<\/p><p>الشرح بالعربي: السؤال بيركز على الوصول الفيزيائي والواجهات الموجودة بالجهاز، مش على تفاصيل استغلالها.<\/p>", "group": "35", "lecture": "2", "href": "lesson.html#slide-35", "context": "A smart environmental sensor is installed in a public area. The device contains a processor, memory, and a physical debugging interface.", "week": 1}, {"id": "q-24c87ebac281ab", "type": "mcq", "prompt": "What is the attack surface of an IoT system?", "answerHTML": "<p>B. The collection of places where unauthorized or unintended interaction could occur<\/p><p>التعريف الرسمي بيركز على أماكن التفاعل غير المصرّح أو غير المقصود، مش فقط الثغرات أو المنافذ.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Only known software vulnerabilities", "The collection of places where unauthorized or unintended interaction could occur", "Only open network ports", "Only physical hardware"], "correct": 1, "explanation": "التعريف الرسمي بيركز على أماكن التفاعل غير المصرّح أو غير المقصود، مش فقط الثغرات أو المنافذ.", "persist": "lecture2-30-35-q1", "week": 1}, {"id": "q-c267b73fbf24be", "type": "mcq", "prompt": "Does a larger attack surface automatically mean a system is insecure?", "answerHTML": "<p>C. No, it means more exposure to understand and manage<\/p><p>كبر سطح الهجوم يعني نقاط تعرّض أكثر لازم نفهمها ونديرها، ولا يثبت أن النظام غير آمن.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Yes, always", "Only for industrial IoT", "No, it means more exposure to understand and manage", "Only when a cloud service is used"], "correct": 2, "explanation": "كبر سطح الهجوم يعني نقاط تعرّض أكثر لازم نفهمها ونديرها، ولا يثبت أن النظام غير آمن.", "persist": "lecture2-30-35-q2", "week": 1}, {"id": "q-28e280f613b405", "type": "mcq", "prompt": "Which of the following is NOT excluded from IoT attack-surface mapping?", "answerHTML": "<p>A. Human workflows<\/p><p>Human Workflows جزء أساسي من Attack Surface، مثل الإعداد والصيانة واستعادة الحساب.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Human workflows", "Only network ports", "Only wireless connections", "Only firmware"], "correct": 0, "explanation": "Human Workflows جزء أساسي من Attack Surface، مثل الإعداد والصيانة واستعادة الحساب.", "persist": "lecture2-30-35-q3", "week": 1}, {"id": "q-0a847839edb9c7", "type": "mcq", "prompt": "Which attack-surface area includes UART, JTAG, and flash?", "answerHTML": "<p>D. Hardware<\/p><p>UART وJTAG وFlash موجودة ضمن Hardware في مخطط المحاضرة.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Cloud / API", "App / Human", "Gateway", "Hardware"], "correct": 3, "explanation": "UART وJTAG وFlash موجودة ضمن Hardware في مخطط المحاضرة.", "persist": "lecture2-30-35-q4", "week": 1}, {"id": "q-87f6c4d6ca4607", "type": "mcq", "prompt": "Which attack-surface area includes boot, secrets, and code?", "answerHTML": "<p>A. Firmware<\/p><p>Boot وSecrets وCode أمثلة Firmware Surface.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Firmware", "Gateway", "Radio / Network", "Human"], "correct": 0, "explanation": "Boot وSecrets وCode أمثلة Firmware Surface.", "persist": "lecture2-30-35-q5", "week": 1}, {"id": "q-78c72361140157", "type": "mcq", "prompt": "What does BLE stand for?", "answerHTML": "<p>B. Bluetooth Low Energy<\/p><p>BLE = Bluetooth Low Energy، وهي تقنية اتصال منخفضة الطاقة وقصيرة المدى.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Basic Local Ethernet", "Bluetooth Low Energy", "Binary Link Exchange", "Bluetooth Logical Extension"], "correct": 1, "explanation": "BLE = Bluetooth Low Energy، وهي تقنية اتصال منخفضة الطاقة وقصيرة المدى.", "persist": "lecture2-30-35-q6", "week": 1}, {"id": "q-d55b98cb41fb11", "type": "mcq", "prompt": "Which interface is commonly used for serial communication and debugging?", "answerHTML": "<p>C. UART<\/p><p>UART واجهة اتصال تسلسلي مستخدمة في التواصل وفحص المشكلات.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["UX", "API", "UART", "IP"], "correct": 2, "explanation": "UART واجهة اتصال تسلسلي مستخدمة في التواصل وفحص المشكلات.", "persist": "lecture2-30-35-q7", "week": 1}, {"id": "q-25e4d232de5925", "type": "mcq", "prompt": "Which interface may provide low-level hardware testing and debugging access?", "answerHTML": "<p>D. JTAG<\/p><p>JTAG مرتبطة بفحص الأجهزة وتصحيح المشكلات والوصول منخفض المستوى.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["BLE", "API", "UX", "JTAG"], "correct": 3, "explanation": "JTAG مرتبطة بفحص الأجهزة وتصحيح المشكلات والوصول منخفض المستوى.", "persist": "lecture2-30-35-q8", "week": 1}, {"id": "q-ed4d1d9fdab5de", "type": "mcq", "prompt": "What does API stand for?", "answerHTML": "<p>A. Application Programming Interface<\/p><p>API = Application Programming Interface.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Application Programming Interface", "Automatic Processing Interface", "Application Protection Internet", "Advanced Protocol Integration"], "correct": 0, "explanation": "API = Application Programming Interface.", "persist": "lecture2-30-35-q9", "week": 1}, {"id": "q-a4403598e0900d", "type": "mcq", "prompt": "What is the key Week 1 question for the hardware surface?", "answerHTML": "<p>B. What hardware interfaces exist and who can physically reach them?<\/p><p>في Week 1 بنحدد الواجهات والأشخاص القادرين على الوصول، مش تفاصيل الهجمات.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Which exploit is most effective?", "What hardware interfaces exist and who can physically reach them?", "How can firmware encryption be bypassed?", "How can a network be scanned?"], "correct": 1, "explanation": "في Week 1 بنحدد الواجهات والأشخاص القادرين على الوصول، مش تفاصيل الهجمات.", "persist": "lecture2-30-35-q10", "week": 1}, {"id": "q-af19938e427ceb", "type": "blank", "prompt": "The attack surface is the collection of places where an unauthorized or _______ interaction could occur.", "answerHTML": "<p>unintended<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "unintended", "week": 1}, {"id": "q-fb4d8adca5aea3", "type": "blank", "prompt": "A larger attack surface does not automatically mean a system is _______.", "answerHTML": "<p>insecure<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "insecure", "week": 1}, {"id": "q-813ba36bd29458", "type": "blank", "prompt": "The IoT attack surface includes physical interfaces, software interfaces, communication paths, service interfaces, and human _______.", "answerHTML": "<p>workflows<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "workflows", "week": 1}, {"id": "q-a4534209a3e1a5", "type": "blank", "prompt": "UART stands for Universal Asynchronous _______/Transmitter.", "answerHTML": "<p>Receiver<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Receiver", "week": 1}, {"id": "q-f7532aaf103a52", "type": "blank", "prompt": "JTAG stands for Joint Test Action _______.", "answerHTML": "<p>Group<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Group", "week": 1}, {"id": "q-fec7a11c692111", "type": "blank", "prompt": "BLE stands for Bluetooth Low _______.", "answerHTML": "<p>Energy<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Energy", "week": 1}, {"id": "q-751b0ffffa72a2", "type": "blank", "prompt": "IP stands for Internet _______.", "answerHTML": "<p>Protocol<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Protocol", "week": 1}, {"id": "q-bc2377e7e78fc7", "type": "blank", "prompt": "API stands for Application Programming _______.", "answerHTML": "<p>Interface<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Interface", "week": 1}, {"id": "q-ff0aa3dd20ee44", "type": "blank", "prompt": "UX stands for User _______.", "answerHTML": "<p>Experience<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Experience", "week": 1}, {"id": "q-6546c328ba8635", "type": "blank", "prompt": "Hardware includes processors, memory, storage, sensors, actuators, ports, and physical test or _______ interfaces.", "answerHTML": "<p>debug<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "debug", "week": 1}, {"id": "q-4e5aff86d5f03d", "type": "short", "prompt": "Q1. Which attack-surface area is described?", "answerHTML": "<p><strong>Answer:<\/strong> Firmware Surface.<\/p>", "group": "36", "lecture": "2", "href": "lesson.html#slide-36", "context": "A smart camera contains embedded software, device identifiers, configuration settings, and software libraries.", "week": 1}, {"id": "q-0ffa84eb3de2a5", "type": "short", "prompt": "Q2. Identify three elements stored in the firmware.", "answerHTML": "<p><strong>Answer:<\/strong> Device Identifiers, Configuration, and Software Libraries.<\/p>", "group": "36", "lecture": "2", "href": "lesson.html#slide-36", "context": "A smart camera contains embedded software, device identifiers, configuration settings, and software libraries.", "week": 1}, {"id": "q-7f118de4cf2a71", "type": "short", "prompt": "Q3. What is the main Week 1 security question?", "answerHTML": "<p><strong>Answer:<\/strong> What software exists on the device and how is it managed?<\/p><p><strong>التحليل:<\/strong> الكلمات <em>Embedded Software<\/em> و<em>Configuration<\/em> و<em>Libraries<\/em> بتدل مباشرة على Firmware.<\/p>", "group": "36", "lecture": "2", "href": "lesson.html#slide-36", "context": "A smart camera contains embedded software, device identifiers, configuration settings, and software libraries.", "week": 1}, {"id": "q-7eb022d846b7ef", "type": "short", "prompt": "Q1. Which attack-surface area is involved?", "answerHTML": "<p><strong>Answer:<\/strong> Radio / Network Surface.<\/p>", "group": "37", "lecture": "2", "href": "lesson.html#slide-37", "context": "An IoT sensor communicates with a nearby gateway over a local wireless connection. The gateway forwards data to a remote service.", "week": 1}, {"id": "q-f326a7a6637139", "type": "short", "prompt": "Q2. Identify two communication paths.", "answerHTML": "<p><strong>Answer:<\/strong> Sensor to Gateway, and Gateway to Remote Service.<\/p>", "group": "37", "lecture": "2", "href": "lesson.html#slide-37", "context": "An IoT sensor communicates with a nearby gateway over a local wireless connection. The gateway forwards data to a remote service.", "week": 1}, {"id": "q-85aa0202675440", "type": "short", "prompt": "Q3. What should the security engineer determine?", "answerHTML": "<p><strong>Answer:<\/strong> Who can communicate with the device, from where, and through which path.<\/p>", "group": "37", "lecture": "2", "href": "lesson.html#slide-37", "context": "An IoT sensor communicates with a nearby gateway over a local wireless connection. The gateway forwards data to a remote service.", "week": 1}, {"id": "q-5c4839788b379b", "type": "short", "prompt": "Q1. Which component is a shared dependency?", "answerHTML": "<p><strong>Answer:<\/strong> The Gateway.<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service.", "week": 1}, {"id": "q-4b3470c836e58a", "type": "short", "prompt": "Q2. What functions may depend on the gateway?", "answerHTML": "<p><strong>Answer:<\/strong> Communication, Management, and Local Processing.<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service.", "week": 1}, {"id": "q-4506a4f6edaf81", "type": "short", "prompt": "Q3. What is the main security question?", "answerHTML": "<p><strong>Answer:<\/strong> What devices and services trust the gateway?<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service.", "week": 1}, {"id": "q-c6f177b5a8f7a8", "type": "short", "prompt": "Q4. If the gateway fails, must every sensor stop measuring?", "answerHTML": "<p><strong>Answer:<\/strong> Not necessarily. The impact depends on which functions rely on the gateway.<\/p><p><strong>الشرح:<\/strong> فرّق بين استمرار وظيفة الحساس محليًا وبين قدرته على إرسال القياسات للخدمة البعيدة.<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service.", "week": 1}, {"id": "q-23088c8e7037ce", "type": "short", "prompt": "Q1. Which attack-surface area is illustrated?", "answerHTML": "<p><strong>Answer:<\/strong> Cloud / API Surface.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API.", "week": 1}, {"id": "q-1be638a1c7019a", "type": "short", "prompt": "Q2. Identify three remote functions.", "answerHTML": "<p><strong>Answer:<\/strong> Data Storage, User Management, and Command Delivery.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API.", "week": 1}, {"id": "q-eacb1e60b2db88", "type": "short", "prompt": "Q3. What does API stand for?", "answerHTML": "<p><strong>Answer:<\/strong> Application Programming Interface.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API.", "week": 1}, {"id": "q-790f9f131caa7b", "type": "short", "prompt": "Q4. What is the main Week 1 question?", "answerHTML": "<p><strong>Answer:<\/strong> What remote functions can affect the device or its data?<\/p><p><strong>ملاحظة من السلايد:<\/strong> تفاصيل حماية Cloud وAPI رح تنشرح في Week 11.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API.", "week": 1}, {"id": "q-ad5fec6a257e46", "type": "short", "prompt": "Q1. Which attack-surface area is illustrated?", "answerHTML": "<p><strong>Answer:<\/strong> Application / Human Surface.<\/p>", "group": "40", "lecture": "2", "href": "lesson.html#slide-40", "context": "A smart-home application allows users to view devices, share access with family members, and recover their accounts. Installers also use a maintenance interface.", "week": 1}, {"id": "q-b939d2378bc03e", "type": "short", "prompt": "Q2. Identify three human workflows.", "answerHTML": "<p><strong>Answer:<\/strong> Sharing, Account Recovery, and Maintenance.<\/p>", "group": "40", "lecture": "2", "href": "lesson.html#slide-40", "context": "A smart-home application allows users to view devices, share access with family members, and recover their accounts. Installers also use a maintenance interface.", "week": 1}, {"id": "q-b0a957bd9ff070", "type": "short", "prompt": "Q3. What is the main security question?", "answerHTML": "<p><strong>Answer:<\/strong> Which people can perform which actions through which interface?<\/p><p><strong>ملاحظة:<\/strong> تفاصيل Authentication وAuthorization رح تنشرح في Week 2.<\/p>", "group": "40", "lecture": "2", "href": "lesson.html#slide-40", "context": "A smart-home application allows users to view devices, share access with family members, and recover their accounts. Installers also use a maintenance interface.", "week": 1}, {"id": "q-615d7db4054366", "type": "short", "prompt": "Q1. Identify one Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Correct Lock Operation.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected.", "week": 1}, {"id": "q-c43169816b76a9", "type": "short", "prompt": "Q2. Identify one Interface.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application Interface.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected.", "week": 1}, {"id": "q-b5dc17071912a4", "type": "short", "prompt": "Q3. Identify one Dependency.", "answerHTML": "<p><strong>Answer:<\/strong> Cloud Service for Remote Control.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected.", "week": 1}, {"id": "q-769bb1ffd989c5", "type": "short", "prompt": "Q4. Identify one Trust Boundary.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application ↔ Cloud Service, where different trust assumptions may apply.<\/p><p><strong>التحليل:<\/strong> نفس النظام ممكن يحتوي على الأربعة معًا. المطلوب تعرف وظيفة كل مفهوم، مش تحفظ اسم المكوّن لحاله.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected.", "week": 1}, {"id": "q-632fb6ae640503", "type": "mcq", "prompt": "What does firmware include according to the lecture?", "answerHTML": "<p>B. Software and configuration stored on or executed by the device<\/p><p>Firmware يشمل البرمجيات والإعدادات المخزنة على الجهاز أو اللي الجهاز بنفذها.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Only physical sensors", "Software and configuration stored on or executed by the device", "Only cloud applications", "Only wireless connections"], "correct": 1, "explanation": "Firmware يشمل البرمجيات والإعدادات المخزنة على الجهاز أو اللي الجهاز بنفذها.", "persist": "lecture2-36-41-q1", "week": 1}, {"id": "q-c86d824a76b2ee", "type": "mcq", "prompt": "Which of the following may be contained in firmware?", "answerHTML": "<p>A. Device logic, identifiers, configuration, and libraries<\/p><p>السلايد بذكر Device Logic وIdentifiers وConfiguration وLibraries.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Device logic, identifiers, configuration, and libraries", "Only external cloud servers", "Only physical cables", "Only human workflows"], "correct": 0, "explanation": "السلايد بذكر Device Logic وIdentifiers وConfiguration وLibraries.", "persist": "lecture2-36-41-q2", "week": 1}, {"id": "q-1e29715ae4b3a0", "type": "mcq", "prompt": "What is the main Week 1 question about firmware?", "answerHTML": "<p>C. What software exists on the device and how is it managed?<\/p><p>Week 1 بيركز على تحديد البرمجيات وكيف بتتم إدارتها، مش طرق الهجوم.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["How to exploit firmware?", "How to bypass Secure Boot?", "What software exists on the device and how is it managed?", "How to break firmware signatures?"], "correct": 2, "explanation": "Week 1 بيركز على تحديد البرمجيات وكيف بتتم إدارتها، مش طرق الهجوم.", "persist": "lecture2-36-41-q3", "week": 1}, {"id": "q-4da7b8edfd045c", "type": "mcq", "prompt": "Which question best describes the Radio / Network Surface?", "answerHTML": "<p>A. Who can communicate with the device, from where, and through which path?<\/p><p>السؤال الرئيسي هو Who, From Where, Through Which Path.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Who can communicate with the device, from where, and through which path?", "Who manufactured the processor?", "How much storage does the cloud have?", "Who designed the user interface?"], "correct": 0, "explanation": "السؤال الرئيسي هو Who, From Where, Through Which Path.", "persist": "lecture2-36-41-q4", "week": 1}, {"id": "q-11dee9573a8d5a", "type": "mcq", "prompt": "A gateway connects many local sensors to a remote service. What can it become?", "answerHTML": "<p>D. A shared dependency<\/p><p>Gateway ممكن يكون Shared Dependency للاتصال أو الإدارة أو المعالجة المحلية.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["An actuator", "A user interface", "A firmware library", "A shared dependency"], "correct": 3, "explanation": "Gateway ممكن يكون Shared Dependency للاتصال أو الإدارة أو المعالجة المحلية.", "persist": "lecture2-36-41-q5", "week": 1}, {"id": "q-b211f60db22447", "type": "mcq", "prompt": "Which function may be provided by a cloud service?", "answerHTML": "<p>B. Device registration and user management<\/p><p>Cloud ممكن يسجل الأجهزة ويدير المستخدمين ويخزن البيانات ويرسل الأوامر.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Physical sensing only", "Device registration and user management", "Hardware testing only", "Local battery replacement"], "correct": 1, "explanation": "Cloud ممكن يسجل الأجهزة ويدير المستخدمين ويخزن البيانات ويرسل الأوامر.", "persist": "lecture2-36-41-q6", "week": 1}, {"id": "q-b58ee056b8c163", "type": "mcq", "prompt": "What does API stand for?", "answerHTML": "<p>C. Application Programming Interface<\/p><p>API = Application Programming Interface.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Advanced Processing Integration", "Automatic Protection Interface", "Application Programming Interface", "Application Physical Interaction"], "correct": 2, "explanation": "API = Application Programming Interface.", "persist": "lecture2-36-41-q7", "week": 1}, {"id": "q-4fa7d350d37bf5", "type": "mcq", "prompt": "Which of the following is a human workflow?", "answerHTML": "<p>A. Account recovery<\/p><p>Account Recovery من أمثلة Human Workflows المذكورة في Slide 40.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Account recovery", "Processor execution", "Sensor measurement", "Radio transmission"], "correct": 0, "explanation": "Account Recovery من أمثلة Human Workflows المذكورة في Slide 40.", "persist": "lecture2-36-41-q8", "week": 1}, {"id": "q-20ed99f6dedc2d", "type": "mcq", "prompt": "Which term describes something valuable that must be protected or kept functioning?", "answerHTML": "<p>D. Asset<\/p><p>Asset هو الشيء ذو القيمة اللي لازم نحميه أو نحافظ على تشغيله.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Interface", "Dependency", "Trust Boundary", "Asset"], "correct": 3, "explanation": "Asset هو الشيء ذو القيمة اللي لازم نحميه أو نحافظ على تشغيله.", "persist": "lecture2-36-41-q9", "week": 1}, {"id": "q-26cf97d90848fe", "type": "mcq", "prompt": "A point through which a component communicates or can be accessed is called:", "answerHTML": "<p>B. Interface<\/p><p>هذا تعريف Interface من السلايد.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Asset", "Interface", "Dependency", "Trust Boundary"], "correct": 1, "explanation": "هذا تعريف Interface من السلايد.", "persist": "lecture2-36-41-q10", "week": 1}, {"id": "q-434b63faf2e192", "type": "mcq", "prompt": "Another component or service required for correct operation is called:", "answerHTML": "<p>C. Dependency<\/p><p>هذا تعريف Dependency من المحاضرة.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Asset", "Interface", "Dependency", "Trust Boundary"], "correct": 2, "explanation": "هذا تعريف Dependency من المحاضرة.", "persist": "lecture2-36-41-q11", "week": 1}, {"id": "q-52bebb6461a95d", "type": "mcq", "prompt": "Where do data, commands, identity, or control cross areas with different trust assumptions?", "answerHTML": "<p>A. Trust Boundary<\/p><p>هذا تعريف Trust Boundary، ولازم تركز على Different Trust Assumptions.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Trust Boundary", "Firmware Library", "Device Inventory", "Physical Sensor"], "correct": 0, "explanation": "هذا تعريف Trust Boundary، ولازم تركز على Different Trust Assumptions.", "persist": "lecture2-36-41-q12", "week": 1}, {"id": "q-ea6c5b9d54cec2", "type": "blank", "prompt": "Firmware includes software and _______ stored on or executed by the device.", "answerHTML": "<p>configuration<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "configuration", "week": 1}, {"id": "q-b1dfd6a030c223", "type": "blank", "prompt": "Firmware may contain device logic, identifiers, configuration, and _______.", "answerHTML": "<p>libraries<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "libraries", "week": 1}, {"id": "q-eb17f650fe05d9", "type": "blank", "prompt": "Connected devices exchange data and _______ through communication paths.", "answerHTML": "<p>commands<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "commands", "week": 1}, {"id": "q-4a2e8487d8a22c", "type": "blank", "prompt": "Each reachable interface creates an _______ point.", "answerHTML": "<p>interaction<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "interaction", "week": 1}, {"id": "q-f4689b4ae3663e", "type": "blank", "prompt": "A gateway can become a shared _______ for multiple devices.", "answerHTML": "<p>dependency<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "dependency", "week": 1}, {"id": "q-a3e90a53cde44d", "type": "blank", "prompt": "APIs connect applications and services to _______ functions.", "answerHTML": "<p>backend<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "backend", "week": 1}, {"id": "q-bdfcd63bd37d3d", "type": "blank", "prompt": "Human workflows include setup, account recovery, sharing, installation, maintenance, and _______.", "answerHTML": "<p>support<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "support", "week": 1}, {"id": "q-1767721e652e0e", "type": "blank", "prompt": "An _______ is something valuable that must be protected or kept functioning.", "answerHTML": "<p>asset<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "asset", "week": 1}, {"id": "q-698d3a2c64f20a", "type": "blank", "prompt": "An _______ is a point through which a component communicates or can be accessed.", "answerHTML": "<p>interface<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "interface", "week": 1}, {"id": "q-a389848e839ebc", "type": "blank", "prompt": "A _______ is another component or service required for correct operation.", "answerHTML": "<p>dependency<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "dependency", "week": 1}, {"id": "q-0979b7acee4d42", "type": "blank", "prompt": "A trust boundary exists between areas with different trust _______.", "answerHTML": "<p>assumptions<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "assumptions", "week": 1}, {"id": "q-327eabcfc37c32", "type": "blank", "prompt": "A trust boundary may involve data, commands, identity, or _______.", "answerHTML": "<p>control<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "control", "week": 1}, {"id": "q-a58f2762978a4d", "type": "short", "prompt": "Question: Is an asset always a physical object?", "answerHTML": "<p><strong>Answer:<\/strong> No.<\/p><p>الـAsset ممكن يكون بيانات، وظيفة، حساب مستخدم، أو حتى ثقة المستخدمين.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "", "week": 1}, {"id": "q-08d9298fa8b9ac", "type": "short", "prompt": "Q1. Identify one Device Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Correct sensor operation.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions.", "week": 1}, {"id": "q-7d9b105d996791", "type": "short", "prompt": "Q2. Identify one Service Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Patient telemetry.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions.", "week": 1}, {"id": "q-c3441722a65765", "type": "short", "prompt": "Q3. Identify one Operational Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Service availability.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions.", "week": 1}, {"id": "q-83a27a14b5c932", "type": "short", "prompt": "Q4. Is user trust an asset?", "answerHTML": "<p><strong>Answer:<\/strong> Yes. It is an Operational Asset in the lecture's classification.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions.", "week": 1}, {"id": "q-79c266b9780290", "type": "short", "prompt": "Q1. Identify the Data Path.", "answerHTML": "<p><strong>Answer:<\/strong> Thermostat Sensor → Device → Cloud → Dashboard.<\/p>", "group": "43", "lecture": "2", "href": "lesson.html#slide-43", "context": "A thermostat measures room temperature and sends readings to a cloud dashboard. A user can adjust the target temperature using a mobile application.", "week": 1}, {"id": "q-8a3bd2690d1795", "type": "short", "prompt": "Q2. Identify the Control Path.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application → Cloud → Thermostat.<\/p>", "group": "43", "lecture": "2", "href": "lesson.html#slide-43", "context": "A thermostat measures room temperature and sends readings to a cloud dashboard. A user can adjust the target temperature using a mobile application.", "week": 1}, {"id": "q-09fff2c2e051a3", "type": "short", "prompt": "Q3. Why must both paths be included in an attack-surface map?", "answerHTML": "<p><strong>Answer:<\/strong> Because data and commands may cross different interfaces and trust boundaries.<\/p>", "group": "43", "lecture": "2", "href": "lesson.html#slide-43", "context": "A thermostat measures room temperature and sends readings to a cloud dashboard. A user can adjust the target temperature using a mobile application.", "week": 1}, {"id": "q-ee06b9a30994d8", "type": "short", "prompt": "Question: Is every communication path automatically a trust boundary?", "answerHTML": "<p><strong>Answer:<\/strong> No.<\/p><p>لازم يكون في اختلاف في افتراضات الثقة بين المنطقتين.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "", "week": 1}, {"id": "q-7a3176fe81abd3", "type": "short", "prompt": "Q1. Identify a possible trust boundary.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application ↔ Cloud Service.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "A mobile application communicates with a remote cloud service, which sends commands to a smart lock.", "week": 1}, {"id": "q-bf5d5401bb9a12", "type": "short", "prompt": "Q2. Why is it a possible trust boundary?", "answerHTML": "<p><strong>Answer:<\/strong> Because the application and remote service may operate under different trust assumptions.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "A mobile application communicates with a remote cloud service, which sends commands to a smart lock.", "week": 1}, {"id": "q-1c30ae0b2c5701", "type": "short", "prompt": "Q3. What is the Week 1 goal?", "answerHTML": "<p><strong>Answer:<\/strong> Identify where trust assumptions change, without analyzing detailed protection mechanisms.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "A mobile application communicates with a remote cloud service, which sends commands to a smart lock.", "week": 1}, {"id": "q-76ec95247967a1", "type": "short", "prompt": "Q1. Who can physically reach the sensor?", "answerHTML": "<p><strong>Answer:<\/strong> Maintenance Staff.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard.", "week": 1}, {"id": "q-91a7e90554a7a5", "type": "short", "prompt": "Q2. What data does it handle?", "answerHTML": "<p><strong>Answer:<\/strong> Sensor Measurements.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard.", "week": 1}, {"id": "q-da277abf3444d7", "type": "short", "prompt": "Q3. Where does data travel?", "answerHTML": "<p><strong>Answer:<\/strong> Sensor → Gateway → Remote Dashboard.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard.", "week": 1}, {"id": "q-86f6e919a31385", "type": "short", "prompt": "Q4. What other component may depend on the sensor?", "answerHTML": "<p><strong>Answer:<\/strong> The monitoring system may depend on the sensor's measurements.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard.", "week": 1}, {"id": "q-ca1a3e5d7f9924", "type": "short", "prompt": "Q1. Identify two Assets.", "answerHTML": "<p><strong>Answer:<\/strong> Video Recordings and Correct Camera Operation.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance.", "week": 1}, {"id": "q-9c1c546c808951", "type": "short", "prompt": "Q2. Identify two Interfaces.", "answerHTML": "<p><strong>Answer:<\/strong> Network Interface and Mobile Application Interface.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance.", "week": 1}, {"id": "q-6c731ea6848139", "type": "short", "prompt": "Q3. Identify one Dependency.", "answerHTML": "<p><strong>Answer:<\/strong> Cloud Service for remote recording access.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance.", "week": 1}, {"id": "q-0b8c732a419dcd", "type": "short", "prompt": "Q4. Identify one Human Workflow.", "answerHTML": "<p><strong>Answer:<\/strong> Installation or Maintenance.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance.", "week": 1}, {"id": "q-88dc4c6a6cb40d", "type": "short", "prompt": "Q5. Identify a possible Trust Boundary.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application ↔ Cloud Service, if trust assumptions differ.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance.", "week": 1}, {"id": "q-7808d8ac8b0a0e", "type": "short", "prompt": "Q1. Identify the Data Path.", "answerHTML": "<p><strong>Answer:<\/strong> Thermostat → Local Network → Remote Service → Mobile Application.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings.", "week": 1}, {"id": "q-c07204b4c43d6d", "type": "short", "prompt": "Q2. Identify the Control Path.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application → Remote Service → Local Network → Thermostat.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings.", "week": 1}, {"id": "q-1065d975cfab0b", "type": "short", "prompt": "Q3. Identify three Assets.", "answerHTML": "<p><strong>Answer:<\/strong> Temperature Measurements, Correct Thermostat Operation, and Service Availability.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings.", "week": 1}, {"id": "q-b2c2a2479c5194", "type": "short", "prompt": "Q4. Identify two possible Trust Boundaries.", "answerHTML": "<p><strong>Answer:<\/strong> Local Network ↔ Remote Service, and Application ↔ Remote Service, where trust assumptions differ.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings.", "week": 1}, {"id": "q-7c0f8a2a821e3d", "type": "short", "prompt": "Q5. Why should we avoid naming specific attacks at this stage?", "answerHTML": "<p><strong>Answer:<\/strong> Because the Week 1 goal is to identify interfaces, dependencies, physical access points, and trust boundaries before analyzing detailed threats.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings.", "week": 1}, {"id": "q-a0bd8db5e554e9", "type": "mcq", "prompt": "Which of the following is a Device Asset?", "answerHTML": "<p>B. Local configuration<\/p><p>Local Configuration من Device Assets حسب تصنيف Slide 42.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["User trust", "Local configuration", "Availability of service", "Fleet manageability"], "correct": 1, "explanation": "Local Configuration من Device Assets حسب تصنيف Slide 42.", "persist": "lecture2-42-47-q1", "week": 1}, {"id": "q-bc686b086301dc", "type": "mcq", "prompt": "Which is classified as a Service Asset?", "answerHTML": "<p>C. Telemetry<\/p><p>Telemetry موجودة تحت Service Assets.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Physical actuation", "Correct physical behavior", "Telemetry", "User trust"], "correct": 2, "explanation": "Telemetry موجودة تحت Service Assets.", "persist": "lecture2-42-47-q2", "week": 1}, {"id": "q-c36055a26622cc", "type": "mcq", "prompt": "Which is an Operational Asset?", "answerHTML": "<p>A. Fleet manageability<\/p><p>Fleet Manageability من Operational Assets.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Fleet manageability", "Local identifiers", "Device memory", "Stored device configuration"], "correct": 0, "explanation": "Fleet Manageability من Operational Assets.", "persist": "lecture2-42-47-q3", "week": 1}, {"id": "q-c0453ee76127bf", "type": "mcq", "prompt": "What should be included in an IoT data-and-control diagram?", "answerHTML": "<p>D. Both outward data flow and returning control commands<\/p><p>لازم نرسم Data Path وControl Path معًا.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Only sensor readings", "Only cloud interfaces", "Only device hardware", "Both outward data flow and returning control commands"], "correct": 3, "explanation": "لازم نرسم Data Path وControl Path معًا.", "persist": "lecture2-42-47-q4", "week": 1}, {"id": "q-81944691a576de", "type": "mcq", "prompt": "What does a trust boundary indicate?", "answerHTML": "<p>A. A change in trust assumptions<\/p><p>Trust Boundary بتشير لتغير افتراضات الثقة.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["A change in trust assumptions", "A guaranteed vulnerability", "Only a wireless connection", "A device identifier"], "correct": 0, "explanation": "Trust Boundary بتشير لتغير افتراضات الثقة.", "persist": "lecture2-42-47-q5", "week": 1}, {"id": "q-f86b2185dc2286", "type": "mcq", "prompt": "Which is an example of a possible trust boundary?", "answerHTML": "<p>B. Application to cloud with different trust assumptions<\/p><p>Application ↔ Cloud ممكن يكون Trust Boundary عندما تختلف افتراضات الثقة.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Two files in the same folder", "Application to cloud with different trust assumptions", "Two sensors with the same owner and trust context", "A temperature reading stored locally"], "correct": 1, "explanation": "Application ↔ Cloud ممكن يكون Trust Boundary عندما تختلف افتراضات الثقة.", "persist": "lecture2-42-47-q6", "week": 1}, {"id": "q-9115056efea566", "type": "mcq", "prompt": "Which set contains the three questions for every component?", "answerHTML": "<p>C. Who, What, Where<\/p><p>Slide 45 منظمة حول Who, What, Where.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["When, Why, How", "If, Then, Else", "Who, What, Where", "Read, Write, Execute"], "correct": 2, "explanation": "Slide 45 منظمة حول Who, What, Where.", "persist": "lecture2-42-47-q7", "week": 1}, {"id": "q-afb900d6c46e4d", "type": "mcq", "prompt": "Which question belongs under WHO?", "answerHTML": "<p>D. Who administers it?<\/p><p>Who administers it? من أسئلة WHO.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["What data does it handle?", "Where does trust change?", "What failure matters?", "Who administers it?"], "correct": 3, "explanation": "Who administers it? من أسئلة WHO.", "persist": "lecture2-42-47-q8", "week": 1}, {"id": "q-24a15d7e632c95", "type": "mcq", "prompt": "Which component is explicitly included in the smart camera example?", "answerHTML": "<p>B. Remote storage service<\/p><p>Slide 46 بتذكر Remote Storage ضمن Service.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Mandatory gateway", "Remote storage service", "Industrial robot", "Hospital controller"], "correct": 1, "explanation": "Slide 46 بتذكر Remote Storage ضمن Service.", "persist": "lecture2-42-47-q9", "week": 1}, {"id": "q-e1ae94e3bcaa89", "type": "mcq", "prompt": "What is requested in the smart thermostat mini exercise?", "answerHTML": "<p>A. Identify three assets without naming attacks<\/p><p>المطلوب تحديد ثلاثة Assets بدون تسمية هجمات.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Identify three assets without naming attacks", "Demonstrate firmware exploitation", "Calculate encryption key length", "List confirmed vulnerabilities"], "correct": 0, "explanation": "المطلوب تحديد ثلاثة Assets بدون تسمية هجمات.", "persist": "lecture2-42-47-q10", "week": 1}, {"id": "q-b4b8a44741aca4", "type": "blank", "prompt": "User accounts and telemetry are examples of _______ Assets.", "answerHTML": "<p>Service<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Service", "week": 1}, {"id": "q-7883d849bdc574", "type": "blank", "prompt": "Correct physical behavior is an _______ Asset.", "answerHTML": "<p>Operational<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Operational", "week": 1}, {"id": "q-0412be3fc6ccb9", "type": "blank", "prompt": "Device operation and local configuration are _______ Assets.", "answerHTML": "<p>Device<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Device", "week": 1}, {"id": "q-c6f1ef5417f24a", "type": "blank", "prompt": "A diagram should show both data and _______ paths.", "answerHTML": "<p>control<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "control", "week": 1}, {"id": "q-9eb81006646c5e", "type": "blank", "prompt": "A trust boundary marks a change in trust _______.", "answerHTML": "<p>assumptions<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "assumptions", "week": 1}, {"id": "q-673435f729afe1", "type": "blank", "prompt": "The three questions for every component are Who, What, and _______.", "answerHTML": "<p>Where<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Where", "week": 1}, {"id": "q-0e641807c1c9f9", "type": "blank", "prompt": "Who _______ it? is one of the WHO questions.", "answerHTML": "<p>administers<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "administers", "week": 1}, {"id": "q-2f870e13711e27", "type": "blank", "prompt": "What _______ does it handle? is one of the WHAT questions.", "answerHTML": "<p>data<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "data", "week": 1}, {"id": "q-ae66d90f1e151a", "type": "blank", "prompt": "Where does _______ change? is one of the WHERE questions.", "answerHTML": "<p>trust<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "trust", "week": 1}, {"id": "q-8e5351dc71f151", "type": "blank", "prompt": "The smart camera example includes remote storage, device management, notifications, and _______ services.", "answerHTML": "<p>account<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "account", "week": 1}, {"id": "q-5f3a6cf46cb656", "type": "blank", "prompt": "The smart thermostat exercise asks students to identify three _______.", "answerHTML": "<p>assets<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "assets", "week": 1}, {"id": "q-b8beef691ef267", "type": "blank", "prompt": "Students should identify assets without naming _______.", "answerHTML": "<p>attacks<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "attacks", "week": 1}, {"id": "q-5ca956f697ea77", "type": "short", "prompt": "Q1. What continues if the cloud is removed?", "answerHTML": "<p>Answer: Local recording may continue.<\/p>", "group": "48", "lecture": "2", "href": "lesson.html#slide-48", "context": "A smart camera records video locally but uses a cloud service for remote viewing and notifications.", "week": 1}, {"id": "q-459644912cc24d", "type": "short", "prompt": "Q2. What may stop working?", "answerHTML": "<p>Answer: Remote viewing and cloud-based notifications.<\/p>", "group": "48", "lecture": "2", "href": "lesson.html#slide-48", "context": "A smart camera records video locally but uses a cloud service for remote viewing and notifications.", "week": 1}, {"id": "q-9e77dc8bf39935", "type": "short", "prompt": "Q3. What does this scenario demonstrate?", "answerHTML": "<p>Answer: Architecture and dependencies affect system functionality and security exposure.<\/p>", "group": "48", "lecture": "2", "href": "lesson.html#slide-48", "context": "A smart camera records video locally but uses a cloud service for remote viewing and notifications.", "week": 1}, {"id": "q-51615b3a3ec3d1", "type": "short", "prompt": "Q1. What should be recorded for each interface?", "answerHTML": "<p>Answer: Name, Location, Who Can Reach It, Purpose, and Trust Change.<\/p>", "group": "50", "lecture": "2", "href": "lesson.html#slide-50", "context": "A building has door sensors connected to a gateway. Administrators monitor the sensors using a cloud dashboard.", "week": 1}, {"id": "q-59bcd379029377", "type": "short", "prompt": "Q2. Why is the purpose field important?", "answerHTML": "<p>Answer: It explains why the interface exists and what function it enables.<\/p>", "group": "50", "lecture": "2", "href": "lesson.html#slide-50", "context": "A building has door sensors connected to a gateway. Administrators monitor the sensors using a cloud dashboard.", "week": 1}, {"id": "q-ca51d0a22c8849", "type": "short", "prompt": "Q3. What does Trust Change help identify?", "answerHTML": "<p>Answer: Whether information or control crosses into a differently managed area.<\/p>", "group": "50", "lecture": "2", "href": "lesson.html#slide-50", "context": "A building has door sensors connected to a gateway. Administrators monitor the sensors using a cloud dashboard.", "week": 1}, {"id": "q-532c5f3927ff45", "type": "short", "prompt": "Q1. Identify an internal exposure.", "answerHTML": "<p>Answer: Sensor ↔ Gateway.<\/p>", "group": "51", "lecture": "2", "href": "lesson.html#slide-51", "context": "A factory gateway communicates with several sensors over a local network. The gateway also communicates with a remote cloud service.", "week": 1}, {"id": "q-9c122d0486210e", "type": "short", "prompt": "Q2. Identify a possible external exposure.", "answerHTML": "<p>Answer: A remotely reachable Cloud Service Interface.<\/p>", "group": "51", "lecture": "2", "href": "lesson.html#slide-51", "context": "A factory gateway communicates with several sensors over a local network. The gateway also communicates with a remote cloud service.", "week": 1}, {"id": "q-db5664cf3d9ec9", "type": "short", "prompt": "Q3. Why must internal interfaces be mapped?", "answerHTML": "<p>Answer: Because compromise of one component may make other internal interfaces reachable.<\/p>", "group": "51", "lecture": "2", "href": "lesson.html#slide-51", "context": "A factory gateway communicates with several sensors over a local network. The gateway also communicates with a remote cloud service.", "week": 1}, {"id": "q-3b77a1505d73ac", "type": "short", "prompt": "Q1. What type of interface is described?", "answerHTML": "<p>Answer: Management / Maintenance Interface.<\/p>", "group": "52", "lecture": "2", "href": "lesson.html#slide-52", "context": "An installer uses a maintenance interface to configure building sensors. After installation, the interface remains available on the devices.", "week": 1}, {"id": "q-e5205796af4eea", "type": "short", "prompt": "Q2. Why does it deserve attention?", "answerHTML": "<p>Answer: It may provide powerful functions and remain present after deployment.<\/p>", "group": "52", "lecture": "2", "href": "lesson.html#slide-52", "context": "An installer uses a maintenance interface to configure building sensors. After installation, the interface remains available on the devices.", "week": 1}, {"id": "q-ca6af985da2bbf", "type": "short", "prompt": "Q3. What is the Week 1 goal?", "answerHTML": "<p>Answer: Identify the interface and include it in the attack-surface map.<\/p>", "group": "52", "lecture": "2", "href": "lesson.html#slide-52", "context": "An installer uses a maintenance interface to configure building sensors. After installation, the interface remains available on the devices.", "week": 1}, {"id": "q-31031e788b93e4", "type": "short", "prompt": "Q1. What is the essential local function?", "answerHTML": "<p>Answer: Collecting patient measurements.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff.", "week": 1}, {"id": "q-d4d7ed144ecf6b", "type": "short", "prompt": "Q2. What function depends on the remote service?", "answerHTML": "<p>Answer: Displaying measurements to clinical staff remotely.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff.", "week": 1}, {"id": "q-7f0e74ebe552a7", "type": "short", "prompt": "Q3. What happens if the remote service becomes unavailable?", "answerHTML": "<p>Answer: Local sensing may continue, but remote access to readings may be interrupted.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff.", "week": 1}, {"id": "q-486879d3fc45cf", "type": "short", "prompt": "Q4. Why is dependency mapping important?", "answerHTML": "<p>Answer: It reveals hidden dependencies and supports availability and resilience analysis.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff.", "week": 1}, {"id": "q-9130ee290a9d79", "type": "mcq", "prompt": "What determines which functions continue if the cloud is removed?", "answerHTML": "<p>B. The system architecture and dependencies<\/p><p>النتيجة بتعتمد على بنية النظام والاعتمادات.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["The number of users only", "The system architecture and dependencies", "The device color", "The size of the application"], "correct": 1, "explanation": "النتيجة بتعتمد على بنية النظام والاعتمادات.", "persist": "lecture2-48-53-q1", "week": 1}, {"id": "q-2e7e4a4cabcbf6", "type": "mcq", "prompt": "What is the first step in the attack-surface mapping method?", "answerHTML": "<p>C. Draw the physical device and its purpose<\/p><p>الخطوة الأولى هي رسم الجهاز الفيزيائي وتحديد وظيفته.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["List vulnerabilities", "Draw trust boundaries", "Draw the physical device and its purpose", "Analyze encryption"], "correct": 2, "explanation": "الخطوة الأولى هي رسم الجهاز الفيزيائي وتحديد وظيفته.", "persist": "lecture2-48-53-q2", "week": 1}, {"id": "q-a389240a21cba0", "type": "mcq", "prompt": "Which step involves drawing telemetry and command paths?", "answerHTML": "<p>D. Step 4<\/p><p>Step 4: Draw data and control paths.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Step 1", "Step 2", "Step 3", "Step 4"], "correct": 3, "explanation": "Step 4: Draw data and control paths.", "persist": "lecture2-48-53-q3", "week": 1}, {"id": "q-3a21f10dbebe0d", "type": "mcq", "prompt": "Which field is part of an attack-surface inventory?", "answerHTML": "<p>A. Who can reach it<\/p><p>Who Can Reach It من الحقول الخمسة الأساسية.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Who can reach it", "Favorite device brand", "Purchase discount", "Screen resolution only"], "correct": 0, "explanation": "Who Can Reach It من الحقول الخمسة الأساسية.", "persist": "lecture2-48-53-q4", "week": 1}, {"id": "q-69835550fadba8", "type": "mcq", "prompt": "What does the Trust Change field identify?", "answerHTML": "<p>B. Whether information or control crosses into a differently managed area<\/p><p>الحقل بحدد إذا في انتقال إلى منطقة مختلفة بالإدارة أو افتراضات الثقة.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Device battery capacity", "Whether information or control crosses into a differently managed area", "Number of sensors", "Software purchase date"], "correct": 1, "explanation": "الحقل بحدد إذا في انتقال إلى منطقة مختلفة بالإدارة أو افتراضات الثقة.", "persist": "lecture2-48-53-q5", "week": 1}, {"id": "q-b74680e5b97757", "type": "mcq", "prompt": "Which is an example of internal exposure?", "answerHTML": "<p>C. Device-to-Gateway communication<\/p><p>Device-to-Gateway مثال على تفاعل داخلي.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["A public web interface", "An external remote service", "Device-to-Gateway communication", "A product advertisement"], "correct": 2, "explanation": "Device-to-Gateway مثال على تفاعل داخلي.", "persist": "lecture2-48-53-q6", "week": 1}, {"id": "q-38b9481a56d9f6", "type": "mcq", "prompt": "Which statement is correct about internal interfaces?", "answerHTML": "<p>D. They must still be included in attack-surface mapping<\/p><p>Internal مش معناها Trusted تلقائيًا.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["They are always secure", "They can be ignored", "They cannot be reached after a compromise", "They must still be included in attack-surface mapping"], "correct": 3, "explanation": "Internal مش معناها Trusted تلقائيًا.", "persist": "lecture2-48-53-q7", "week": 1}, {"id": "q-b18e5969e88276", "type": "mcq", "prompt": "Which interface may provide more powerful functions than ordinary user interaction?", "answerHTML": "<p>A. Management Interface<\/p><p>Management Interfaces ممكن توفر وظائف إدارة وتشخيص وصيانة أوسع.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Management Interface", "Temperature Sensor", "Physical Actuator", "Telemetry Record"], "correct": 0, "explanation": "Management Interfaces ممكن توفر وظائف إدارة وتشخيص وصيانة أوسع.", "persist": "lecture2-48-53-q8", "week": 1}, {"id": "q-d50333dcb8ad1f", "type": "mcq", "prompt": "Which interface may remain present after installation?", "answerHTML": "<p>B. An installation or maintenance interface<\/p><p>بعض واجهات التركيب والصيانة بتظل موجودة بعد تشغيل النظام.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["A deleted cloud service", "An installation or maintenance interface", "A removed device", "A disconnected sensor only"], "correct": 1, "explanation": "بعض واجهات التركيب والصيانة بتظل موجودة بعد تشغيل النظام.", "persist": "lecture2-48-53-q9", "week": 1}, {"id": "q-d2467c5f6ca080", "type": "mcq", "prompt": "What should dependency mapping distinguish?", "answerHTML": "<p>C. Essential operation and convenience features<\/p><p>التمييز بين Essential Operation وConvenience Features.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Wireless and wired colors", "Old and new logos", "Essential operation and convenience features", "Only device manufacturers"], "correct": 2, "explanation": "التمييز بين Essential Operation وConvenience Features.", "persist": "lecture2-48-53-q10", "week": 1}, {"id": "q-dc292e927edd4d", "type": "mcq", "prompt": "Which dependency may be required for remote viewing?", "answerHTML": "<p>A. Cloud Service<\/p><p>الخدمة السحابية ممكن تكون مطلوبة للوصول عن بُعد، حسب تصميم النظام.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Cloud Service", "Device packaging", "Screen wallpaper", "Physical label"], "correct": 0, "explanation": "الخدمة السحابية ممكن تكون مطلوبة للوصول عن بُعد، حسب تصميم النظام.", "persist": "lecture2-48-53-q11", "week": 1}, {"id": "q-d979f23691fa12", "type": "mcq", "prompt": "What is the main Week 1 goal when examining management interfaces?", "answerHTML": "<p>D. Identify their existence and include them in the map<\/p><p>Week 1 بيركز على تحديد الواجهات، مش استغلالها.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Exploit them", "Bypass authentication", "Remove all interfaces", "Identify their existence and include them in the map"], "correct": 3, "explanation": "Week 1 بيركز على تحديد الواجهات، مش استغلالها.", "persist": "lecture2-48-53-q12", "week": 1}, {"id": "q-2433505fe760b2", "type": "blank", "prompt": "Removing the cloud demonstrates why architecture and _______ affect security exposure.", "answerHTML": "<p>dependencies<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "dependencies", "week": 1}, {"id": "q-31a7c91ba1524b", "type": "blank", "prompt": "The first mapping step is to draw the physical device and its _______.", "answerHTML": "<p>purpose<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "purpose", "week": 1}, {"id": "q-94cdb8eb490bf9", "type": "blank", "prompt": "The fourth mapping step is to draw data and _______ paths.", "answerHTML": "<p>control<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "control", "week": 1}, {"id": "q-d0481dd45989c7", "type": "blank", "prompt": "The fifth mapping step includes interfaces, dependencies, physical access points, and trust _______.", "answerHTML": "<p>boundaries<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "boundaries", "week": 1}, {"id": "q-de2deb6d636c09", "type": "blank", "prompt": "An attack-surface inventory should record the interface name, location, who can reach it, purpose, and trust _______.", "answerHTML": "<p>change<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "change", "week": 1}, {"id": "q-202e54a8806f54", "type": "blank", "prompt": "External exposure is reachable from _______ the immediate device or trusted environment.", "answerHTML": "<p>outside<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "outside", "week": 1}, {"id": "q-9731b0f10fe47c", "type": "blank", "prompt": "Internal exposure exists _______ components inside the ecosystem.", "answerHTML": "<p>between<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "between", "week": 1}, {"id": "q-9ee98b777ea1c8", "type": "blank", "prompt": "Internal does not automatically mean _______.", "answerHTML": "<p>trusted<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "trusted", "week": 1}, {"id": "q-94abb390b621b2", "type": "blank", "prompt": "Management interfaces may provide more _______ functions than ordinary user interfaces.", "answerHTML": "<p>powerful<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "powerful", "week": 1}, {"id": "q-b0b400726a1ab9", "type": "blank", "prompt": "Some maintenance interfaces remain present after _______.", "answerHTML": "<p>deployment<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "deployment", "week": 1}, {"id": "q-f500d6233ddd5f", "type": "blank", "prompt": "Dependency mapping separates essential operation from _______ features.", "answerHTML": "<p>convenience<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "convenience", "week": 1}, {"id": "q-6b073c52e7e3ed", "type": "blank", "prompt": "Dependency mapping supports later availability and _______ analysis.", "answerHTML": "<p>resilience<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "resilience", "week": 1}, {"id": "q-34c7f34f1d17a8", "type": "short", "prompt": "Q1. Identify the four trust boundaries.", "answerHTML": "<p><strong>Model Answer:<\/strong><\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism.", "week": 1}, {"id": "q-45bb52af20c68f", "type": "short", "prompt": "Q2. Which boundary connects the digital and physical worlds?", "answerHTML": "<p><strong>Answer:<\/strong> Boundary 4.<\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism.", "week": 1}, {"id": "q-1abcfef72100e6", "type": "short", "prompt": "Q3. What should be identified at each boundary?", "answerHTML": "<p><strong>Answer:<\/strong> The identity, data, or command crossing the boundary.<\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism.", "week": 1}, {"id": "q-fc8e9a96a3f6ba", "type": "short", "prompt": "Q4. Should you explain encryption or authentication mechanisms in this exercise?", "answerHTML": "<p><strong>Answer:<\/strong> No. The Week 1 objective is to identify trust boundaries, not detailed security mechanisms.<\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism.", "week": 1}, {"id": "q-4d2bec95d25baf", "type": "short", "prompt": "Q1. Identify three mistakes.", "answerHTML": "<p><strong>Answer:<\/strong><\/p>", "group": "55", "lecture": "2", "href": "lesson.html#slide-55", "context": "A student maps a smart camera system by listing only open network ports and cloud storage. The student ignores installers and the mobile application, and assumes all local interfaces are trusted.", "week": 1}, {"id": "q-93561c86e2c8e8", "type": "short", "prompt": "Q2. What else should the student check?", "answerHTML": "<p><strong>Answer:<\/strong> Data and control paths, physical interfaces, dependencies, and trust boundaries.<\/p>", "group": "55", "lecture": "2", "href": "lesson.html#slide-55", "context": "A student maps a smart camera system by listing only open network ports and cloud storage. The student ignores installers and the mobile application, and assumes all local interfaces are trusted.", "week": 1}, {"id": "q-4bbe9bc337c02a", "type": "short", "prompt": "Q1. Which system illustrates a larger deployment scale?", "answerHTML": "<p><strong>Answer:<\/strong> System B.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": "", "week": 1}, {"id": "q-e610e6dc01c0f1", "type": "short", "prompt": "Q2. Which system has a shared gateway dependency?", "answerHTML": "<p><strong>Answer:<\/strong> System B.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": "", "week": 1}, {"id": "q-17bc9c22344512", "type": "short", "prompt": "Q3. Can we conclude that System B is less secure?", "answerHTML": "<p><strong>Answer:<\/strong> No. More devices and dependencies do not automatically prove insecurity.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": "", "week": 1}, {"id": "q-ca11d1b5f1a33c", "type": "short", "prompt": "Q4. What additional information is needed?", "answerHTML": "<p><strong>Answer:<\/strong> Interface reachability, physical accessibility, users, communication paths, trust boundaries, and system architecture.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": "", "week": 1}, {"id": "q-a5fc35d29b970b", "type": "mcq", "prompt": "Which is the first trust boundary in the smart lock example?", "answerHTML": "<p>B. Physical User ↔ Mobile Application<\/p><p>Boundary 1 هي Physical User ↔ Mobile Application.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Gateway ↔ Cloud", "Physical User ↔ Mobile Application", "Digital Command ↔ Locking Mechanism", "Device ↔ Database"], "correct": 1, "explanation": "Boundary 1 هي Physical User ↔ Mobile Application.", "persist": "lecture2-54-58-q1", "week": 1}, {"id": "q-265ad59b9a694e", "type": "mcq", "prompt": "Which boundary connects a digital command to physical locking behavior?", "answerHTML": "<p>D. Boundary 4<\/p><p>Boundary 4 تربط Digital Command مع Physical Locking Mechanism.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Boundary 1", "Boundary 2", "Boundary 3", "Boundary 4"], "correct": 3, "explanation": "Boundary 4 تربط Digital Command مع Physical Locking Mechanism.", "persist": "lecture2-54-58-q2", "week": 1}, {"id": "q-14e7ca22c8d984", "type": "mcq", "prompt": "What should be identified at each trust boundary during Week 1?", "answerHTML": "<p>A. Identity, data, or commands crossing it<\/p><p>المطلوب تحديد شو بعبر الحد: Identity أو Data أو Command، مش طريقة حمايته.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Identity, data, or commands crossing it", "Exact encryption algorithms", "Known exploits", "Password-cracking techniques"], "correct": 0, "explanation": "المطلوب تحديد شو بعبر الحد: Identity أو Data أو Command، مش طريقة حمايته.", "persist": "lecture2-54-58-q3", "week": 1}, {"id": "q-a93b6334bf7dc5", "type": "mcq", "prompt": "Which is a common attack-surface mapping mistake?", "answerHTML": "<p>C. Looking only for open network ports<\/p><p>التركيز فقط على Open Ports وإهمال باقي الواجهات خطأ.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Including human roles", "Mapping both data and control paths", "Looking only for open network ports", "Documenting dependencies"], "correct": 2, "explanation": "التركيز فقط على Open Ports وإهمال باقي الواجهات خطأ.", "persist": "lecture2-54-58-q4", "week": 1}, {"id": "q-03bf67e26b3327", "type": "mcq", "prompt": "Why is drawing only the data path insufficient?", "answerHTML": "<p>B. It may omit control commands returning to devices<\/p><p>لازم نرسم Data Path وControl Path.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Data paths are always insecure", "It may omit control commands returning to devices", "All IoT devices have no sensors", "Applications never send commands"], "correct": 1, "explanation": "لازم نرسم Data Path وControl Path.", "persist": "lecture2-54-58-q5", "week": 1}, {"id": "q-7f3832b9073115", "type": "mcq", "prompt": "Which statement about internal network components is correct?", "answerHTML": "<p>D. Their trust must not be assumed solely from being internal<\/p><p>Internal لا تعني Trusted تلقائيًا.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["They are always trusted", "They never need to be mapped", "They cannot be accessed physically", "Their trust must not be assumed solely from being internal"], "correct": 3, "explanation": "Internal لا تعني Trusted تلقائيًا.", "persist": "lecture2-54-58-q6", "week": 1}, {"id": "q-157aef4c63830f", "type": "mcq", "prompt": "Which factor is relevant when comparing the two IoT systems?", "answerHTML": "<p>A. Physical accessibility<\/p><p>المقارنة بتشمل Physical Accessibility وNumber of Devices وUsers وDependencies وFailure Consequences.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Physical accessibility", "Brand logo color", "Product packaging design", "Font size in the application"], "correct": 0, "explanation": "المقارنة بتشمل Physical Accessibility وNumber of Devices وUsers وDependencies وFailure Consequences.", "persist": "lecture2-54-58-q7", "week": 1}, {"id": "q-991bacafb86183", "type": "mcq", "prompt": "Can the larger attack surface be determined only by counting interfaces?", "answerHTML": "<p>C. No, architecture and exposure context also matter<\/p><p>عدد الواجهات لحاله مش كافي للحكم على Attack Surface.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Yes, always", "Yes, only for home IoT", "No, architecture and exposure context also matter", "Only when the system uses BLE"], "correct": 2, "explanation": "عدد الواجهات لحاله مش كافي للحكم على Attack Surface.", "persist": "lecture2-54-58-q8", "week": 1}, {"id": "q-338e9c3d09769a", "type": "mcq", "prompt": "How many components must be labeled in the Week 1 exit exercise?", "answerHTML": "<p>B. At least 5<\/p><p>المطلوب At least five components.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["At least 3", "At least 5", "Exactly 7", "At least 10"], "correct": 1, "explanation": "المطلوب At least five components.", "persist": "lecture2-54-58-q9", "week": 1}, {"id": "q-f3f79943eb5253", "type": "mcq", "prompt": "How many communication or interaction paths are required in the exit exercise?", "answerHTML": "<p>A. At least 4<\/p><p>المطلوب At least four paths.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["At least 4", "Exactly 2", "At least 8", "Only 1"], "correct": 0, "explanation": "المطلوب At least four paths.", "persist": "lecture2-54-58-q10", "week": 1}, {"id": "q-ef267e72b1f6f8", "type": "mcq", "prompt": "What is the minimum number of trust boundaries required?", "answerHTML": "<p>D. 3<\/p><p>المطلوب At least three trust boundaries.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["1", "2", "4", "3"], "correct": 3, "explanation": "المطلوب At least three trust boundaries.", "persist": "lecture2-54-58-q11", "week": 1}, {"id": "q-06aee0b594b8d1", "type": "mcq", "prompt": "What is the minimum number of physical access points required?", "answerHTML": "<p>B. 2<\/p><p>المطلوب At least two physical access points.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["1", "2", "3", "5"], "correct": 1, "explanation": "المطلوب At least two physical access points.", "persist": "lecture2-54-58-q12", "week": 1}, {"id": "q-b524bf45c5da56", "type": "mcq", "prompt": "Which topic belongs to Week 2 preparation?", "answerHTML": "<p>C. Authentication and Authorization<\/p><p>Week 2 بتتناول Device Identity وAuthentication وAuthorization وAccess Control وغيرها.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Only device packaging", "Only sensor calibration", "Authentication and Authorization", "Only hardware manufacturing"], "correct": 2, "explanation": "Week 2 بتتناول Device Identity وAuthentication وAuthorization وAccess Control وغيرها.", "persist": "lecture2-54-58-q13", "week": 1}, {"id": "q-0e136ecbf08c0a", "type": "blank", "prompt": "Boundary 1 in the smart lock example is physical user ↔ mobile _______.", "answerHTML": "<p>application<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "application", "week": 1}, {"id": "q-3bf41267736759", "type": "blank", "prompt": "Boundary 2 is application ↔ remote _______.", "answerHTML": "<p>service<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "service", "week": 1}, {"id": "q-794a5603bb8ed0", "type": "blank", "prompt": "Boundary 3 is remote service ↔ device or _______.", "answerHTML": "<p>gateway<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "gateway", "week": 1}, {"id": "q-5776b636738982", "type": "blank", "prompt": "Boundary 4 is digital command ↔ physical locking _______.", "answerHTML": "<p>mechanism<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "mechanism", "week": 1}, {"id": "q-e5a387dcf8e6b4", "type": "blank", "prompt": "At each trust boundary, identify what identity, data, or _______ is crossing.", "answerHTML": "<p>command<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "command", "week": 1}, {"id": "q-3c9eebaff9c30c", "type": "blank", "prompt": "A common mapping mistake is looking only for open network _______.", "answerHTML": "<p>ports<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "ports", "week": 1}, {"id": "q-2fbcd4eeb652a9", "type": "blank", "prompt": "A map must include both data flow and _______ commands.", "answerHTML": "<p>control<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "control", "week": 1}, {"id": "q-fa8ece17000ecc", "type": "blank", "prompt": "Being inside the local network does not automatically make a component _______.", "answerHTML": "<p>trusted<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "trusted", "week": 1}, {"id": "q-49e8192de41a33", "type": "blank", "prompt": "The comparison workshop includes physical accessibility, users, dependencies, and consequences of _______.", "answerHTML": "<p>failure<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "failure", "week": 1}, {"id": "q-18d7c5676d5bbf", "type": "blank", "prompt": "The exit exercise requires at least _______ components.", "answerHTML": "<p>five<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "five", "week": 1}, {"id": "q-0e206bdf3af038", "type": "blank", "prompt": "The exit exercise requires at least _______ communication or interaction paths.", "answerHTML": "<p>four<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "four", "week": 1}, {"id": "q-e92b3fcd3daaa2", "type": "blank", "prompt": "The exit exercise requires at least _______ trust boundaries.", "answerHTML": "<p>three<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "three", "week": 1}, {"id": "q-97a7e438dc032d", "type": "blank", "prompt": "The exit exercise requires at least _______ physical access points.", "answerHTML": "<p>two<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "two", "week": 1}, {"id": "q-544ddb13291494", "type": "blank", "prompt": "Week 2 introduces device identity, authentication, _______ and access control.", "answerHTML": "<p>authorization<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "authorization", "week": 1}, {"id": "q-93ed5fff5d2fe3", "type": "case", "prompt": "Smart Hospital Monitoring System", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Physical Device, Device Software, Connectivity, Gateway / Edge, Cloud Service, and User Application with human interaction.<\/li><li>The sensors.<\/li><li>Because they have limited battery power.<\/li><li>It connects the sensors to the cloud service and forwards their measurements.<\/li><li>Cloud-dependent storage, access, or remote management may become unavailable. Local functions depend on the design.<\/li><li>The environment and dependencies may change while the devices remain deployed; maintainability and support matter.<\/li><li>Their actions affect access, configuration, and operation.<\/li><\/ol>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "context": "A hospital uses multiple connected patient sensors to collect measurements. The sensors send their data through a local gateway to a cloud service. Medical staff use a web application to view the measurements. Some sensors have limited battery power, and the hospital has used the same devices for several years.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the six ecosystem components involved in the system.<\/li><li>Which component collects the patient measurements?<\/li><li>Why might the sensors prioritize low power?<\/li><li>What is the role of the gateway?<\/li><li>What happens if the cloud service becomes unavailable?<\/li><li>Why is the long deployment lifetime important?<\/li><li>Why should medical staff be considered part of the system boundary?<\/li><\/ol>", "week": 1}, {"id": "q-90b0808930088d", "type": "case", "prompt": "Smart Factory", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Scale, Heterogeneity, Constraints, and Long Lifetime.<\/li><li>The same mistake or configuration issue may affect thousands of devices.<\/li><li>Different vendors and platforms may require different management and update capabilities.<\/li><li>Devices may remain deployed while software support ends and dependencies or security assumptions become outdated.<\/li><\/ol>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "context": "A factory operates 5,000 connected sensors from different manufacturers. Some sensors have limited memory and battery power. The devices have been installed for many years, and some no longer receive software support.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify four IoT security challenges in this scenario.<\/li><li>Explain how scale affects security.<\/li><li>Why is heterogeneity important?<\/li><li>What does long lifetime imply?<\/li><\/ol>", "week": 1}, {"id": "q-de352c4994a214", "type": "case", "prompt": "Smart Building Control", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Because computation is tightly integrated with physical processes and feedback.<\/li><li>Sensing.<\/li><li>Actuation.<\/li><li>No. CPS classification is explained by the interaction between computation, physical processes, and feedback.<\/li><\/ol>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "context": "A smart building system continuously measures indoor temperature and automatically adjusts the cooling system using sensor feedback. The system also sends measurements to a cloud dashboard.", "questionsHTML": "<ol dir=\"ltr\"><li>Why can this system be considered a CPS?<\/li><li>Which capability allows the system to measure temperature?<\/li><li>Which capability allows it to adjust cooling?<\/li><li>Does the presence of cloud connectivity alone explain the CPS classification?<\/li><\/ol>", "week": 1}, {"id": "q-317c8bfc50ed23", "type": "case", "prompt": "Smart Lock Cloud Failure", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Dependencies.<\/li><li>Cloud Service.<\/li><li>No. The lock may continue its local operation while cloud-dependent remote control becomes unavailable.<\/li><\/ol>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "context": "A smart lock operates locally but relies on a cloud service for remote control. When the cloud becomes unavailable, users can no longer control the lock through the mobile application.", "questionsHTML": "<ol dir=\"ltr\"><li>Which IoT security challenge is illustrated?<\/li><li>What is the external dependency?<\/li><li>Does the cloud failure necessarily mean that the physical lock has stopped operating?<\/li><\/ol>", "week": 1}, {"id": "q-ccf32114a20547", "type": "case", "prompt": "Smart Building Security Responsibilities", "answerHTML": "<ol dir=\"ltr\"><li>Enterprise / Building IoT.<\/li><li>Device Manufacturer.<\/li><li>Service Provider.<\/li><li>Installer / Organization.<\/li><li>Security gaps may appear between the responsible parties.<\/li><\/ol>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "context": "A company installs smart access-control devices throughout its office building. The manufacturer provides the hardware and embedded software. A service provider manages the remote accounts. An installation team configures the devices and network, while employees operate the system daily.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the IoT category.<\/li><li>Who is responsible for hardware and embedded software?<\/li><li>Who manages account-related backend services?<\/li><li>Who handles deployment and configuration?<\/li><li>What problem may arise if responsibilities are unclear?<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-fd07eb73796eed", "type": "case", "prompt": "Smart Camera Analysis", "answerHTML": "<ol dir=\"ltr\"><li>Video monitoring.<\/li><li>Video recordings.<\/li><li>Remote service and network connection.<\/li><li>Physical Exposure.<\/li><li>Because the camera&#x27;s operation and security also depend on communication, remote storage, applications, and human interaction.<\/li><\/ol>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "context": "A smart camera collects video, stores recordings through a remote service, and allows users to view the video through a mobile application. The camera is installed in a publicly accessible area.", "questionsHTML": "<ol dir=\"ltr\"><li>What service does the camera support?<\/li><li>What type of data does it collect?<\/li><li>Identify two dependencies.<\/li><li>What physical security concern exists?<\/li><li>Why is analyzing only the camera hardware insufficient?<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-6c865697aff9f0", "type": "case", "prompt": "Consumer vs. Industrial IoT", "answerHTML": "<ol dir=\"ltr\"><li>System A: Consumer IoT. System B: Industrial / Infrastructure IoT.<\/li><li>System B.<\/li><li>Because the category affects the environment, ownership model, expected lifetime, and consequences of failure.<\/li><\/ol>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "context": "System A is a smart speaker used by a family at home. System B is a connected sensor used to monitor a critical industrial process.", "questionsHTML": "<ol dir=\"ltr\"><li>Classify System A and System B.<\/li><li>Which system is more directly associated with industrial operational consequences?<\/li><li>Why does the IoT category matter for security analysis?<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-58ac2b246de976", "type": "case", "prompt": "Smart Hospital System", "answerHTML": "<ol dir=\"ltr\"><li>Physical Layer: Patient Sensors. Local Layer: Gateways. Remote Layer: Monitoring Service and Dashboard. Human Layer: Clinical Staff.<\/li><li>Patient Sensors → Local Gateways → Remote Monitoring Service → Web Dashboard.<\/li><li>Scale, Dependencies, and Long Lifetime.<\/li><li>A repeated design or configuration mistake may affect thousands of devices.<\/li><li>Devices may outlive software support, and their dependencies or security assumptions may become outdated.<\/li><li>Incorrect data may mislead clinical staff, while service interruption may prevent access to patient measurements. Both can be important depending on clinical use.<\/li><li>No. The scenario describes measurement collection and reporting, not physical actuation.<\/li><\/ol>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "context": "A hospital operates 2,000 connected patient sensors across several buildings. The sensors collect measurements and send them through local gateways to a remote monitoring service. Clinical staff use a web dashboard to view the data. Some sensors have been installed for many years, and several software dependencies are no longer supported.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the physical, local, remote, and human layers.<\/li><li>Describe the telemetry path.<\/li><li>Identify three security challenges.<\/li><li>Explain why scale changes the security problem.<\/li><li>Why does long lifetime matter?<\/li><li>Compare the potential impact of incorrect data and service interruption.<\/li><li>Can we conclude that the sensors perform physical actuation?<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-dd586e06232218", "type": "case", "prompt": "Smart Factory Monitoring", "answerHTML": "<ol dir=\"ltr\"><li>Firmware, Radio / Network, Gateway / Edge, Cloud / API, and Application / Human.<\/li><li>The local gateway.<\/li><li>Sensor measurements or correct sensor operation.<\/li><li>Wireless communication interface or web application interface.<\/li><li>Gateway ↔ Cloud Service, if they operate under different trust assumptions.<\/li><\/ol>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "context": "A factory operates 300 connected sensors. Each sensor contains embedded firmware and communicates wirelessly with a local gateway. The gateway forwards measurements to a cloud service, where administrators monitor the system through a web application.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify five attack-surface areas.<\/li><li>What is the shared dependency?<\/li><li>Identify one asset.<\/li><li>Identify one interface.<\/li><li>Identify one possible trust boundary.<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-7167f6afcfca32", "type": "case", "prompt": "Smart Camera Remote Access", "answerHTML": "<ol dir=\"ltr\"><li>Application / Human Surface.<\/li><li>Cloud / API Surface.<\/li><li>Video recordings.<\/li><li>The remote service for remote access to recordings.<\/li><li>Mobile Application ↔ Remote Service, if their trust assumptions differ.<\/li><\/ol>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "context": "A smart camera stores recordings in a remote service. Users access the recordings through a mobile application. The application also allows account recovery and sharing access with family members.", "questionsHTML": "<ol dir=\"ltr\"><li>Which attack-surface area includes account recovery?<\/li><li>Which area includes remote recording storage?<\/li><li>Identify one asset.<\/li><li>Identify one dependency.<\/li><li>Identify a possible trust boundary.<\/li><\/ol>", "answerOrigin": "study", "week": 1}, {"id": "q-ce53bce2051a91", "type": "case", "prompt": "Connected Medical Sensor", "answerHTML": "<ol dir=\"ltr\"><li>Patient measurements or correct sensor operation.<\/li><li>The sensor network interface.<\/li><li>The remote service for displaying readings to clinical staff.<\/li><li>Local Network ↔ Remote Service, if their trust assumptions differ.<\/li><li>An interface is a point of communication or access; a dependency is another component or service required for correct operation.<\/li><\/ol>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "context": "A hospital uses connected medical sensors to collect patient measurements. The sensors communicate through a local network and depend on a remote service to display readings to clinical staff.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify one asset.<\/li><li>Identify one interface.<\/li><li>Identify one dependency.<\/li><li>Identify one trust boundary.<\/li><li>What is the most important distinction between an interface and a dependency?<\/li><\/ol>", "answerOrigin": "study", "week": 1}, {"id": "q-78e8519a17bca8", "type": "case", "prompt": "Smart Building Security System", "answerHTML": "<ol dir=\"ltr\"><li>Device Asset: Correct camera operation. Service Asset: Stored video recordings. Operational Asset: Availability of the monitoring service.<\/li><li>Camera / Door Sensor → Local Network → Remote Service → Web Application.<\/li><li>Web Application → Remote Service → Local Network → Controllable Device.<\/li><li>Local Network ↔ Remote Service; Web Application ↔ Remote Service. Both depend on differences in trust assumptions.<\/li><li>WHO: Security administrators and maintenance staff. WHAT: Sensor measurements, video recordings, and control commands. WHERE: Devices are deployed across several buildings, with data traveling to a remote service.<\/li><li>Device Network Interface, Remote Service Interface, and Web Application Interface.<\/li><li>Because control commands can return to devices and may affect physical behavior. Mapping only telemetry would omit those interactions.<\/li><\/ol>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "context": "A company operates smart cameras and door sensors across several buildings. The devices send measurements and video recordings through local networks to a remote service. Security administrators use a web application to monitor the buildings and send control commands. Maintenance staff can physically access some devices.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify one Device Asset, one Service Asset, and one Operational Asset.<\/li><li>Describe the Data Path.<\/li><li>Describe a possible Control Path.<\/li><li>Identify two possible Trust Boundaries.<\/li><li>Answer one WHO, one WHAT, and one WHERE question about the system.<\/li><li>Identify three interfaces.<\/li><li>Explain why drawing only the Data Path would be insufficient.<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-3da69d5b492bcf", "type": "case", "prompt": "Smart Building Access Control", "answerHTML": "<ol dir=\"ltr\"><li>Smart Lock, Gateway, Remote Service, Mobile Application, Web Dashboard.<\/li><li>Employee ↔ Mobile Application; Mobile Application ↔ Remote Service; Remote Service ↔ Gateway; Gateway ↔ Smart Lock.<\/li><li>User ↔ Application; Application ↔ Remote Service; Remote Service ↔ Gateway. These should be checked against the system&#x27;s actual trust assumptions.<\/li><li>Smart Lock Hardware and Gateway Hardware.<\/li><li>Assets: Correct Lock Operation and User Access Permissions. Dependencies: Remote Service and Gateway for the described remote-control path.<\/li><li>Employees, Installers, and Administrators.<\/li><li>The map could omit commands sent back to unlock or control the physical locks.<\/li><li>A gateway should not be considered trusted only because it is inside the local network.<\/li><li>Device Identity, Authentication, Authorization, Access Control, and Trust.<\/li><\/ol>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "context": "A company operates smart door locks in multiple buildings. Employees use a mobile application to request access. The application communicates with a remote service, which forwards commands through local gateways to the locks. Installers can physically access the locks and gateways for maintenance. Administrators manage user access through a web dashboard.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify five system components.<\/li><li>Identify four communication or interaction paths.<\/li><li>Identify three possible trust boundaries.<\/li><li>Identify two physical access points.<\/li><li>Identify two assets and two dependencies.<\/li><li>Identify two human roles.<\/li><li>What could be missing if the map shows only telemetry?<\/li><li>Why should local gateways not automatically be considered trusted?<\/li><li>Which Week 2 concepts will help analyze access decisions?<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-c22b6cff37736e", "type": "case", "prompt": "Smart Factory Monitoring System", "answerHTML": "<ol dir=\"ltr\"><li>Sensors → Local Gateway → Cloud Platform → Web Dashboard. Add Administrators and Installers, and mark physical maintenance interfaces and possible trust boundaries.<\/li><li>Sensor ↔ Gateway, Gateway ↔ local device-management functions (if present), and internal sensor maintenance access. The scenario explicitly establishes Sensor ↔ Gateway; other internal paths must be verified rather than assumed.<\/li><li>The remotely reachable Cloud Platform or Dashboard interface.<\/li><li>The sensor maintenance interface used by installers.<\/li><li>Name: Sensor Maintenance Interface. Location: Physical Sensor. Who Can Reach It: Installers. Purpose: Maintenance. Trust Change: Depends on who manages the interface and its trust context.<\/li><li>Local sensor measurement collection.<\/li><li>Cloud-based remote monitoring through the dashboard.<\/li><li>Dependencies: Gateway for forwarding measurements; Cloud Platform for remote monitoring. Possible Trust Boundaries: Sensor ↔ Gateway and Gateway ↔ Cloud, if their trust assumptions differ.<\/li><li>Internal interfaces still matter because compromise of one component may make another internal interface reachable.<\/li><\/ol>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "context": "A factory operates 500 connected environmental sensors. Each sensor collects measurements and sends them to a local gateway. The gateway forwards the data to a cloud platform. Administrators use a web dashboard to monitor the factory. Installers can access a maintenance interface on each sensor. The cloud platform is required for remote monitoring, but sensors can continue collecting measurements locally.", "questionsHTML": "<ol dir=\"ltr\"><li>Draw a first-pass attack-surface map.<\/li><li>Identify three internal interfaces or interaction paths.<\/li><li>Identify one possible external exposure.<\/li><li>Which management interface deserves special attention?<\/li><li>Create an inventory record for the sensor maintenance interface.<\/li><li>What continues if the cloud becomes unavailable?<\/li><li>What functionality may be interrupted?<\/li><li>Identify two dependencies and two possible trust boundaries.<\/li><li>Explain why the internal network cannot automatically be considered trusted.<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-d07018f8ca9a6f", "type": "case", "prompt": "Smart Building Access System", "answerHTML": "<ol dir=\"ltr\"><li>Hardware, Firmware, Radio / Network, Gateway, Cloud / API, and Application / Human.<\/li><li>Hardware Surface.<\/li><li>Firmware Surface.<\/li><li>Radio / Network Surface.<\/li><li>The gateway connects local devices to other networks or remote services and acts as a shared communication or trust point.<\/li><li>Cloud / API Surface.<\/li><li>Because human workflows such as administration, installation, and maintenance are part of the system&#x27;s attack surface.<\/li><li>No. Interfaces indicate exposure that must be understood and managed; they do not automatically prove insecurity.<\/li><\/ol>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "context": "A company operates smart door locks connected through a local wireless network. The devices contain embedded firmware and physical debugging interfaces. A gateway connects the locks to a cloud management service. Administrators use a web application to manage access permissions, while installers perform device maintenance.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the six attack-surface areas in this system.<\/li><li>Which area includes physical debugging interfaces?<\/li><li>Which area includes embedded code and configuration?<\/li><li>Which area includes wireless communication?<\/li><li>What is the role of the gateway?<\/li><li>Which area includes cloud management functions?<\/li><li>Why must administrators and installers be included in the attack-surface map?<\/li><li>Does the presence of these interfaces automatically prove the system is insecure?<\/li><\/ol>", "answerOrigin": "source", "week": 1}, {"id": "q-9f7c67487ff346", "type": "mcq", "prompt": "What does CPS stand for?", "answerHTML": "<p>B. Cyber-Physical System<\/p><p>CPS = Cyber-Physical System.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-1", "options": ["Cloud Processing Service", "Cyber-Physical System", "Connected Protection System", "Computer Protocol Security"], "correct": 1, "explanation": "CPS = Cyber-Physical System.", "persist": "final-mcq-1", "week": 1}, {"id": "q-67ae4dc6552a9c", "type": "mcq", "prompt": "Which component interacts with the physical environment?", "answerHTML": "<p>C. Sensor or Actuator<\/p><p>Sensor بجمع معلومات من البيئة، وActuator بنفذ فعلًا فيزيائيًا.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-2", "options": ["Cloud Storage", "Web Application", "Sensor or Actuator", "Remote Database"], "correct": 2, "explanation": "Sensor بجمع معلومات من البيئة، وActuator بنفذ فعلًا فيزيائيًا.", "persist": "final-mcq-2", "week": 1}, {"id": "q-189cefc8d36d81", "type": "mcq", "prompt": "Which component may aggregate data and translate communication?", "answerHTML": "<p>A. Gateway / Edge<\/p><p>Gateway ممكن يجمع بيانات من عدة أجهزة ويكيّف الاتصال بينها وبين الخدمات.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-3", "options": ["Gateway / Edge", "User Account", "UX", "Sensor Housing"], "correct": 0, "explanation": "Gateway ممكن يجمع بيانات من عدة أجهزة ويكيّف الاتصال بينها وبين الخدمات.", "persist": "final-mcq-3", "week": 1}, {"id": "q-f19728a4694169", "type": "mcq", "prompt": "Which is a common IoT security challenge?", "answerHTML": "<p>D. Long deployment lifetime<\/p><p>Long Lifetime أحد تحديات أمن IoT؛ البيئة والدعم ممكن يتغيروا خلال تشغيل الجهاز.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-4", "options": ["All devices have unlimited resources", "Every device has the same operating system", "Devices never change ownership", "Long deployment lifetime"], "correct": 3, "explanation": "Long Lifetime أحد تحديات أمن IoT؛ البيئة والدعم ممكن يتغيروا خلال تشغيل الجهاز.", "persist": "final-mcq-4", "week": 1}, {"id": "q-de6bd9de0e49e4", "type": "mcq", "prompt": "What does OTA stand for?", "answerHTML": "<p>B. Over-the-Air<\/p><p>OTA = Over-the-Air؛ توصيل البرمجيات أو الإعدادات عن بُعد.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-5", "options": ["Online Transfer Access", "Over-the-Air", "Open Technology Application", "Operating Trust Agreement"], "correct": 1, "explanation": "OTA = Over-the-Air؛ توصيل البرمجيات أو الإعدادات عن بُعد.", "persist": "final-mcq-5", "week": 1}, {"id": "q-d9d03221ce9e64", "type": "mcq", "prompt": "Which party is responsible for hardware and embedded software decisions?", "answerHTML": "<p>C. Device Manufacturer<\/p><p>Device Manufacturer مسؤول عن قرارات Hardware وEmbedded Software.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-6", "options": ["User", "Installer", "Device Manufacturer", "Cloud Customer"], "correct": 2, "explanation": "Device Manufacturer مسؤول عن قرارات Hardware وEmbedded Software.", "persist": "final-mcq-6", "week": 1}, {"id": "q-c5bb02bc7a6ffb", "type": "mcq", "prompt": "Which direction does telemetry usually travel?", "answerHTML": "<p>A. From physical environment toward applications and services<\/p><p>Telemetry بيانات القياس والمراقبة المتجهة من البيئة الفيزيائية نحو التطبيقات والخدمات.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-7", "options": ["From physical environment toward applications and services", "Only from cloud to actuator", "Only between users", "From application to locking mechanism"], "correct": 0, "explanation": "Telemetry بيانات القياس والمراقبة المتجهة من البيئة الفيزيائية نحو التطبيقات والخدمات.", "persist": "final-mcq-7", "week": 1}, {"id": "q-a34d7687026391", "type": "mcq", "prompt": "What does UART stand for?", "answerHTML": "<p>D. Universal Asynchronous Receiver/Transmitter<\/p><p>UART = Universal Asynchronous Receiver/Transmitter.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-8", "options": ["Universal Access Radio Technology", "Unified Application Routing Tool", "User Authentication Resource Token", "Universal Asynchronous Receiver/Transmitter"], "correct": 3, "explanation": "UART = Universal Asynchronous Receiver/Transmitter.", "persist": "final-mcq-8", "week": 1}, {"id": "q-0c85246ce65dd2", "type": "mcq", "prompt": "Which term describes something valuable that must be protected or kept functioning?", "answerHTML": "<p>B. Asset<\/p><p>Asset هو شيء ذو قيمة لازم نحميه أو نحافظ على عمله.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-9", "options": ["Interface", "Asset", "Dependency", "Gateway"], "correct": 1, "explanation": "Asset هو شيء ذو قيمة لازم نحميه أو نحافظ على عمله.", "persist": "final-mcq-9", "week": 1}, {"id": "q-c1908b7f9c9b91", "type": "mcq", "prompt": "Which term describes another component or service required for correct operation?", "answerHTML": "<p>C. Dependency<\/p><p>Dependency مكوّن أو خدمة مطلوبة حتى تعمل وظيفة النظام بشكل صحيح.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-10", "options": ["Telemetry", "Interface", "Dependency", "UX"], "correct": 2, "explanation": "Dependency مكوّن أو خدمة مطلوبة حتى تعمل وظيفة النظام بشكل صحيح.", "persist": "final-mcq-10", "week": 1}, {"id": "q-e8e3591d81ec0a", "type": "mcq", "prompt": "Which of the following is a possible trust boundary?", "answerHTML": "<p>A. Mobile Application ↔ Remote Service, where trust assumptions differ<\/p><p>Trust Boundary بتظهر لما تتغير افتراضات الثقة بين منطقتين.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-11", "options": ["Mobile Application ↔ Remote Service, where trust assumptions differ", "A device label", "A temperature value", "A processor clock"], "correct": 0, "explanation": "Trust Boundary بتظهر لما تتغير افتراضات الثقة بين منطقتين.", "persist": "final-mcq-11", "week": 1}, {"id": "q-7265eab7a6c555", "type": "mcq", "prompt": "Which is a management interface?", "answerHTML": "<p>D. A diagnostics interface<\/p><p>Diagnostics Interface واجهة للفحص والتشخيص، وهي من واجهات الإدارة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-12", "options": ["A temperature reading", "A camera lens", "A device battery", "A diagnostics interface"], "correct": 3, "explanation": "Diagnostics Interface واجهة للفحص والتشخيص، وهي من واجهات الإدارة.", "persist": "final-mcq-12", "week": 1}, {"id": "q-f2de6fc64b29b2", "type": "mcq", "prompt": "What should an attack-surface map include?", "answerHTML": "<p>C. Data and control paths<\/p><p>الخريطة بتشمل البيانات الخارجة والأوامر الراجعة للجهاز، مع المكونات والواجهات والاعتمادات وحدود الثقة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-13", "options": ["Only vulnerabilities", "Only network ports", "Data and control paths", "Only cloud services"], "correct": 2, "explanation": "الخريطة بتشمل البيانات الخارجة والأوامر الراجعة للجهاز، مع المكونات والواجهات والاعتمادات وحدود الثقة.", "persist": "final-mcq-13", "week": 1}, {"id": "q-08fe6fed4e99d7", "type": "mcq", "prompt": "Which statement is correct?", "answerHTML": "<p>B. Internal does not automatically mean trusted<\/p><p>وجود الواجهة داخل النظام لا يكفي وحده لاعتبارها موثوقة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-14", "options": ["All internal interfaces are trusted", "Internal does not automatically mean trusted", "Every gateway is optional in all systems", "IoT security concerns only the device"], "correct": 1, "explanation": "وجود الواجهة داخل النظام لا يكفي وحده لاعتبارها موثوقة.", "persist": "final-mcq-14", "week": 1}, {"id": "q-5fbb3157a797c1", "type": "mcq", "prompt": "What is the first step in attack-surface mapping?", "answerHTML": "<p>A. Draw the physical device and its purpose<\/p><p>الخطوة الأولى من Slide 49: Draw the physical device and its purpose.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-15", "options": ["Draw the physical device and its purpose", "Identify specific attacks", "Choose an encryption algorithm", "Remove the cloud"], "correct": 0, "explanation": "الخطوة الأولى من Slide 49: Draw the physical device and its purpose.", "persist": "final-mcq-15", "week": 1}, {"id": "q-c70414d0010b7f", "type": "blank", "prompt": "IoT stands for Internet of _______.", "answerHTML": "<p>Things<\/p><p>IoT = Internet of Things.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-1", "answer": "Things", "week": 1}, {"id": "q-cf904cb21a3e1f", "type": "blank", "prompt": "API stands for Application Programming _______.", "answerHTML": "<p>Interface<\/p><p>واجهة تواصل بين مكونات أو خدمات برمجية.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-2", "answer": "Interface", "week": 1}, {"id": "q-1ef46c8f46f850", "type": "blank", "prompt": "UX stands for User _______.", "answerHTML": "<p>Experience<\/p><p>بتتعلق بكيفية تفاعل الأشخاص مع المنتج وخطوات استخدامه.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-3", "answer": "Experience", "week": 1}, {"id": "q-4a087cd7d27ec3", "type": "blank", "prompt": "A _______ connects local devices to external networks or services.", "answerHTML": "<p>gateway<\/p><p>ممكن يربط الأجهزة المحلية بالخدمات الخارجية.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-4", "answer": "gateway", "week": 1}, {"id": "q-250bcf08a57949", "type": "blank", "prompt": "A _______ is a point through which a component communicates or can be accessed.", "answerHTML": "<p>interface<\/p><p>هذا تعريف Interface.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-5", "answer": "interface", "week": 1}, {"id": "q-e40dfd6849cb85", "type": "blank", "prompt": "A trust boundary involves different trust _______.", "answerHTML": "<p>assumptions<\/p><p>الاختلاف في Trust Assumptions هو الأساس.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-6", "answer": "assumptions", "week": 1}, {"id": "q-2db4efe1673f63", "type": "blank", "prompt": "Connected devices exchange data and _______ through communication paths.", "answerHTML": "<p>commands<\/p><p>الاتصالات بتنقل بيانات وأوامر.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-7", "answer": "commands", "week": 1}, {"id": "q-1107793bbd1f82", "type": "blank", "prompt": "The three questions for every component are Who, What, and _______.", "answerHTML": "<p>Where<\/p><p>Who–What–Where هي الأسئلة الثلاثة لكل مكوّن.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-8", "answer": "Where", "week": 1}, {"id": "q-3501dcadc2d0b1", "type": "blank", "prompt": "Internal does not automatically mean _______.", "answerHTML": "<p>trusted<\/p><p>وجود الواجهة داخل النظام مش دليل ثقة تلقائي.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-9", "answer": "trusted", "week": 1}, {"id": "q-443113fa948aee", "type": "blank", "prompt": "Dependency mapping separates essential operation from _______ features.", "answerHTML": "<p>convenience<\/p><p>Essential Operation مقابل Convenience Features.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-10", "answer": "convenience", "week": 1}, {"id": "q-2359ba5ccada7e", "type": "short", "prompt": "List THREE differences between Traditional IT and IoT.", "answerHTML": "<pre dir=\"ltr\">1. Traditional IT uses general-purpose computers; IoT often uses special-purpose devices.\n2. Traditional IT has frequent user interaction; IoT devices are often unattended.\n3. Traditional IT systems are usually easier to patch or replace; IoT devices may have long deployment lifetimes.<\/pre><p>احفظ ثلاث مقارنات من Slide 12، وكل نقطة واضحة لحالها.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-1", "week": 1}, {"id": "q-4e53c055858b90", "type": "short", "prompt": "Mention THREE IoT security challenges.", "answerHTML": "<pre dir=\"ltr\">Constraints, Physical Exposure, and Scale.<\/pre><p>كمان ممكن تذكر Heterogeneity أو Long Lifetime أو Dependencies.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-2", "week": 1}, {"id": "q-57ae740eb4aa12", "type": "short", "prompt": "List THREE responsibilities in an IoT ecosystem and the responsible party.", "answerHTML": "<pre dir=\"ltr\">1. Device Manufacturer — Hardware and embedded software decisions.\n2. Service Provider — Backend, remote management, and accounts.\n3. Installer / Organization — Deployment, network placement, and configuration.<\/pre><p>Slide 23: اربط كل جهة بمسؤوليتها، وممكن تذكر User / Operator كمان.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-3", "week": 1}, {"id": "q-b58e2fe60336e0", "type": "short", "prompt": "List the FIVE fields of an Attack Surface Inventory.", "answerHTML": "<pre dir=\"ltr\">Component or Interface Name; Location; Who Can Reach It; Purpose; Trust Change.<\/pre><p>هاي قائمة Slide 50، مهمة للحفظ.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-4", "week": 1}, {"id": "q-63060b24c921c3", "type": "short", "prompt": "Mention THREE common attack-surface mapping mistakes.", "answerHTML": "<pre dir=\"ltr\">1. Looking only for open network ports.\n2. Drawing only data flow and forgetting control commands.\n3. Assuming internal components are automatically trusted.<\/pre><p>كلها موجودة في Slide 55. ممكن بدل أي نقطة تذكر تجاهل الأشخاص أو البدء بالثغرات.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-5", "week": 1}, {"id": "q-a408e224ce31de", "type": "case", "prompt": "Smart Camera", "answerHTML": "<ol dir=\"ltr\"><li>Smart Camera, Home Network, Cloud Service, Mobile Application.<\/li><li>Video Recordings.<\/li><li>Cloud Service for remote recording access.<\/li><li>Camera Network Interface or Mobile Application Interface.<\/li><li>Mobile Application ↔ Cloud Service, if trust assumptions differ.<\/li><\/ol><p>الـAsset هو الشيء المهم، والـDependency شيء النظام بيعتمد عليه، والـInterface نقطة تواصل، والـTrust Boundary مكان اختلاف افتراضات الثقة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-case-1", "context": "A smart camera records video, connects to a home network, stores recordings in a remote cloud service, and allows the owner to view recordings using a mobile application.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify four ecosystem components.<\/li><li>Identify one asset.<\/li><li>Identify one dependency.<\/li><li>Identify one interface.<\/li><li>Identify one possible trust boundary.<\/li><\/ol>", "week": 1}, {"id": "q-6d0aa94acb4038", "type": "case", "prompt": "Connected Medical Sensor", "answerHTML": "<ol dir=\"ltr\"><li>Medical Sensor.<\/li><li>Patient Measurements.<\/li><li>Sensor → Communication Path → Remote Service → Clinical Staff.<\/li><li>Remote Service for displaying patient readings.<\/li><li>Clinical staff may lose access to remote readings. Local measurement may continue if the device supports it.<\/li><\/ol><p>ما بنفترض إنه الجهاز توقف تمامًا، لأن استمرار القياس المحلي بيعتمد على تصميمه.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-case-2", "context": "A connected medical sensor measures patient data and sends readings to a remote service used by clinical staff.", "questionsHTML": "<ol dir=\"ltr\"><li>What is the physical device?<\/li><li>What is the main data asset?<\/li><li>What is the Data Path?<\/li><li>Identify one dependency.<\/li><li>What may happen if the remote service becomes unavailable?<\/li><\/ol>", "week": 1}, {"id": "q-1eb8da2610fb66", "type": "diagram", "prompt": "Draw a simple attack-surface map for a smart thermostat. Your diagram must include the thermostat, local network, remote service, mobile application, and user. Show the Data Path, Control Path, and possible Trust Boundaries.", "answerHTML": "<div class=\"course-flow\" dir=\"ltr\"><span>User + Mobile Application<\/span><b>↔<\/b><span>Remote Service<\/span><b>↔<\/b><span>Local Network<\/span><b>↔<\/b><span>Smart Thermostat<\/span><\/div><p dir=\"ltr\"><b>Data Path:<\/b> Thermostat → Local Network → Remote Service → Mobile Application.<\/p><p dir=\"ltr\"><b>Control Path:<\/b> Mobile Application → Remote Service → Local Network → Thermostat.<\/p><p dir=\"ltr\"><b>Assets:<\/b> Temperature Measurements, Correct Thermostat Operation, Service Availability.<\/p><p dir=\"ltr\"><b>Possible Trust Boundaries:<\/b> Application ↔ Remote Service and Local Network ↔ Remote Service, where trust assumptions differ.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-diagram", "week": 1}, {"id": "q-e9ae4849631219", "type": "mcq", "prompt": "What does IoT stand for?", "answerHTML": "<p>B. Internet of Things<\/p><p>IoT = Internet of Things.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Internet of Technology", "Internet of Things", "Integration of Tools", "Internet of Telecommunications"], "correct": 1, "explanation": "IoT = Internet of Things.", "persist": "mini-direct-q1", "week": 1}, {"id": "q-af00c3aa1b8b82", "type": "mcq", "prompt": "Which component collects information from the physical environment?", "answerHTML": "<p>A. Sensor<\/p><p>Sensor بقرأ المعلومات من البيئة الفيزيائية.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Sensor", "Cloud", "Application", "Gateway"], "correct": 0, "explanation": "Sensor بقرأ المعلومات من البيئة الفيزيائية.", "persist": "mini-direct-q2", "week": 1}, {"id": "q-10c351afeac809", "type": "mcq", "prompt": "What does API stand for?", "answerHTML": "<p>A. Application Programming Interface<\/p><p>API = Application Programming Interface.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Application Programming Interface", "Automatic Protection Interface", "Advanced Program Integration", "Application Physical Interface"], "correct": 0, "explanation": "API = Application Programming Interface.", "persist": "mini-direct-q3", "week": 1}, {"id": "q-ef1d3de785bb4c", "type": "mcq", "prompt": "Which of the following is a Trust Boundary?", "answerHTML": "<p>C. A point where trust assumptions change<\/p><p>هي نقطة انتقال بين مناطق بافتراضات ثقة مختلفة.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["A device battery", "A sensor reading", "A point where trust assumptions change", "A device model number"], "correct": 2, "explanation": "هي نقطة انتقال بين مناطق بافتراضات ثقة مختلفة.", "persist": "mini-direct-q4", "week": 1}, {"id": "q-583df762fc4b46", "type": "mcq", "prompt": "Which path carries commands toward the physical device?", "answerHTML": "<p>B. Control Path<\/p><p>Control Path بنقل أوامر التحكم باتجاه الجهاز.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Data Path", "Control Path", "Storage Path", "Inventory Path"], "correct": 1, "explanation": "Control Path بنقل أوامر التحكم باتجاه الجهاز.", "persist": "mini-direct-q5", "week": 1}, {"id": "q-d751245f3c4810", "type": "mcq", "prompt": "Which is a common mistake in attack-surface mapping?", "answerHTML": "<p>D. Looking only for open ports<\/p><p>التركيز على Open Ports فقط خطأ؛ لازم تشمل كل الواجهات.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Including users", "Mapping dependencies", "Drawing both data and control paths", "Looking only for open ports"], "correct": 3, "explanation": "التركيز على Open Ports فقط خطأ؛ لازم تشمل كل الواجهات.", "persist": "mini-direct-q6", "week": 1}, {"id": "w2-practice1-mcq-1", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-1", "answerOrigin": "study", "prompt": "What does CIA stand for?", "options": ["Cloud, Internet, Application", "Confidentiality, Integrity, Availability", "Control, Identity, Access", "Configuration, Integrity, Authentication"], "correct": 1, "explanation": "السرّية والسلامة والتوافر.", "persist": "w2-practice1-mcq-1", "answerHTML": "<p dir=\"ltr\">B. Confidentiality, Integrity, Availability<\/p><p>السرّية والسلامة والتوافر.<\/p>"}, {"id": "w2-practice1-mcq-2", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-2", "answerOrigin": "study", "prompt": "Which security principle prevents unauthorized disclosure?", "options": ["Integrity", "Safety", "Confidentiality", "Availability"], "correct": 2, "explanation": "سرّية البيانات.", "persist": "w2-practice1-mcq-2", "answerHTML": "<p dir=\"ltr\">C. Confidentiality<\/p><p>سرّية البيانات.<\/p>"}, {"id": "w2-practice1-mcq-3", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-3", "answerOrigin": "study", "prompt": "Which security principle protects sensor readings from unauthorized modification?", "options": ["Integrity", "Availability", "Privacy", "Identification"], "correct": 0, "explanation": "سلامة البيانات والأوامر.", "persist": "w2-practice1-mcq-3", "answerHTML": "<p dir=\"ltr\">A. Integrity<\/p><p>سلامة البيانات والأوامر.<\/p>"}, {"id": "w2-practice1-mcq-4", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-4", "answerOrigin": "study", "prompt": "Which principle keeps essential IoT services reachable?", "options": ["Authentication", "Integrity", "Identification", "Availability"], "correct": 3, "explanation": "توافر الوظائف الأساسية.", "persist": "w2-practice1-mcq-4", "answerHTML": "<p dir=\"ltr\">D. Availability<\/p><p>توافر الوظائف الأساسية.<\/p>"}, {"id": "w2-practice1-mcq-5", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-5", "answerOrigin": "study", "prompt": "Which question is answered by Identification?", "options": ["Can you prove your identity?", "Who are you claiming to be?", "What may you access?", "Is the service online?"], "correct": 1, "explanation": "ادّعاء الهوية.", "persist": "w2-practice1-mcq-5", "answerHTML": "<p dir=\"ltr\">B. Who are you claiming to be?<\/p><p>ادّعاء الهوية.<\/p>"}, {"id": "w2-practice1-mcq-6", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-6", "answerOrigin": "study", "prompt": "Which question is answered by Authentication?", "options": ["Can you prove that claim?", "What is your device model?", "Which sensor is installed?", "What is the network address?"], "correct": 0, "explanation": "التحقّق من صحة الادّعاء.", "persist": "w2-practice1-mcq-6", "answerHTML": "<p dir=\"ltr\">A. Can you prove that claim?<\/p><p>التحقّق من صحة الادّعاء.<\/p>"}, {"id": "w2-practice1-mcq-7", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-7", "answerOrigin": "study", "prompt": "What does PSK stand for?", "options": ["Private Security Key", "Public Session Key", "Pre-Shared Key", "Protected Software Kernel"], "correct": 2, "explanation": "سر مشترك مسبقًا.", "persist": "w2-practice1-mcq-7", "answerHTML": "<p dir=\"ltr\">C. Pre-Shared Key<\/p><p>سر مشترك مسبقًا.<\/p>"}, {"id": "w2-practice1-mcq-8", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-8", "answerOrigin": "study", "prompt": "Which is an example of a freshness mechanism?", "options": ["Serial number", "Device color", "Default password", "Nonce"], "correct": 3, "explanation": "تمييز التفاعل الجديد عن إعادة رسالة قديمة.", "persist": "w2-practice1-mcq-8", "answerHTML": "<p dir=\"ltr\">D. Nonce<\/p><p>تمييز التفاعل الجديد عن إعادة رسالة قديمة.<\/p>"}, {"id": "w2-practice1-mcq-9", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-9", "answerOrigin": "study", "prompt": "What is Provisioning?", "options": ["Only connecting to Wi-Fi", "Preparing a device with identity, credentials, ownership, configuration and trust information", "Only installing an application", "Only measuring sensor data"], "correct": 1, "explanation": "تجهيز أمني وتشغيلي للجهاز.", "persist": "w2-practice1-mcq-9", "answerHTML": "<p dir=\"ltr\">B. Preparing a device with identity, credentials, ownership, configuration and trust information<\/p><p>تجهيز أمني وتشغيلي للجهاز.<\/p>"}, {"id": "w2-practice1-mcq-10", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-10", "answerOrigin": "study", "prompt": "What does Onboarding do?", "options": ["Connects the device to the intended organization, user, network, or service", "Deletes all credentials", "Replaces every sensor", "Measures network latency"], "correct": 0, "explanation": "ربط الجهاز بجهته المقصودة.", "persist": "w2-practice1-mcq-10", "answerHTML": "<p dir=\"ltr\">A. Connects the device to the intended organization, user, network, or service<\/p><p>ربط الجهاز بجهته المقصودة.<\/p>"}, {"id": "w2-practice1-mcq-11", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-11", "answerOrigin": "study", "prompt": "Which statement about a printed device identifier is correct?", "options": ["It always proves authenticity", "It replaces authentication", "It does not prove the device is genuine by itself", "It is the same as a private key"], "correct": 2, "explanation": "المعرّف المطبوع مش دليل كافي.", "persist": "w2-practice1-mcq-11", "answerHTML": "<p dir=\"ltr\">C. It does not prove the device is genuine by itself<\/p><p>المعرّف المطبوع مش دليل كافي.<\/p>"}, {"id": "w2-practice1-mcq-12", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-12", "answerOrigin": "study", "prompt": "Why are unchanged factory-default credentials a concern?", "options": ["They improve uniqueness", "They prevent onboarding", "They remove all dependencies", "One discovered credential may affect many devices"], "correct": 3, "explanation": "اعتماد متكرر ممكن يعرّض أجهزة كثيرة.", "persist": "w2-practice1-mcq-12", "answerHTML": "<p dir=\"ltr\">D. One discovered credential may affect many devices<\/p><p>اعتماد متكرر ممكن يعرّض أجهزة كثيرة.<\/p>"}, {"id": "w2-practice1-mcq-13", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-13", "answerOrigin": "study", "prompt": "What is Ownership Binding?", "options": ["Connecting a sensor to a battery", "Associating a device with its intended user or organization", "Encrypting all traffic", "Measuring physical temperature"], "correct": 1, "explanation": "إثبات ارتباط الجهاز بمالكه المقصود.", "persist": "w2-practice1-mcq-13", "answerHTML": "<p dir=\"ltr\">B. Associating a device with its intended user or organization<\/p><p>إثبات ارتباط الجهاز بمالكه المقصود.<\/p>"}, {"id": "w2-practice1-mcq-14", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-14", "answerOrigin": "study", "prompt": "What is the main problem in a cloned device identity scenario?", "options": ["Two devices use the same identity and credential", "The cloud is offline", "A sensor measures humidity", "The application has a new version"], "correct": 0, "explanation": "صعوبة تمييز الجهاز الحقيقي.", "persist": "w2-practice1-mcq-14", "answerHTML": "<p dir=\"ltr\">A. Two devices use the same identity and credential<\/p><p>صعوبة تمييز الجهاز الحقيقي.<\/p>"}, {"id": "w2-practice1-mcq-15", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-mcq-15", "answerOrigin": "study", "prompt": "What does MFA stand for?", "options": ["Main Firmware Authentication", "Managed File Access", "Multi-Factor Authentication", "Mobile Frequency Access"], "correct": 2, "explanation": "تحقّق بأكثر من عامل.", "persist": "w2-practice1-mcq-15", "answerHTML": "<p dir=\"ltr\">C. Multi-Factor Authentication<\/p><p>تحقّق بأكثر من عامل.<\/p>"}, {"id": "w2-practice1-blank-1", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-1", "answerOrigin": "study", "prompt": "CIA stands for Confidentiality, Integrity, and ______.", "answer": "Availability", "answerHTML": "<p dir=\"ltr\">Availability<\/p><p>التوافر.<\/p>"}, {"id": "w2-practice1-blank-2", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-2", "answerOrigin": "study", "prompt": "______ prevents unauthorized disclosure of data.", "answer": "Confidentiality", "answerHTML": "<p dir=\"ltr\">Confidentiality<\/p><p>السرّية.<\/p>"}, {"id": "w2-practice1-blank-3", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-3", "answerOrigin": "study", "prompt": "______ protects data and commands from unauthorized modification.", "answer": "Integrity", "answerHTML": "<p dir=\"ltr\">Integrity<\/p><p>سلامة البيانات والأوامر.<\/p>"}, {"id": "w2-practice1-blank-4", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-4", "answerOrigin": "study", "prompt": "Identification answers: Who are you claiming to ______?", "answer": "be", "answerHTML": "<p dir=\"ltr\">be<\/p><p>ادّعاء الهوية.<\/p>"}, {"id": "w2-practice1-blank-5", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-5", "answerOrigin": "study", "prompt": "Authentication answers: Can you ______ that claim?", "answer": "prove", "answerHTML": "<p dir=\"ltr\">prove<\/p><p>إثبات الادّعاء.<\/p>"}, {"id": "w2-practice1-blank-6", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-6", "answerOrigin": "study", "prompt": "PSK stands for Pre-Shared ______.", "answer": "Key", "answerHTML": "<p dir=\"ltr\">Key<\/p><p>مفتاح مشترك مسبقًا.<\/p>"}, {"id": "w2-practice1-blank-7", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-7", "answerOrigin": "study", "prompt": "MFA stands for Multi-Factor ______.", "answer": "Authentication", "answerHTML": "<p dir=\"ltr\">Authentication<\/p><p>التحقّق متعدد العوامل.<\/p>"}, {"id": "w2-practice1-blank-8", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-8", "answerOrigin": "study", "prompt": "______ helps distinguish a current interaction from an old recorded one.", "answer": "Freshness", "answerHTML": "<p dir=\"ltr\">Freshness<\/p><p>مثل Nonce أو Counter أو Timestamp.<\/p>"}, {"id": "w2-practice1-blank-9", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-9", "answerOrigin": "study", "prompt": "______ prepares identity, credentials, ownership, configuration, and trust information.", "answer": "Provisioning", "answerHTML": "<p dir=\"ltr\">Provisioning<\/p><p>التجهيز قبل التشغيل.<\/p>"}, {"id": "w2-practice1-blank-10", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-blank-10", "answerOrigin": "study", "prompt": "Ownership ______ associates a device with its intended user or organization.", "answer": "Binding", "answerHTML": "<p dir=\"ltr\">Binding<\/p><p>ربط الملكية.<\/p>"}, {"id": "w2-practice1-short-1", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-short-1", "answerOrigin": "study", "prompt": "Define Identification and Authentication.", "answerHTML": "<p dir=\"ltr\">Identification claims who an entity is. Authentication verifies proof of that claim.<\/p><p><\/p>"}, {"id": "w2-practice1-short-2", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-short-2", "answerOrigin": "study", "prompt": "List THREE freshness mechanisms.", "answerHTML": "<p dir=\"ltr\">Nonces, Counters, Timestamps.<\/p><p><\/p>"}, {"id": "w2-practice1-short-3", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-short-3", "answerOrigin": "study", "prompt": "Explain why a printed device identifier is not sufficient for authentication.", "answerHTML": "<p dir=\"ltr\">It can be copied and does not prove that the communicating device is genuine.<\/p><p><\/p>"}, {"id": "w2-practice1-short-4", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-short-4", "answerOrigin": "study", "prompt": "What is the difference between Provisioning and Onboarding?", "answerHTML": "<p dir=\"ltr\">Provisioning prepares identity, credentials, ownership, configuration and trust information. Onboarding connects the device to its intended user, organization, network or service. Provisioning establishes operational trust and ownership.<\/p><p><\/p>"}, {"id": "w2-practice1-short-5", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-short-5", "answerOrigin": "study", "prompt": "Expand PSK, MFA, PKI, and OTP.", "answerHTML": "<p dir=\"ltr\">Pre-Shared Key; Multi-Factor Authentication; Public Key Infrastructure; One-Time Password.<\/p><p><\/p>"}, {"id": "w2-practice1-case-1", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · practice1", "href": "week2.html#w2-practice1-case-1", "answerOrigin": "study", "prompt": "Smart Lock — Identity and CIA", "context": "A smart-home system includes an owner, a mobile application, a smart lock, a gateway and a cloud service.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify three identities.<\/li><li>Give one Confidentiality example.<\/li><li>Give one Integrity example.<\/li><li>Give one Availability example.<\/li><li>What is the purpose of Ownership Binding?<\/li><li>Why is an identifier alone insufficient for Authentication?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Owner, Application, Smart Lock.<\/li><li>Keep door events private.<\/li><li>Prevent unauthorized unlock-command modification.<\/li><li>Keep essential lock functions available.<\/li><li>Associate the device with its intended owner.<\/li><li>The identifier alone does not prove the device is genuine.<\/li><\/ol><p><\/p>"}, {"id": "w2-practice2-mcq-1", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-1", "answerOrigin": "study", "prompt": "What does Authorization determine?", "options": ["The device temperature", "Whether an authenticated entity may perform an action on a resource", "The network speed", "The physical location only"], "correct": 1, "explanation": "فعل معيّن على مورد معيّن.", "persist": "w2-practice2-mcq-1", "answerHTML": "<p dir=\"ltr\">B. Whether an authenticated entity may perform an action on a resource<\/p><p>فعل معيّن على مورد معيّن.<\/p>"}, {"id": "w2-practice2-mcq-2", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-2", "answerOrigin": "study", "prompt": "Which comes first in the access-control process?", "options": ["Authentication", "Enforcement", "Audit Export", "Firmware Update"], "correct": 0, "explanation": "نثبت الهوية قبل تقييم الصلاحية.", "persist": "w2-practice2-mcq-2", "answerHTML": "<p dir=\"ltr\">A. Authentication<\/p><p>نثبت الهوية قبل تقييم الصلاحية.<\/p>"}, {"id": "w2-practice2-mcq-3", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-3", "answerOrigin": "study", "prompt": "In 'An employee unlocks Door A', what is the Action?", "options": ["Employee", "Door A", "Unlock", "Cloud"], "correct": 2, "explanation": "Employee هو Subject وDoor A هو Resource.", "persist": "w2-practice2-mcq-3", "answerHTML": "<p dir=\"ltr\">C. Unlock<\/p><p>Employee هو Subject وDoor A هو Resource.<\/p>"}, {"id": "w2-practice2-mcq-4", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-4", "answerOrigin": "study", "prompt": "What does PDP stand for?", "options": ["Private Device Policy", "Public Data Protection", "Permission Device Protocol", "Policy Decision Point"], "correct": 3, "explanation": "نقطة القرار.", "persist": "w2-practice2-mcq-4", "answerHTML": "<p dir=\"ltr\">D. Policy Decision Point<\/p><p>نقطة القرار.<\/p>"}, {"id": "w2-practice2-mcq-5", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-5", "answerOrigin": "study", "prompt": "What does PEP do?", "options": ["Makes every policy", "Enforces an access decision", "Stores only temperature", "Creates a device identity"], "correct": 1, "explanation": "تطبيق القرار قبل العملية.", "persist": "w2-practice2-mcq-5", "answerHTML": "<p dir=\"ltr\">B. Enforces an access decision<\/p><p>تطبيق القرار قبل العملية.<\/p>"}, {"id": "w2-practice2-mcq-6", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-6", "answerOrigin": "study", "prompt": "Which access-control model attaches permissions to a resource?", "options": ["ACL", "RBAC", "ABAC", "Zero Trust"], "correct": 0, "explanation": "Access Control List.", "persist": "w2-practice2-mcq-6", "answerHTML": "<p dir=\"ltr\">A. ACL<\/p><p>Access Control List.<\/p>"}, {"id": "w2-practice2-mcq-7", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-7", "answerOrigin": "study", "prompt": "Which model assigns permissions through roles?", "options": ["ACL", "MAC", "RBAC", "HMAC"], "correct": 2, "explanation": "Role-Based Access Control.", "persist": "w2-practice2-mcq-7", "answerHTML": "<p dir=\"ltr\">C. RBAC<\/p><p>Role-Based Access Control.<\/p>"}, {"id": "w2-practice2-mcq-8", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-8", "answerOrigin": "study", "prompt": "Which model can evaluate time, location, and device state?", "options": ["ACL", "RBAC", "PSK", "ABAC"], "correct": 3, "explanation": "صفات وسياق.", "persist": "w2-practice2-mcq-8", "answerHTML": "<p dir=\"ltr\">D. ABAC<\/p><p>صفات وسياق.<\/p>"}, {"id": "w2-practice2-mcq-9", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-9", "answerOrigin": "study", "prompt": "What is Least Privilege?", "options": ["Giving all users administrator rights", "Giving only permissions needed for a legitimate function", "Trusting all local devices", "Allowing every action after login"], "correct": 1, "explanation": "الحد الأدنى الضروري.", "persist": "w2-practice2-mcq-9", "answerHTML": "<p dir=\"ltr\">B. Giving only permissions needed for a legitimate function<\/p><p>الحد الأدنى الضروري.<\/p>"}, {"id": "w2-practice2-mcq-10", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-10", "answerOrigin": "study", "prompt": "What should the backend verify when a user requests Device A data?", "options": ["That the user is authorized for Device A", "Only that Device A has a name", "Only that the user knows Device A identifier", "That every user has access"], "correct": 0, "explanation": "التحقّق من الصلاحية على الجهاز نفسه.", "persist": "w2-practice2-mcq-10", "answerHTML": "<p dir=\"ltr\">A. That the user is authorized for Device A<\/p><p>التحقّق من الصلاحية على الجهاز نفسه.<\/p>"}, {"id": "w2-practice2-mcq-11", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-11", "answerOrigin": "study", "prompt": "What does Zero Trust mean in this lecture?", "options": ["Never authenticate devices", "Disable all networks", "Do not grant broad implicit trust", "Always reject every request"], "correct": 2, "explanation": "مش رفض الجميع، بل تجنّب الثقة التلقائية.", "persist": "w2-practice2-mcq-11", "answerHTML": "<p dir=\"ltr\">C. Do not grant broad implicit trust<\/p><p>مش رفض الجميع، بل تجنّب الثقة التلقائية.<\/p>"}, {"id": "w2-practice2-mcq-12", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-12", "answerOrigin": "study", "prompt": "Which may require re-evaluating permissions?", "options": ["Changing screen brightness", "Reading a static label", "Changing device color", "Ownership change"], "correct": 3, "explanation": "تغيّر الملكية ممكن يغيّر الصلاحية.", "persist": "w2-practice2-mcq-12", "answerHTML": "<p dir=\"ltr\">D. Ownership change<\/p><p>تغيّر الملكية ممكن يغيّر الصلاحية.<\/p>"}, {"id": "w2-practice2-mcq-13", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-13", "answerOrigin": "study", "prompt": "What is the goal of Non-Repudiation?", "options": ["Improve network speed", "Provide strong evidence of an action that resists later denial", "Replace device inventory", "Remove all logs"], "correct": 1, "explanation": "دليل قوي يصعب معه إنكار الفعل.", "persist": "w2-practice2-mcq-13", "answerHTML": "<p dir=\"ltr\">B. Provide strong evidence of an action that resists later denial<\/p><p>دليل قوي يصعب معه إنكار الفعل.<\/p>"}, {"id": "w2-practice2-mcq-14", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-14", "answerOrigin": "study", "prompt": "Which key is used to sign data in a digital-signature system?", "options": ["Private Key", "Public Key", "Wi-Fi Password", "Device Name"], "correct": 0, "explanation": "المفتاح الخاص للتوقيع والعام للتحقّق.", "persist": "w2-practice2-mcq-14", "answerHTML": "<p dir=\"ltr\">A. Private Key<\/p><p>المفتاح الخاص للتوقيع والعام للتحقّق.<\/p>"}, {"id": "w2-practice2-mcq-15", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-mcq-15", "answerOrigin": "study", "prompt": "Which is a security-relevant event to log?", "options": ["Changing wallpaper color", "Reading a public brochure", "Ownership Change", "Viewing a clock"], "correct": 2, "explanation": "تغيّر الملكية حدث أمني مهم.", "persist": "w2-practice2-mcq-15", "answerHTML": "<p dir=\"ltr\">C. Ownership Change<\/p><p>تغيّر الملكية حدث أمني مهم.<\/p>"}, {"id": "w2-practice2-blank-1", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-1", "answerOrigin": "study", "prompt": "______ decides whether an authenticated identity may perform an action.", "answer": "Authorization", "answerHTML": "<p dir=\"ltr\">Authorization<\/p><p>تحديد الصلاحية.<\/p>"}, {"id": "w2-practice2-blank-2", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-2", "answerOrigin": "study", "prompt": "The entity making an access request is called the ______.", "answer": "Subject", "answerHTML": "<p dir=\"ltr\">Subject<\/p><p>الطرف صاحب الطلب.<\/p>"}, {"id": "w2-practice2-blank-3", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-3", "answerOrigin": "study", "prompt": "PDP stands for Policy ______ Point.", "answer": "Decision", "answerHTML": "<p dir=\"ltr\">Decision<\/p><p>قرار السماح أو المنع.<\/p>"}, {"id": "w2-practice2-blank-4", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-4", "answerOrigin": "study", "prompt": "PEP stands for Policy ______ Point.", "answer": "Enforcement", "answerHTML": "<p dir=\"ltr\">Enforcement<\/p><p>تطبيق القرار.<\/p>"}, {"id": "w2-practice2-blank-5", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-5", "answerOrigin": "study", "prompt": "ACL stands for Access Control ______.", "answer": "List", "answerHTML": "<p dir=\"ltr\">List<\/p><p>قائمة صلاحيات المورد.<\/p>"}, {"id": "w2-practice2-blank-6", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-6", "answerOrigin": "study", "prompt": "RBAC stands for Role-Based Access ______.", "answer": "Control", "answerHTML": "<p dir=\"ltr\">Control<\/p><p>وصول حسب الدور.<\/p>"}, {"id": "w2-practice2-blank-7", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-7", "answerOrigin": "study", "prompt": "ABAC stands for Attribute-Based Access ______.", "answer": "Control", "answerHTML": "<p dir=\"ltr\">Control<\/p><p>وصول حسب الصفات.<\/p>"}, {"id": "w2-practice2-blank-8", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-8", "answerOrigin": "study", "prompt": "______ Privilege gives each subject only necessary permissions.", "answer": "Least", "answerHTML": "<p dir=\"ltr\">Least<\/p><p>الحد الأدنى.<\/p>"}, {"id": "w2-practice2-blank-9", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-9", "answerOrigin": "study", "prompt": "Zero Trust avoids broad ______ trust.", "answer": "implicit", "answerHTML": "<p dir=\"ltr\">implicit<\/p><p>ثقة ضمنية أو تلقائية واسعة.<\/p>"}, {"id": "w2-practice2-blank-10", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-blank-10", "answerOrigin": "study", "prompt": "HMAC stands for Hash-based Message Authentication ______.", "answer": "Code", "answerHTML": "<p dir=\"ltr\">Code<\/p><p>Hash-based MAC.<\/p>"}, {"id": "w2-practice2-short-1", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-short-1", "answerOrigin": "study", "prompt": "Differentiate Authentication and Authorization.", "answerHTML": "<p dir=\"ltr\">Authentication verifies who or what the requester is. Authorization decides if that identity may perform a specific action on a specific resource.<\/p><p><\/p>"}, {"id": "w2-practice2-short-2", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-short-2", "answerOrigin": "study", "prompt": "Expand ACL, RBAC, ABAC, PDP, and PEP.", "answerHTML": "<p dir=\"ltr\">Access Control List; Role-Based Access Control; Attribute-Based Access Control; Policy Decision Point; Policy Enforcement Point.<\/p><p><\/p>"}, {"id": "w2-practice2-short-3", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-short-3", "answerOrigin": "study", "prompt": "Define Least Privilege.", "answerHTML": "<p dir=\"ltr\">Giving each subject only the permissions needed for its legitimate function.<\/p><p><\/p>"}, {"id": "w2-practice2-short-4", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-short-4", "answerOrigin": "study", "prompt": "Give THREE examples of attributes used in ABAC.", "answerHTML": "<p dir=\"ltr\">Time, Location, Device State.<\/p><p><\/p>"}, {"id": "w2-practice2-short-5", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-short-5", "answerOrigin": "study", "prompt": "What is the difference between MAC and Digital Signature?", "answerHTML": "<p dir=\"ltr\">MAC uses a shared secret to verify integrity and authenticity. A digital signature is created with a private key and verified with the corresponding public key.<\/p><p><\/p>"}, {"id": "w2-practice2-short-6", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-short-6", "answerOrigin": "study", "prompt": "Mention FOUR events that should be recorded in security logs.", "answerHTML": "<p dir=\"ltr\">Login, Device Registration, Ownership Change, Configuration Change.<\/p><p><\/p>"}, {"id": "w2-practice2-case-1", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-case-1", "answerOrigin": "study", "prompt": "Smart Camera Access", "context": "A family owns a smart camera. The owner may view live video, share access and change configuration. A family member may view live video only. A guest has temporary viewing permission.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify three subjects.<\/li><li>Identify two actions.<\/li><li>Identify one resource.<\/li><li>Which principle limits each person permissions?<\/li><li>Which model lists permissions directly on the camera?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Owner, Family Member, Guest.<\/li><li>View Live Video, Change Configuration.<\/li><li>Smart Camera.<\/li><li>Least Privilege.<\/li><li>ACL — Access Control List.<\/li><\/ol><p><\/p>"}, {"id": "w2-practice2-case-2", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-case-2", "answerOrigin": "study", "prompt": "Smart Building", "context": "A building has employees, technicians, administrators and connected locks. Technicians may configure assigned locks only during approved maintenance. Employees may unlock assigned doors only.", "questionsHTML": "<ol dir=\"ltr\"><li>Which model uses maintenance time as a condition?<\/li><li>Which principle restricts employees to assigned doors?<\/li><li>What is the Subject in an employee unlock request?<\/li><li>What is the Resource?<\/li><li>Why does authentication alone not grant access to every door?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>ABAC.<\/li><li>Least Privilege.<\/li><li>Employee.<\/li><li>Assigned Door Lock.<\/li><li>Authentication proves identity; Authorization checks permission on that specific door.<\/li><\/ol><p><\/p>"}, {"id": "w2-practice2-case-3", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · practice2", "href": "week2.html#w2-practice2-case-3", "answerOrigin": "study", "prompt": "Logging and Accountability", "context": "An administrator changes a lock configuration. The system records the administrator identity, affected lock, change and timestamp.", "questionsHTML": "<ol dir=\"ltr\"><li>What concept is supported by recording these details?<\/li><li>Mention two log fields.<\/li><li>What does Non-Repudiation aim to provide?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Accountability.<\/li><li>Administrator identity and timestamp; affected lock and change are also valid.<\/li><li>Strong evidence that an entity performed or approved an action, resisting later denial.<\/li><\/ol><p><\/p>"}, {"id": "w2-final-mcq-1", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-1", "prompt": "What does CIA stand for in IoT Security?", "options": ["Control, Identity, Access", "Confidentiality, Integrity, Availability", "Cloud, Internet, Application", "Confidentiality, Identification, Authorization"], "correct": 1, "explanation": "CIA: السرّية وسلامة البيانات والتوافر.", "persist": "w2-final-mcq-1", "answerHTML": "<p dir=\"ltr\">B. Confidentiality, Integrity, Availability<\/p><p>CIA: السرّية وسلامة البيانات والتوافر.<\/p>"}, {"id": "w2-final-mcq-2", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-2", "prompt": "Which principle prevents unauthorized disclosure of IoT data?", "options": ["Availability", "Integrity", "Confidentiality", "Safety"], "correct": 2, "explanation": "السرّية بتمنع الكشف غير المصرّح.", "persist": "w2-final-mcq-2", "answerHTML": "<p dir=\"ltr\">C. Confidentiality<\/p><p>السرّية بتمنع الكشف غير المصرّح.<\/p>"}, {"id": "w2-final-mcq-3", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-3", "prompt": "An attacker changes a temperature sensor reading. Which principle is affected?", "options": ["Integrity", "Availability", "Identification", "Privacy only"], "correct": 0, "explanation": "تغيير القراءة بدون إذن انتهاك لسلامة البيانات.", "persist": "w2-final-mcq-3", "answerHTML": "<p dir=\"ltr\">A. Integrity<\/p><p>تغيير القراءة بدون إذن انتهاك لسلامة البيانات.<\/p>"}, {"id": "w2-final-mcq-4", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-4", "prompt": "Which principle keeps essential IoT services reachable?", "options": ["Authentication", "Confidentiality", "Ownership", "Availability"], "correct": 3, "explanation": "Availability تعني بقاء الخدمات الأساسية متاحة.", "persist": "w2-final-mcq-4", "answerHTML": "<p dir=\"ltr\">D. Availability<\/p><p>Availability تعني بقاء الخدمات الأساسية متاحة.<\/p>"}, {"id": "w2-final-mcq-5", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-5", "prompt": "What does Identification answer?", "options": ["Can you prove that claim?", "Who are you claiming to be?", "What can you access?", "Is the device online?"], "correct": 1, "explanation": "Identification هو ادّعاء الهوية؛ إثباتها Authentication.", "persist": "w2-final-mcq-5", "answerHTML": "<p dir=\"ltr\">B. Who are you claiming to be?<\/p><p>Identification هو ادّعاء الهوية؛ إثباتها Authentication.<\/p>"}, {"id": "w2-final-mcq-6", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-6", "prompt": "What is the main purpose of Authentication?", "options": ["Verify a claimed identity", "Assign every permission", "Measure network speed", "Record temperature"], "correct": 0, "explanation": "إثبات الهوية ما بمنح كل الصلاحيات.", "persist": "w2-final-mcq-6", "answerHTML": "<p dir=\"ltr\">A. Verify a claimed identity<\/p><p>إثبات الهوية ما بمنح كل الصلاحيات.<\/p>"}, {"id": "w2-final-mcq-7", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-7", "prompt": "What does PSK stand for?", "options": ["Public Security Key", "Private Session Key", "Pre-Shared Key", "Protected Service Kernel"], "correct": 2, "explanation": "سر مشترك مسبقًا بين الأطراف.", "persist": "w2-final-mcq-7", "answerHTML": "<p dir=\"ltr\">C. Pre-Shared Key<\/p><p>سر مشترك مسبقًا بين الأطراف.<\/p>"}, {"id": "w2-final-mcq-8", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-8", "prompt": "Which is a freshness mechanism used against replay?", "options": ["Device color", "Serial number alone", "Factory password", "Nonce"], "correct": 3, "explanation": "Nonce أو Counter أو Timestamp بيساعد يميّز الرسالة الحالية من القديمة.", "persist": "w2-final-mcq-8", "answerHTML": "<p dir=\"ltr\">D. Nonce<\/p><p>Nonce أو Counter أو Timestamp بيساعد يميّز الرسالة الحالية من القديمة.<\/p>"}, {"id": "w2-final-mcq-9", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-9", "prompt": "Which statement best describes Provisioning?", "options": ["Only connecting a device to Wi-Fi", "Preparing a device with identity, credentials, ownership, configuration, and trust information", "Only reading sensor data", "Only deleting device logs"], "correct": 1, "explanation": "تجهيز الهوية والاعتمادات والملكية والإعدادات والثقة.", "persist": "w2-final-mcq-9", "answerHTML": "<p dir=\"ltr\">B. Preparing a device with identity, credentials, ownership, configuration, and trust information<\/p><p>تجهيز الهوية والاعتمادات والملكية والإعدادات والثقة.<\/p>"}, {"id": "w2-final-mcq-10", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-10", "prompt": "What is Ownership Binding?", "options": ["Associating a device with its intended user or organization", "Changing the battery", "Publishing telemetry", "Increasing network range"], "correct": 0, "explanation": "ربط الجهاز بالمالك أو المؤسسة المقصودة.", "persist": "w2-final-mcq-10", "answerHTML": "<p dir=\"ltr\">A. Associating a device with its intended user or organization<\/p><p>ربط الجهاز بالمالك أو المؤسسة المقصودة.<\/p>"}, {"id": "w2-final-mcq-11", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-11", "prompt": "Two devices use the same identity and credential. What is this scenario called?", "options": ["Offline Access", "Zero Trust", "Cloned Device Identity", "Least Privilege"], "correct": 2, "explanation": "النظام ممكن ما يقدر يميّز الجهاز الأصلي.", "persist": "w2-final-mcq-11", "answerHTML": "<p dir=\"ltr\">C. Cloned Device Identity<\/p><p>النظام ممكن ما يقدر يميّز الجهاز الأصلي.<\/p>"}, {"id": "w2-final-mcq-12", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-12", "prompt": "What does Authorization decide?", "options": ["Which device was manufactured first", "Whether an authenticated identity may perform an action on a resource", "The battery capacity", "The device's serial number"], "correct": 1, "explanation": "الصلاحية مرتبطة بهوية وفعل ومورد محدّد.", "persist": "w2-final-mcq-12", "answerHTML": "<p dir=\"ltr\">B. Whether an authenticated identity may perform an action on a resource<\/p><p>الصلاحية مرتبطة بهوية وفعل ومورد محدّد.<\/p>"}, {"id": "w2-final-mcq-13", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-13", "prompt": "In 'A technician configures Camera A', what is the Resource?", "options": ["Technician", "Configure", "Policy", "Camera A"], "correct": 3, "explanation": "Subject = Technician; Action = Configure; Resource = Camera A.", "persist": "w2-final-mcq-13", "answerHTML": "<p dir=\"ltr\">D. Camera A<\/p><p>Subject = Technician; Action = Configure; Resource = Camera A.<\/p>"}, {"id": "w2-final-mcq-14", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-14", "prompt": "What does the Policy Decision Point (PDP) do?", "options": ["Evaluates policy and returns Permit or Deny", "Physically opens every door", "Stores all sensor readings", "Creates manufacturing identities"], "correct": 0, "explanation": "PDP بقرّر، وPEP بطبّق القرار.", "persist": "w2-final-mcq-14", "answerHTML": "<p dir=\"ltr\">A. Evaluates policy and returns Permit or Deny<\/p><p>PDP بقرّر، وPEP بطبّق القرار.<\/p>"}, {"id": "w2-final-mcq-15", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-15", "prompt": "Which access model groups permissions by roles?", "options": ["ACL", "ABAC", "RBAC", "PSK"], "correct": 2, "explanation": "RBAC = Role-Based Access Control.", "persist": "w2-final-mcq-15", "answerHTML": "<p dir=\"ltr\">C. RBAC<\/p><p>RBAC = Role-Based Access Control.<\/p>"}, {"id": "w2-final-mcq-16", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-16", "prompt": "A technician may configure a device only during an approved maintenance window. Which model fits best?", "options": ["ACL", "ABAC", "MAC", "PSK"], "correct": 1, "explanation": "ABAC بفحص صفات مثل الوقت والموقع وحالة الجهاز.", "persist": "w2-final-mcq-16", "answerHTML": "<p dir=\"ltr\">B. ABAC<\/p><p>ABAC بفحص صفات مثل الوقت والموقع وحالة الجهاز.<\/p>"}, {"id": "w2-final-mcq-17", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-17", "prompt": "What does Least Privilege mean?", "options": ["Give every device admin access", "Trust all internal services", "Never allow access", "Grant only permissions needed for legitimate functions"], "correct": 3, "explanation": "أقل صلاحيات لازمة للعمل المشروع.", "persist": "w2-final-mcq-17", "answerHTML": "<p dir=\"ltr\">D. Grant only permissions needed for legitimate functions<\/p><p>أقل صلاحيات لازمة للعمل المشروع.<\/p>"}, {"id": "w2-final-mcq-18", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-18", "prompt": "What is the main idea of Zero Trust in this lecture?", "options": ["Do not grant broad implicit trust", "Reject every request forever", "Trust all devices inside the network", "Remove authentication"], "correct": 0, "explanation": "تحقّق من الهوية والحالة وأعد التقييم بدل الثقة التلقائية الواسعة.", "persist": "w2-final-mcq-18", "answerHTML": "<p dir=\"ltr\">A. Do not grant broad implicit trust<\/p><p>تحقّق من الهوية والحالة وأعد التقييم بدل الثقة التلقائية الواسعة.<\/p>"}, {"id": "w2-final-mcq-19", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-19", "prompt": "Which key creates a Digital Signature?", "options": ["Public key", "Wi-Fi password", "Private key", "Serial number"], "correct": 2, "explanation": "Private Key يوقّع، وPublic Key بتحقّق.", "persist": "w2-final-mcq-19", "answerHTML": "<p dir=\"ltr\">C. Private key<\/p><p>Private Key يوقّع، وPublic Key بتحقّق.<\/p>"}, {"id": "w2-final-mcq-20", "type": "mcq", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-mcq-20", "prompt": "Which concept aims to provide strong evidence that an entity performed or approved an action?", "options": ["Availability", "Non-Repudiation", "Onboarding", "Identification"], "correct": 1, "explanation": "دليل قوي على الفعل يقاوم الإنكار لاحقًا.", "persist": "w2-final-mcq-20", "answerHTML": "<p dir=\"ltr\">B. Non-Repudiation<\/p><p>دليل قوي على الفعل يقاوم الإنكار لاحقًا.<\/p>"}, {"id": "w2-final-blank-1", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-1", "prompt": "CIA stands for Confidentiality, Integrity, and ______.", "answer": "Availability", "answerHTML": "<p dir=\"ltr\">Availability<\/p><p>التوافر هو العنصر الثالث.<\/p>"}, {"id": "w2-final-blank-2", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-2", "prompt": "Identification asks: Who are you claiming to ______?", "answer": "be", "answerHTML": "<p dir=\"ltr\">be<\/p><p>ادّعاء الهوية.<\/p>"}, {"id": "w2-final-blank-3", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-3", "prompt": "MFA stands for Multi-Factor ______.", "answer": "Authentication", "answerHTML": "<p dir=\"ltr\">Authentication<\/p><p>التحقّق بأكثر من عامل.<\/p>"}, {"id": "w2-final-blank-4", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-4", "prompt": "PKI stands for Public Key ______.", "answer": "Infrastructure", "answerHTML": "<p dir=\"ltr\">Infrastructure<\/p><p>البنية التحتية للمفتاح العام.<\/p>"}, {"id": "w2-final-blank-5", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-5", "prompt": "OTP stands for One-Time ______.", "answer": "Password", "answerHTML": "<p dir=\"ltr\">Password<\/p><p>كلمة مرور لمرة واحدة.<\/p>"}, {"id": "w2-final-blank-6", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-6", "prompt": "______ connects a device to the intended user, organization, network, or service.", "answer": "Onboarding", "answerHTML": "<p dir=\"ltr\">Onboarding<\/p><p>ربط الجهاز بالجهة المقصودة.<\/p>"}, {"id": "w2-final-blank-7", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-7", "prompt": "ACL stands for Access Control ______.", "answer": "List", "answerHTML": "<p dir=\"ltr\">List<\/p><p>قائمة صلاحيات مرتبطة بمورد.<\/p>"}, {"id": "w2-final-blank-8", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-8", "prompt": "RBAC stands for Role-Based Access ______.", "answer": "Control", "answerHTML": "<p dir=\"ltr\">Control<\/p><p>وصول مبني على الأدوار.<\/p>"}, {"id": "w2-final-blank-9", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-9", "prompt": "PEP stands for Policy ______ Point.", "answer": "Enforcement", "answerHTML": "<p dir=\"ltr\">Enforcement<\/p><p>نقطة تنفيذ قرار السياسة.<\/p>"}, {"id": "w2-final-blank-10", "type": "blank", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-blank-10", "prompt": "HMAC stands for Hash-based Message Authentication ______.", "answer": "Code", "answerHTML": "<p dir=\"ltr\">Code<\/p><p>نوع من MAC مبني على Hash.<\/p>"}, {"id": "w2-final-short-1", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-short-1", "prompt": "Differentiate between Identification, Authentication, and Authorization.", "answerHTML": "<p dir=\"ltr\">Identification claims an identity. Authentication verifies the claim. Authorization decides whether that identity may perform an action on a resource.<\/p><p>ادّعاء الهوية ثم إثباتها ثم تحديد الصلاحية.<\/p>"}, {"id": "w2-final-short-2", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-short-2", "prompt": "Define Provisioning and Onboarding. Why is Provisioning a security process?", "answerHTML": "<p dir=\"ltr\">Provisioning prepares identity, credentials, ownership, configuration and trust information. Onboarding connects the device to its intended user, organization, network or service. Provisioning establishes operational trust and ownership.<\/p><p>علامة لكل تعريف وعلامة للغرض الأمني.<\/p>"}, {"id": "w2-final-short-3", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-short-3", "prompt": "Compare ACL, RBAC, and ABAC.", "answerHTML": "<p dir=\"ltr\">ACL: permissions attached to a resource. RBAC: permissions assigned through roles. ABAC: permissions depend on attributes and context.<\/p><p>Resource / Role / Attributes.<\/p>"}, {"id": "w2-final-short-4", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-short-4", "prompt": "Explain Least Privilege and give TWO IoT examples.", "answerHTML": "<p dir=\"ltr\">Give each subject only permissions needed for its legitimate function. A temperature sensor may publish readings without admin rights. A user should access only owned or assigned devices.<\/p><p>علامة للتعريف وعلامة لكل مثال.<\/p>"}, {"id": "w2-final-short-5", "type": "short", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-short-5", "prompt": "Differentiate between MAC and Digital Signature, and explain how a digital signature is verified.", "answerHTML": "<p dir=\"ltr\">MAC uses a shared secret to verify integrity and authenticity. A digital signature is created with a private key and verified with the corresponding public key.<\/p><p>Shared Secret مقابل Private/Public Keys.<\/p>"}, {"id": "w2-final-case-1", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-case-1", "prompt": "Smart Home Security", "context": "A smart home contains a smart lock, a camera, and temperature sensors. The owner uses a mobile application to control the lock. The system records door activity and sensor readings.", "questionsHTML": "<ol dir=\"ltr\"><li>Give one example of Confidentiality.<\/li><li>Give one example of Integrity.<\/li><li>Give one example of Availability.<\/li><li>Identify two different identities in this system.<\/li><li>Why is the smart lock serial number alone insufficient for Authentication?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Prevent unauthorized viewing of camera recordings or door activity.<\/li><li>Prevent unauthorized modification of readings or unlock commands.<\/li><li>Keep essential smart-lock functions reachable when needed.<\/li><li>Owner and Smart Lock Device; the Application and Cloud Service are also valid.<\/li><li>A serial number alone does not prove that the communicating device is genuine.<\/li><\/ol><p>تطبيق CIA مع الهويات والتمييز بين المعرّف والدليل.<\/p>"}, {"id": "w2-final-case-2", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-case-2", "prompt": "Smart Building Access Control", "context": "A smart building has 300 sensors, 40 smart locks, local gateways, and a cloud dashboard. Employees may unlock assigned doors. Technicians may configure devices only while assigned to a site and during an approved maintenance window. Administrators manage access permissions.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify Subject, Action, and Resource when an employee unlocks Door A.<\/li><li>Which model is suitable for permissions based on maintenance time?<\/li><li>Which principle prevents employees from accessing all smart locks?<\/li><li>What does the PDP do?<\/li><li>What does the PEP do?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Subject: Employee. Action: Unlock. Resource: Door A.<\/li><li>ABAC — Attribute-Based Access Control.<\/li><li>Least Privilege.<\/li><li>Evaluates the request against policy and returns Permit or Deny.<\/li><li>Enforces the decision before the requested action occurs.<\/li><\/ol><p>PDP = Decide; PEP = Enforce.<\/p>"}, {"id": "w2-final-case-3", "type": "case", "week": 2, "lecture": "w2", "group": "Week 2 · final", "href": "exam-week2.html#w2-final-case-3", "prompt": "Device Identity, Trust and Accountability", "context": "A newly installed IoT device is registered to its owner. Later, two physical devices appear to the backend using the same identity and credential. A technician also changes a device configuration, and the system records the action.", "questionsHTML": "<ol dir=\"ltr\"><li>What is the purpose of Ownership Binding?<\/li><li>What is the problem when two physical devices use the same identity and credential?<\/li><li>What does Zero Trust mean in this situation?<\/li><li>What information should the system record about the technician action?<\/li><li>Which cryptographic mechanism can support Non-Repudiation?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Associates the device with the intended user or organization.<\/li><li>Cloned Device Identity: the backend may not distinguish the genuine device.<\/li><li>No broad implicit trust; verify identity and relevant device state.<\/li><li>Technician identity, affected device, configuration change and timestamp.<\/li><li>Digital Signatures, when keys and identity binding are properly managed.<\/li><\/ol><p>ربط التجهيز بالثقة والمساءلة.<\/p>"}, {"id": "w3-final-mcq-1", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-1", "prompt": "Which IoT functional layer is responsible for sensors, actuators, and local controllers?", "options": ["Connectivity", "Physical Things", "Cloud / Backend", "Application"], "correct": 1, "explanation": "Physical Things بتضم القياس والتنفيذ والمنطق المحلي.", "persist": "w3-final-mcq-1", "answerHTML": "<p dir=\"ltr\">B. Physical Things<\/p><p>Physical Things بتضم القياس والتنفيذ والمنطق المحلي.<\/p>"}, {"id": "w3-final-mcq-2", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-2", "prompt": "Which component typically performs local filtering, translation, and aggregation?", "options": ["Leaf Node", "Application Dashboard", "Edge / Gateway", "Sensing Element"], "correct": 2, "explanation": "الحافة أو البوابة بتنفّذ المعالجة المحلية.", "persist": "w3-final-mcq-2", "answerHTML": "<p dir=\"ltr\">C. Edge / Gateway<\/p><p>الحافة أو البوابة بتنفّذ المعالجة المحلية.<\/p>"}, {"id": "w3-final-mcq-3", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-3", "prompt": "Which component in a sensor node samples and processes readings?", "options": ["Microcontroller", "Power Supply", "Radio Antenna", "Actuator"], "correct": 0, "explanation": "المتحكّم الدقيق بعالج العيّنات؛ Firmware بحدّد السلوك والتوقيت.", "persist": "w3-final-mcq-3", "answerHTML": "<p dir=\"ltr\">A. Microcontroller<\/p><p>المتحكّم الدقيق بعالج العيّنات؛ Firmware بحدّد السلوك والتوقيت.<\/p>"}, {"id": "w3-final-mcq-4", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-4", "prompt": "What is the main characteristic of a Leaf / End Node?", "options": ["It forwards all neighbors' packets", "It is always the DODAG root", "It converts application protocols", "It does not forward other nodes' packets"], "correct": 3, "explanation": "Leaf ينتج أو يستهلك بياناته بدون تمرير بيانات الجيران.", "persist": "w3-final-mcq-4", "answerHTML": "<p dir=\"ltr\">D. It does not forward other nodes&#x27; packets<\/p><p>Leaf ينتج أو يستهلك بياناته بدون تمرير بيانات الجيران.<\/p>"}, {"id": "w3-final-mcq-5", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-5", "prompt": "Which component performs a physical action?", "options": ["Sensor", "Actuator", "Cloud Database", "Routing Table"], "correct": 1, "explanation": "المشغّل بنفّذ فعلًا مثل فتح صمام.", "persist": "w3-final-mcq-5", "answerHTML": "<p dir=\"ltr\">B. Actuator<\/p><p>المشغّل بنفّذ فعلًا مثل فتح صمام.<\/p>"}, {"id": "w3-final-mcq-6", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-6", "prompt": "Which sequence correctly represents the control path?", "options": ["Sense → Process → Forward → Use", "Discover → Evaluate → Select → Operate", "Request → Authorize → Deliver → Act", "Read → Store → Analyze → Display"], "correct": 2, "explanation": "طلب ثم صلاحية ثم توصيل ثم فعل.", "persist": "w3-final-mcq-6", "answerHTML": "<p dir=\"ltr\">C. Request → Authorize → Deliver → Act<\/p><p>طلب ثم صلاحية ثم توصيل ثم فعل.<\/p>"}, {"id": "w3-final-mcq-7", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-7", "prompt": "What is the main role of a Border Router?", "options": ["Forward IP packets between a constrained IP network and another IP network", "Display sensor data to users", "Measure physical temperature", "Decide every actuator action"], "correct": 0, "explanation": "يربط شبكتي IP؛ مش لازم يعمل ترجمة تطبيقات.", "persist": "w3-final-mcq-7", "answerHTML": "<p dir=\"ltr\">A. Forward IP packets between a constrained IP network and another IP network<\/p><p>يربط شبكتي IP؛ مش لازم يعمل ترجمة تطبيقات.<\/p>"}, {"id": "w3-final-mcq-8", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-8", "prompt": "In a Star topology, end devices normally communicate through a:", "options": ["Preferred Parent selected by RPL", "Mesh of alternative links", "Cloud Database", "Central Coordinator"], "correct": 3, "explanation": "المركز هو اعتماد أساسي في Star.", "persist": "w3-final-mcq-8", "answerHTML": "<p dir=\"ltr\">D. Central Coordinator<\/p><p>المركز هو اعتماد أساسي في Star.<\/p>"}, {"id": "w3-final-mcq-9", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-9", "prompt": "What does a physical Mesh topology show?", "options": ["Only the selected RPL parent links", "Possible connectivity links among nodes", "Application user permissions", "Only downward routes"], "correct": 1, "explanation": "Mesh روابط ممكنة؛ DODAG علاقات توجيه منطقية.", "persist": "w3-final-mcq-9", "answerHTML": "<p dir=\"ltr\">B. Possible connectivity links among nodes<\/p><p>Mesh روابط ممكنة؛ DODAG علاقات توجيه منطقية.<\/p>"}, {"id": "w3-final-mcq-10", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-10", "prompt": "Which sequence best describes a CPS feedback loop?", "options": ["Cloud → Database → Dashboard → User", "Router → Root → Internet → Router", "Physical State → Sensor → Controller → Actuator → Updated Physical State", "DIS → DAO → DIO → DAO-ACK"], "correct": 2, "explanation": "قياس ثم قرار ثم فعل فيزيائي وقياس جديد.", "persist": "w3-final-mcq-10", "answerHTML": "<p dir=\"ltr\">C. Physical State → Sensor → Controller → Actuator → Updated Physical State<\/p><p>قياس ثم قرار ثم فعل فيزيائي وقياس جديد.<\/p>"}, {"id": "w3-final-mcq-11", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-11", "prompt": "What does RPL stand for?", "options": ["Routing Protocol for Low-Power and Lossy Networks", "Reliable Packet Link", "Remote Processing Layer", "Routing Policy for Local Networks"], "correct": 0, "explanation": "بروتوكول توجيه IPv6 للشبكات المحدودة.", "persist": "w3-final-mcq-11", "answerHTML": "<p dir=\"ltr\">A. Routing Protocol for Low-Power and Lossy Networks<\/p><p>بروتوكول توجيه IPv6 للشبكات المحدودة.<\/p>"}, {"id": "w3-final-mcq-12", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-12", "prompt": "What does DODAG stand for?", "options": ["Device-Oriented Data Access Graph", "Distributed Object Directed Access Gateway", "Destination-Oriented Dynamic Application Graph", "Destination-Oriented Directed Acyclic Graph"], "correct": 3, "explanation": "رسم موجّه نحو جذر بدون حلقات موجّهة.", "persist": "w3-final-mcq-12", "answerHTML": "<p dir=\"ltr\">D. Destination-Oriented Directed Acyclic Graph<\/p><p>رسم موجّه نحو جذر بدون حلقات موجّهة.<\/p>"}, {"id": "w3-final-mcq-13", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-13", "prompt": "What does Rank represent in RPL?", "options": ["The exact IPv6 address of a node", "A node's relative position toward the root", "The number of sensors connected to a router", "The device's hardware serial number"], "correct": 1, "explanation": "موقع نسبي، مش IP ولا بالضرورة عدد القفزات.", "persist": "w3-final-mcq-13", "answerHTML": "<p dir=\"ltr\">B. A node&#x27;s relative position toward the root<\/p><p>موقع نسبي، مش IP ولا بالضرورة عدد القفزات.<\/p>"}, {"id": "w3-final-mcq-14", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-14", "prompt": "What is a Preferred Parent?", "options": ["Any neighbor with a radio signal", "The cloud service that stores readings", "The selected parent for normal upward forwarding", "The node with the highest battery level in all cases"], "correct": 2, "explanation": "الأب المختار حسب OF والمعايير وقيود Rank.", "persist": "w3-final-mcq-14", "answerHTML": "<p dir=\"ltr\">C. The selected parent for normal upward forwarding<\/p><p>الأب المختار حسب OF والمعايير وقيود Rank.<\/p>"}, {"id": "w3-final-mcq-15", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-15", "prompt": "What does the Objective Function (OF) help determine?", "options": ["Rank calculation and parent selection", "Sensor calibration only", "User-interface design", "Application message encryption"], "correct": 0, "explanation": "تفسّر المعلومات لحساب Rank واختيار Parent.", "persist": "w3-final-mcq-15", "answerHTML": "<p dir=\"ltr\">A. Rank calculation and parent selection<\/p><p>تفسّر المعلومات لحساب Rank واختيار Parent.<\/p>"}, {"id": "w3-final-mcq-16", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-16", "prompt": "Which RPL control message requests routing information?", "options": ["DAO", "DIO", "DAO-ACK", "DIS"], "correct": 3, "explanation": "DIS = DODAG Information Solicitation.", "persist": "w3-final-mcq-16", "answerHTML": "<p dir=\"ltr\">D. DIS<\/p><p>DIS = DODAG Information Solicitation.<\/p>"}, {"id": "w3-final-mcq-17", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-17", "prompt": "Which RPL control message advertises DODAG information?", "options": ["DAO", "DIO", "DIS", "DAO-ACK"], "correct": 1, "explanation": "DIO = DODAG Information Object.", "persist": "w3-final-mcq-17", "answerHTML": "<p dir=\"ltr\">B. DIO<\/p><p>DIO = DODAG Information Object.<\/p>"}, {"id": "w3-final-mcq-18", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-18", "prompt": "Which RPL message advertises downward reachability?", "options": ["DIS", "DIO", "DAO", "DAO-ACK"], "correct": 2, "explanation": "DAO = Destination Advertisement Object.", "persist": "w3-final-mcq-18", "answerHTML": "<p dir=\"ltr\">C. DAO<\/p><p>DAO = Destination Advertisement Object.<\/p>"}, {"id": "w3-final-mcq-19", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-19", "prompt": "In Non-Storing Mode, where is downward routing knowledge maintained?", "options": ["At the root", "Only at leaf nodes", "At every intermediate router", "Only at the application dashboard"], "correct": 0, "explanation": "Root بحفظ معلومات النزول وبستخدم Source Routing.", "persist": "w3-final-mcq-19", "answerHTML": "<p dir=\"ltr\">A. At the root<\/p><p>Root بحفظ معلومات النزول وبستخدم Source Routing.<\/p>"}, {"id": "w3-final-mcq-20", "type": "mcq", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-mcq-20", "prompt": "What is the purpose of the Trickle algorithm?", "options": ["Encrypt actuator commands", "Replace the DODAG root", "Convert sensors into routers", "Regulate routing-information dissemination and reduce redundant overhead"], "correct": 3, "explanation": "يقلّل الإعلانات الزائدة وقت الاستقرار ويسرّع الانتشار عند عدم الاتساق.", "persist": "w3-final-mcq-20", "answerHTML": "<p dir=\"ltr\">D. Regulate routing-information dissemination and reduce redundant overhead<\/p><p>يقلّل الإعلانات الزائدة وقت الاستقرار ويسرّع الانتشار عند عدم الاتساق.<\/p>"}, {"id": "w3-final-blank-1", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-1", "prompt": "The five functional layers include Physical Things, Connectivity, Edge / Gateway, Cloud / Backend, and ______.", "answer": "Application", "answerHTML": "<p dir=\"ltr\">Application<\/p><p>واجهة المستخدم والمراقبة والتحكّم.<\/p>"}, {"id": "w3-final-blank-2", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-2", "prompt": "A node that forwards packets from neighboring devices is called a ______.", "answer": "Router", "answerHTML": "<p dir=\"ltr\">Router<\/p><p>Router Node بمرّر حزم الجيران.<\/p>"}, {"id": "w3-final-blank-3", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-3", "prompt": "The ______ measures physical conditions such as temperature or humidity.", "answer": "Sensor", "answerHTML": "<p dir=\"ltr\">Sensor<\/p><p>الحساس بقيس، والمشغّل بنفّذ.<\/p>"}, {"id": "w3-final-blank-4", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-4", "prompt": "The measurement path is Sense → Process → ______ → Use.", "answer": "Forward", "answerHTML": "<p dir=\"ltr\">Forward<\/p><p>تمرير القراءة بعد معالجتها.<\/p>"}, {"id": "w3-final-blank-5", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-5", "prompt": "LLN stands for Low-Power and ______ Network.", "answer": "Lossy", "answerHTML": "<p dir=\"ltr\">Lossy<\/p><p>روابط ممكن تفقد حزم.<\/p>"}, {"id": "w3-final-blank-6", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-6", "prompt": "The DODAG is organized toward a node called the ______.", "answer": "Root", "answerHTML": "<p dir=\"ltr\">Root<\/p><p>الجذر هو الوجهة المشتركة للصعود.<\/p>"}, {"id": "w3-final-blank-7", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-7", "prompt": "A node's relative position toward the DODAG root is represented by its ______.", "answer": "Rank", "answerHTML": "<p dir=\"ltr\">Rank<\/p><p>الموقع النسبي حسب قواعد RPL.<\/p>"}, {"id": "w3-final-blank-8", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-8", "prompt": "The RPL message used to solicit routing information is ______.", "answer": "DIS", "answerHTML": "<p dir=\"ltr\">DIS<\/p><p>طلب معلومات.<\/p>"}, {"id": "w3-final-blank-9", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-9", "prompt": "The RPL message used to advertise downward reachability is ______.", "answer": "DAO", "answerHTML": "<p dir=\"ltr\">DAO<\/p><p>إعلان الوصول للأسفل.<\/p>"}, {"id": "w3-final-blank-10", "type": "blank", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-blank-10", "prompt": "In ______ mode, intermediate routers store downward route entries.", "answer": "Storing", "answerHTML": "<p dir=\"ltr\">Storing<\/p><p>الحفظ عند الرواتر الوسيطة.<\/p>"}, {"id": "w3-final-short-1", "type": "short", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-short-1", "prompt": "Explain the difference between a Sensor, an Actuator, and a Controller. Give one example of each.", "answerHTML": "<p dir=\"ltr\">A sensor measures a physical condition, e.g. a temperature sensor. An actuator performs an action, e.g. a valve. A controller evaluates readings against a rule or setpoint and selects a response, e.g. a thermostat controller.<\/p><p>Measure / Act / Decide مع مثال لكل وظيفة.<\/p>"}, {"id": "w3-final-short-2", "type": "short", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-short-2", "prompt": "Compare a Gateway and a Border Router in an IoT system.", "answerHTML": "<p dir=\"ltr\">A border router forwards IP packets between a constrained IP network and another IP network. A gateway may translate protocols, aggregate data and process locally. One device can perform both roles.<\/p><p>وظيفتان مختلفتان ممكن يجتمعوا بجهاز واحد.<\/p>"}, {"id": "w3-final-short-3", "type": "short", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-short-3", "prompt": "Explain the difference between a physical Mesh topology and a DODAG.", "answerHTML": "<p dir=\"ltr\">A physical mesh shows possible connectivity links. A DODAG is a logical, directed, root-oriented routing graph formed by RPL. Not every mesh link is a selected routing link.<\/p><p>روابط ممكنة مقابل علاقات توجيه.<\/p>"}, {"id": "w3-final-short-4", "type": "short", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-short-4", "prompt": "What is Rank in RPL, and how is a Preferred Parent selected?", "answerHTML": "<p dir=\"ltr\">Rank represents relative position toward the root. A preferred parent is selected from candidates using the Objective Function, routing metrics and rank constraints. Rank is not necessarily hop count.<\/p><p>Rank نسبي؛ الاختيار حسب OF والمعايير والقيود.<\/p>"}, {"id": "w3-final-short-5", "type": "short", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-short-5", "prompt": "Compare Storing Mode and Non-Storing Mode for downward routing.", "answerHTML": "<p dir=\"ltr\">Storing: intermediate routers keep downward route entries. Non-Storing: root maintains downward routing knowledge and uses source routing. Storing uses router memory; Non-Storing can increase header overhead.<\/p><p>الفرق بمكان حفظ المسارات وكلفة الذاكرة والترويسات.<\/p>"}, {"id": "w3-final-case-1", "type": "case", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-case-1", "prompt": "Smart Irrigation System", "context": "A smart farm has four battery-powered soil moisture sensors, two powered routers, one border router acting as the DODAG root, a local irrigation controller, and a cloud dashboard.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the Leaf Nodes and Router Nodes.<\/li><li>Describe the upward measurement path.<\/li><li>What should happen to local irrigation if the Internet fails, assuming local control is supported?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>The four soil sensors are Leaves; the two forwarding devices are Routers. The border router is the Root.<\/li><li>Soil Sensor → Preferred Parent / Router → Root → Backend / Dashboard.<\/li><li>The local controller can continue irrigation decisions from local readings and policy even while the cloud dashboard is unavailable.<\/li><\/ol><p>استمرار الري المحلي مشروط بوجود دعم للتحكّم المحلي.<\/p>"}, {"id": "w3-final-case-2", "type": "case", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-case-2", "prompt": "Router Failure and Parent Selection", "context": "Leaf 2 normally forwards through Router A. It also has a possible radio link to Router B. Router A becomes unavailable.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the Preferred Parent before failure.<\/li><li>Identify the Candidate Parent.<\/li><li>What should Leaf 2 do after Router A fails?<\/li><li>Does the alternative link guarantee immediate recovery?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>Router A.<\/li><li>Router B.<\/li><li>Re-evaluate candidates using routing information, OF and rank constraints; select Router B only if viable.<\/li><li>No. The link must be usable, and repair can require messages, time and energy.<\/li><\/ol><p>وجود خط بديل مش ضمان لتعافٍ فوري.<\/p>"}, {"id": "w3-final-case-3", "type": "case", "week": 3, "lecture": "w3", "group": "Week 3 · final", "href": "exam-week3.html#w3-final-case-3", "prompt": "Joining an RPL Network", "context": "A new temperature sensor starts in an LLN without routing information. It must send readings toward the root, and the network may later send commands downward.", "questionsHTML": "<ol dir=\"ltr\"><li>Which message can request routing information?<\/li><li>Which message advertises DODAG information?<\/li><li>What is evaluated before selecting a Preferred Parent?<\/li><li>Which message advertises downward reachability?<\/li><li>What does DAO-ACK acknowledge?<\/li><\/ol>", "answerHTML": "<ol dir=\"ltr\"><li>DIS — DODAG Information Solicitation.<\/li><li>DIO — DODAG Information Object.<\/li><li>Candidate information, rank constraints, metrics and OF.<\/li><li>DAO — Destination Advertisement Object.<\/li><li>A DAO when requested; not application-data delivery or physical actuation.<\/li><\/ol><p>افصل رسائل التوجيه عن بيانات التطبيق.<\/p>"}, {"id": "w3-final-diagram", "week": 3, "type": "diagram", "lecture": "w3", "group": "Week 3 · Drawing", "prompt": "Draw a DODAG with one Root, two Routers and four Leaf Nodes. Label Leaf 1 upward path and show an alternative Candidate Parent for Leaf 2.", "href": "exam-week3.html#final-diagram", "answerHTML": "<div class=\"tree-diagram\"><svg class=\"topology-svg\" viewBox=\"0 0 660 300\" role=\"img\" aria-label=\"Root-oriented DODAG. Solid arrows show upward preferred links; dashed line shows an alternative candidate for Leaf 2.\"><defs><marker id=\"arrow-root\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 0 L 10 5 L 0 10 z\" fill=\"#1877f2\"/><\/marker><\/defs><line x1=\"165.0\" y1=\"111\" x2=\"330\" y2=\"61\" marker-end=\"url(#arrow-root)\"/><line x1=\"100.0\" y1=\"217\" x2=\"165.0\" y2=\"155\" marker-end=\"url(#arrow-root)\"/><line x1=\"230.0\" y1=\"217\" x2=\"165.0\" y2=\"155\" marker-end=\"url(#arrow-root)\"/><line x1=\"495.0\" y1=\"111\" x2=\"330\" y2=\"61\" marker-end=\"url(#arrow-root)\"/><line x1=\"430.0\" y1=\"217\" x2=\"495.0\" y2=\"155\" marker-end=\"url(#arrow-root)\"/><line x1=\"560.0\" y1=\"217\" x2=\"495.0\" y2=\"155\" marker-end=\"url(#arrow-root)\"/><line x1=\"230.0\" y1=\"217\" x2=\"495.0\" y2=\"155\" marker-end=\"url(#arrow-root)\" stroke-dasharray=\"7 6\" style=\"stroke:#d68b16\"/><rect x=\"282\" y=\"18\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"330\" y=\"44\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Root<\/text><rect x=\"117.0\" y=\"112\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"165.0\" y=\"138\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Router A<\/text><rect x=\"52.0\" y=\"218\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"100.0\" y=\"244\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Leaf 1<\/text><rect x=\"182.0\" y=\"218\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"230.0\" y=\"244\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Leaf 2<\/text><rect x=\"447.0\" y=\"112\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"495.0\" y=\"138\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Router B<\/text><rect x=\"382.0\" y=\"218\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"430.0\" y=\"244\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Leaf 3<\/text><rect x=\"512.0\" y=\"218\" width=\"96\" height=\"40\" rx=\"10\" fill=\"#e8f2ff\" stroke=\"#1877f2\"/><text x=\"560.0\" y=\"244\" text-anchor=\"middle\" style=\"fill:#1453a0;font-size:17px\">Leaf 4<\/text><\/svg><p dir=\"ltr\">Upward: Leaf 1 → Router A → Root<\/p><div class=\"tree-candidate\">Dashed: Leaf 2 ⇢ Router B (Candidate)<\/div><\/div><p dir=\"ltr\">Root above Router A and Router B; Leaves 1–2 under A and Leaves 3–4 under B. Leaf 1 → Router A → Root. A dashed alternative link connects Leaf 2 to Router B.<\/p>"}, {"id": "w2-inline-1", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 3", "prompt": "Is confidentiality only about encryption?", "href": "week2.html#slide-3", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. It also involves appropriate access to data.<\/p>"}, {"id": "w2-inline-2", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 4", "prompt": "Can the system trust the value it received? Which objective does this question concern?", "href": "week2.html#slide-4", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Integrity: protect readings, configuration and commands from unauthorized modification.<\/p>"}, {"id": "w2-inline-3", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 7", "prompt": "Can a user and an application have separate identities?", "href": "week2.html#slide-7", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Yes. An application can act on behalf of a signed-in user and also have its own application identity.<\/p>"}, {"id": "w2-inline-4", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 11", "prompt": "Give TWO examples of freshness mechanisms.", "href": "week2.html#slide-11", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Nonces and Counters. Timestamps and Short-Lived Sessions are also valid.<\/p>"}, {"id": "w2-inline-5", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 14", "prompt": "Why must ownership transfer and device reset be designed carefully?", "href": "week2.html#slide-14", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">To prevent old trust from remaining accidentally.<\/p>"}, {"id": "w2-inline-6", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 15", "prompt": "Why is cloned device identity a security problem?", "href": "week2.html#slide-15", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Two physical devices use the same identity and credential, making it difficult for the backend to distinguish the genuine device.<\/p>"}, {"id": "w2-inline-7", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 15", "prompt": "Which concepts are important in the cloned identity scenario?", "href": "week2.html#slide-15", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Identity Uniqueness, Credential Protection, Inventory and Lifecycle Management.<\/p>"}, {"id": "w2-inline-8", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 16", "prompt": "Map the identities in a smart camera or lock ecosystem and their authentication evidence.", "href": "week2.html#slide-16", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Include Owner, Application, Device, Gateway, Cloud Service, Administrator and Installer. Match each claimed identity to suitable account, device or service credentials. Flag identifiers accepted without proof.<\/p>"}, {"id": "w2-inline-9", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 17", "prompt": "Apply CIA to a Smart Lock.", "href": "week2.html#slide-17", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Confidentiality: keep door events private. Integrity: prevent unauthorized command changes. Availability: keep essential lock functions available.<\/p>"}, {"id": "w2-inline-10", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 17", "prompt": "Why does a device need its own identity?", "href": "week2.html#slide-17", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">So the system can distinguish it, authenticate its claims, bind ownership and manage its lifecycle independently of the human account.<\/p>"}, {"id": "w2-inline-11", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 20", "prompt": "Identify Subject, Action and Resource: A technician changes the configuration of Sensor B.", "href": "week2.html#slide-20", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Subject: Technician. Action: Change Configuration. Resource: Sensor B.<\/p>"}, {"id": "w2-inline-12", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 26", "prompt": "Should a temperature sensor have administrative permissions?", "href": "week2.html#slide-26", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. It should have only permissions required for its legitimate function.<\/p>"}, {"id": "w2-inline-13", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 32", "prompt": "Which key is used to create a digital signature?", "href": "week2.html#slide-32", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Private Key.<\/p>"}, {"id": "w2-inline-14", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 32", "prompt": "Which key verifies a digital signature?", "href": "week2.html#slide-32", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">The corresponding Public Key.<\/p>"}, {"id": "w2-inline-15", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 34", "prompt": "Which three access-control mistakes should be avoided?", "href": "week2.html#slide-34", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Assuming authenticated means fully authorized; using one broad administrator role for unrelated tasks; trusting a client resource identifier without checking ownership.<\/p>"}, {"id": "w2-inline-16", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 35", "prompt": "Identify the main identities in the integrated smart-building scenario.", "href": "week2.html#slide-35", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Sensors, Smart Locks, Gateways, Cloud Services, Technicians, Employees and Administrators.<\/p>"}, {"id": "w2-inline-17", "week": 2, "type": "short", "lecture": "w2", "group": "Week 2 · Slide 35", "prompt": "Which identities need authentication in the smart-building scenario?", "href": "week2.html#slide-35", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Entities making requests or participating in trusted communication need appropriate authentication for their roles and interactions.<\/p>"}, {"id": "w3-inline-18", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 4", "prompt": "Which component is responsible for sampling sensor readings?", "href": "week3.html#slide-4", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Microcontroller.<\/p>"}, {"id": "w3-inline-19", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 5", "prompt": "Can a sensor also be a Router Node?", "href": "week3.html#slide-5", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Yes, if it forwards packets from neighboring devices in addition to its own sensing function.<\/p>"}, {"id": "w3-inline-20", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 10", "prompt": "Are a Gateway and a Border Router synonyms?", "href": "week3.html#slide-10", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. Border Router forwards between IP networks; Gateway may translate or aggregate and process data. One appliance may perform both roles.<\/p>"}, {"id": "w3-inline-21", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 13", "prompt": "Why should physical mesh and DODAG diagrams be drawn separately?", "href": "week3.html#slide-13", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Mesh shows possible connectivity; DODAG shows directed logical routing relationships. Not every available link is selected.<\/p>"}, {"id": "w3-inline-22", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 15", "prompt": "Does every CPS require Internet connectivity?", "href": "week3.html#slide-15", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. A CPS links computation and a physical process; its feedback loop may be local.<\/p>"}, {"id": "w3-inline-23", "week": 3, "type": "diagram", "lecture": "w3", "group": "Week 3 · Slide 18", "prompt": "Draw a greenhouse with six leaf sensors, two routers, a gateway, an actuator and a monitoring application. Label telemetry, control and one shared dependency.", "href": "week3.html#slide-18", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Sensors send telemetry through routers and gateway toward monitoring. A controller sends authorized commands toward the actuator. Label an upstream router or gateway as a shared dependency; keep a supported local control decision local during cloud outages.<\/p>"}, {"id": "w3-inline-24", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 24", "prompt": "What does the Objective Function help determine?", "href": "week3.html#slide-24", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Rank calculation and parent selection using routing information and metrics.<\/p>"}, {"id": "w3-inline-25", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 25", "prompt": "Must a new node always send DIS before receiving DIO?", "href": "week3.html#slide-25", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. A node may receive unsolicited DIO advertisements.<\/p>"}, {"id": "w3-inline-26", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 29", "prompt": "Does DAO-ACK prove successful physical actuation?", "href": "week3.html#slide-29", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. It acknowledges a DAO when requested, not sensor-data delivery or actuator completion.<\/p>"}, {"id": "w3-inline-27", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 33", "prompt": "Does an alternative physical link guarantee immediate route recovery?", "href": "week3.html#slide-33", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">No. It must be viable; repair can require control messages, time and energy.<\/p>"}, {"id": "w3-inline-28", "week": 3, "type": "diagram", "lecture": "w3", "group": "Week 3 · Slide 35", "prompt": "Draw one root, three routers and six leaves. Give one leaf two candidate parents and trace an upward reading.", "href": "week3.html#slide-35", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Show root-oriented preferred links and a dashed alternative candidate. A reading follows Leaf → Preferred Router → Root, possibly through intermediate routers. Ranks increase outward; failure requires a viable alternative.<\/p>"}, {"id": "w3-inline-29", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 36", "prompt": "Describe the control-message timeline for a new sensor needing upward and downward communication.", "href": "week3.html#slide-36", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Listen for DIO or send DIS; receive DIO; evaluate candidates, OF and rank constraints; select parent; send upward data. Use DAO for downward reachability and optional DAO-ACK when requested.<\/p>"}, {"id": "w3-inline-30", "week": 3, "type": "short", "lecture": "w3", "group": "Week 3 · Slide 37", "prompt": "Expand RPL, LLN, DODAG, DIO, DIS, DAO, DAO-ACK and OF.", "href": "week3.html#slide-37", "answerOrigin": "study", "answerHTML": "<p dir=\"ltr\">Routing Protocol for Low-Power and Lossy Networks; Low-Power and Lossy Network; Destination-Oriented Directed Acyclic Graph; DODAG Information Object; DODAG Information Solicitation; Destination Advertisement Object; DAO Acknowledgment; Objective Function.<\/p>"}];